function resolveJiejingApiBase(kind, localDefault) {
  const apiKey = kind === "runtime" ? "runtimeApiBase" : "saasApiBase";
  const queryKey = kind === "runtime" ? "runtimeApiBase" : "saasApiBase";
  const storageKey = kind === "runtime" ? "jiejing_runtime_api_base" : "jiejing_saas_api_base";
  const metaName = kind === "runtime" ? "jiejing-runtime-api-base" : "jiejing-saas-api-base";
  const sameOriginBase = inferJiejingSameOriginApiBase(kind, localDefault);
  const preferSameOrigin = kind === "saas" && isPublicJiejingOrigin();
  const storedOverride = normalizeJiejingApiBase(safeStorageValue(storageKey));
  if (storedOverride && !isPlausibleJiejingApiBase(storedOverride, kind)) {
    clearBadJiejingApiBase(storageKey, storedOverride);
  }
  const configSources = preferSameOrigin
    ? [
        safeWindowConfig("JIEJING_CONFIG", apiKey),
        safeWindowConfig("__JIEJING_CONFIG__", apiKey),
        safeQueryParam(queryKey),
        safeMetaContent(metaName),
        sameOriginBase,
        safeStorageValue(storageKey),
        localDefault,
      ]
    : [
        safeWindowConfig("JIEJING_CONFIG", apiKey),
        safeWindowConfig("__JIEJING_CONFIG__", apiKey),
        safeQueryParam(queryKey),
        safeMetaContent(metaName),
        safeStorageValue(storageKey),
        sameOriginBase,
        localDefault,
      ];
  for (const value of configSources) {
    const normalized = normalizeJiejingApiBase(value);
    if (!isPlausibleJiejingApiBase(normalized, kind)) {
      clearBadJiejingApiBase(storageKey, normalized);
      continue;
    }
    if (normalized) return normalized;
  }
  return localDefault;
}

function safeWindowConfig(rootKey, apiKey) {
  try {
    const root = window[rootKey];
    return root && typeof root === "object" ? root[apiKey] : "";
  } catch (error) {
    return "";
  }
}

function safeQueryParam(key) {
  try {
    return new URLSearchParams(window.location.search).get(key) || "";
  } catch (error) {
    return "";
  }
}

function safeMetaContent(name) {
  try {
    return document.querySelector(`meta[name="${name}"]`)?.content || "";
  } catch (error) {
    return "";
  }
}

function safeStorageValue(key) {
  try {
    return localStorage.getItem(key) || "";
  } catch (error) {
    return "";
  }
}

function isPlausibleJiejingApiBase(value, kind = "saas") {
  if (!value) return false;
  try {
    const url = new URL(value, window.location.origin);
    const path = url.pathname || "";
    if (url.search || url.hash) return false;
    if (/\.html?$/i.test(path) || /\/(index|app)\.html/i.test(path)) return false;
    if (!["http:", "https:"].includes(url.protocol)) return false;
    if (kind === "saas" && isPublicJiejingOrigin()) {
      // Public SaaS requests must stay on the current HTTPS origin so a crafted
      // query/config override cannot redirect login credentials to another host.
      if (url.protocol !== "https:") return false;
      if (url.origin !== window.location.origin) return false;
    }
    return true;
  } catch (error) {
    return false;
  }
}

function clearBadJiejingApiBase(storageKey, value) {
  if (!value) return;
  try {
    if (localStorage.getItem(storageKey) === value) localStorage.removeItem(storageKey);
  } catch (error) {
    // Ignore storage cleanup failures; the next source still provides a safe base.
  }
}

function inferJiejingSameOriginApiBase(kind, localDefault) {
  try {
    if (!window.location || window.location.protocol === "file:") return localDefault;
    const host = window.location.hostname;
    if (host === "localhost" || host === "127.0.0.1" || host === "::1") return localDefault;
    return kind === "saas" ? window.location.origin : localDefault;
  } catch (error) {
    return localDefault;
  }
}

function defaultJiejingRuntimeApiBase() {
  try {
    if (!window.location || window.location.protocol === "file:") return "http://127.0.0.1:8765";
    const host = window.location.hostname;
    if (host === "localhost" || host === "127.0.0.1" || host === "::1") return "http://127.0.0.1:8765";
  } catch (error) {
    return "http://127.0.0.1:8765";
  }
  return "";
}

function resolveJiejingBooleanConfig(key, fallback) {
  const storageKey = key === "saasDemoBootstrapEnabled" ? "jiejing_saas_demo_bootstrap_enabled" : key;
  const metaName = key === "saasDemoBootstrapEnabled" ? "jiejing-saas-operator-bootstrap" : key;
  const legacyMetaName = key === "saasDemoBootstrapEnabled" ? "jiejing-saas-demo-bootstrap" : "";
  const values = [
    safeWindowConfig("JIEJING_CONFIG", key),
    safeWindowConfig("__JIEJING_CONFIG__", key),
    safeQueryParam(key),
    safeMetaContent(metaName),
    legacyMetaName ? safeMetaContent(legacyMetaName) : "",
    safeStorageValue(storageKey),
  ];
  for (const value of values) {
    const parsed = parseJiejingBoolean(value);
    if (parsed !== null) return parsed;
  }
  return Boolean(fallback);
}

function parseJiejingBoolean(value) {
  if (value === true || value === false) return value;
  const normalized = String(value ?? "").trim().toLowerCase();
  if (!normalized) return null;
  if (["true", "1", "yes", "on", "enabled"].includes(normalized)) return true;
  if (["false", "0", "no", "off", "disabled"].includes(normalized)) return false;
  return null;
}

function defaultJiejingDemoBootstrapEnabled() {
  try {
    if (!window.location) return false;
    if (window.location.protocol === "file:") return true;
    const host = window.location.hostname;
    return host === "localhost" || host === "127.0.0.1" || host === "::1";
  } catch (error) {
    return false;
  }
}

function isPublicJiejingOrigin() {
  try {
    if (!window.location || window.location.protocol === "file:") return false;
    const host = window.location.hostname;
    return host !== "localhost" && host !== "127.0.0.1" && host !== "::1";
  } catch (error) {
    return false;
  }
}

function isLocalJiejingOrigin() {
  try {
    if (!window.location || window.location.protocol === "file:") return false;
    const host = window.location.hostname;
    return host === "localhost" || host === "127.0.0.1" || host === "::1";
  } catch (error) {
    return false;
  }
}

function localQaForcesSaasPublicMvpMode() {
  if (!isLocalJiejingOrigin() || !isProtectedSaasAppRoute()) return false;
  const qaMode = safeQueryParam("qa");
  return qaMode === "public-saas" || qaMode === "listing-v2-workbench" || qaMode === "ai-ceo-market-report-handoff";
}

function isSaasPublicMvpMode() {
  try {
    if (window.__JIEJING_FORCE_PUBLIC_MVP__ === true) return true;
    if (localQaForcesSaasPublicMvpMode()) return true;
    if (isPublicJiejingOrigin()) return true;
    if (!isProtectedSaasAppRoute()) return false;
    const hasSession =
      Boolean(sessionStorage.getItem(saasStorageKeys.token)) ||
      Boolean(localStorage.getItem(saasStorageKeys.sessionHint)) ||
      Boolean(localStorage.getItem(saasStorageKeys.storeId)) ||
      Boolean(safeStorageValue("jiejing_saas_api_base"));
    return hasSession;
  } catch (error) {
    return isPublicJiejingOrigin();
  }
}

function isProtectedSaasAppRoute() {
  try {
    const params = new URLSearchParams(window.location.search);
    return window.location.pathname.endsWith("/app.html") || params.get("start") === "app" || params.get("onboarded") === "1";
  } catch (error) {
    return false;
  }
}

const saasRealWorkbenchViews = new Set(["cockpit", "workflow", "product", "media", "bulk", "confirm", "service", "connect"]);
const saasProtectedViewAliases = {
  ai: "cockpit",
  "ai-ceo": "cockpit",
  aiceo: "cockpit",
  ceo: "cockpit",
  listing: "product",
  listings: "product",
  product_listing: "product",
  productlisting: "product",
  material: "media",
  materials: "media",
  assets: "media",
  asset: "media",
  batch: "bulk",
  decisions: "confirm",
  decision: "confirm",
  confirmation: "confirm",
  settings: "connect",
  account: "connect",
  support: "service",
  orders: "service",
  activity: "cockpit",
  report: "cockpit",
  reports: "cockpit",
};

function normalizeSaasProtectedView(view = "cockpit") {
  let nextView = String(view || "cockpit").trim().toLowerCase();
  nextView = saasProtectedViewAliases[nextView] || nextView;
  if (nextView === "workflow" && !isSaasPublicMvpMode()) nextView = "product";
  if (isSaasPublicMvpMode() && !saasRealWorkbenchViews.has(nextView)) return "cockpit";
  if (!/^[a-z0-9_-]+$/i.test(nextView)) return "cockpit";
  if (!document.querySelector(`#view-${nextView}`)) return "cockpit";
  return nextView;
}

function rememberSaasStartupRequestedView(view = "") {
  const nextView = normalizeSaasProtectedView(view || "cockpit");
  state.saasStartupRequestedView = nextView;
  return nextView;
}

function activeSaasRefreshView(fallback = "cockpit") {
  const currentView = normalizeSaasProtectedView(state.view || fallback);
  const startupView = state.saasStartupRequestedView
    ? normalizeSaasProtectedView(state.saasStartupRequestedView)
    : "";
  return startupView && currentView === "cockpit" ? startupView : currentView || startupView || normalizeSaasProtectedView(fallback);
}

function consumeSaasStartupRequestedView(fallback = "cockpit") {
  const nextView = activeSaasRefreshView(fallback);
  state.saasStartupRequestedView = "";
  return nextView;
}

function redirectToSaasLogin(reason = "login_required") {
  if (state.saasManualLogout && reason !== "logout") return false;
  try {
    const loginUrl = new URL("./index.html", window.location.href);
    loginUrl.searchParams.set("reason", reason);
    loginUrl.hash = "ai-ceo-workbench";
    window.location.replace(loginUrl.toString());
    return true;
  } catch (error) {
    return false;
  }
}

function isSaasUnrecoverableSessionError(error = null) {
  const status = Number(error?.status || error?.payload?.status || 0) || 0;
  if (status === 401 || error?.code === "saas_session_expired") return true;
  const raw = String(error?.message || error?.detail || error || "").toLowerCase();
  return /missing bearer token|session expired|session_expired|session_refresh_invalid|invalid access token|access token expired|token has expired|unauthorized session/.test(raw);
}

function handleSaasUnrecoverableSession(error = null) {
  if (!isSaasUnrecoverableSessionError(error)) return false;
  const firstFailure = state.saasSessionExpiryHandled !== true;
  state.saasSessionExpiryHandled = true;
  stopSaasAiCeoCrossDeviceSync();
  clearSaasSessionFromStorage({ preserveCeoThread: true, preservePendingListingGeneration: true });
  resetSaasProtectedWorkbenchState();
  state.saasConnected = false;
  state.saasProtectedStateReady = false;
  state.saasError = "捷境登录已失效，请重新登录。当前页面没有继续调用 AI、素材或 eBay；本机对话草稿已保留。";
  const shouldRedirectToLogin = isSaasPublicMvpMode() && isProtectedSaasAppRoute();
  if (shouldRedirectToLogin) {
    if (!state.saasSessionExpiryRedirected) {
      state.saasSessionExpiryRedirected = redirectToSaasLogin("session_expired") === true;
    }
  } else if (firstFailure) {
    openAuth("login");
  }
  try {
    syncSaasPublicMvpMode();
    renderSaasBackendPanel();
    renderGlobalLoopWorkbench();
    renderStoreContext();
  } catch (renderError) {
    // Session termination must still complete if a stale page cannot re-render its old shell.
  }
  if (firstFailure) {
    try {
      showActionToast("捷境登录已失效，请重新登录；本次未执行真实动作。");
    } catch (toastError) {
      // A stale shell can still be redirected even if its toast host no longer exists.
    }
  }
  return true;
}

function syncSaasPublicMvpMode() {
  if (!document?.body) return;
  const enabled = isSaasPublicMvpMode();
  const hasSessionCandidate = hasSaasProtectedSessionCandidate();
  document.body.classList.toggle("saas-public-mvp", enabled);
  document.body.classList.toggle("saas-mvp-login-required", enabled && !state.saasConnected && !hasSessionCandidate);
}

function normalizeJiejingApiBase(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  return raw.replace(/\/+$/, "");
}

