function getActiveWizardFields() {
  const fields = stageWizardFields[state.dna.merchantStage] || stageWizardFields.newbie;
  return state.preselectedFromLanding ? fields.filter((field) => field !== "merchantStage") : fields;
}

function getActiveWizard() {
  const flowFields = getActiveWizardFields();
  return flowFields
    .map((field) => wizard.find((step) => step.field === field))
    .filter(Boolean);
}

function getWizardLength() {
  return getActiveWizard().length;
}

function clampWizardStep() {
  state.wizardStep = Math.max(0, Math.min(state.wizardStep, getWizardLength() - 1));
}

function getWizardStep(index = state.wizardStep) {
  const activeWizard = getActiveWizard();
  const base = activeWizard[Math.max(0, Math.min(index, activeWizard.length - 1))];
  if (!base) return base;
  const override = stageWizardOverrides[state.dna.merchantStage]?.[base.field];
  return override ? { ...base, ...override, options: override.options || base.options } : base;
}

