function productizeJiejingProductCopy(value = "") {
  let output = String(value ?? "");
  for (const [pattern, replacement] of jiejingProductCopyReplacements) {
    output = output.replace(pattern, replacement);
  }
  return output;
}

function merchantConversationText(value = "") {
  return String(value ?? "")
    .replace(legacyExecutionPairPattern, "捷境系统")
    .replace(legacyExecutionBrandPattern, "捷境系统")
    .replace(legacyExecutionBrandLowerPattern, "internal-runtime")
    .replace(/patch_work\/internal-runtime-skills/gi, "内部技能包")
    .replace(/patch_work\/[^\s`'"]+/gi, "内部资料")
    .replace(/output\/JIEJING_[^\s`'"]+/gi, "内部运行记录")
    .replace(/[A-Z]:\\Users\\[^\\]+\\Documents\\Codex\\[^\\]+\\/gi, "")
    .replace(/\/mnt\/c\/Users\/[^/]+\/Documents\/Codex\/[^/]+\//gi, "");
}

function showActionToast(text) {
  const toast = document.querySelector("#actionToast");
  if (!toast) return;
  window.clearTimeout(actionToastTimer);
  toast.textContent = productizeJiejingProductCopy(text);
  toast.hidden = false;
  toast.classList.add("is-visible");
  actionToastTimer = window.setTimeout(() => {
    toast.classList.remove("is-visible");
    window.setTimeout(() => {
      toast.hidden = true;
    }, 180);
  }, 2600);
}

const cockpitMarketProfiles = {};

function cockpitMarketProfile(draft) {
  if (isSaasPublicMvpMode() && (!draft || isLegacySampleMediaDraftKey(draft.id))) return null;
  return cockpitMarketProfiles[draft?.id] || cockpitMarketProfiles.incense;
}
function activeListingDraft() {
  const matched = listingDraftCatalog.find((draft) => draft.id === state.activeListingDraft) || null;
  if (isSaasPublicMvpMode() && (!matched || isLegacySampleMediaDraftKey(matched.id))) return null;
  return matched || listingDraftCatalog[0];
}

function activeCockpitMarketDraft() {
  const matched = listingDraftCatalog.find((draft) => draft.id === state.activeCockpitMarketDraft) || null;
  if (isSaasPublicMvpMode() && (!matched || isLegacySampleMediaDraftKey(matched.id))) return null;
  return matched || listingDraftCatalog[0];
}

function cockpitMarketReportItem(draft, keywords = [], fallbackIndex = 0) {
  const report = Array.isArray(draft.report) ? draft.report : [];
  const found = report.find(([title]) => keywords.some((keyword) => String(title).includes(keyword)));
  return found || report[fallbackIndex] || ["市场判断", draft.conclusion || "等待 AI CEO 汇总。"];
}

function cockpitMarketTone(draft) {
  const statusText = `${draft.status || ""}${draft.badge || ""}${draft.risk || ""}`;
  if (/高|暂不|阻断|侵权/.test(statusText)) return "is-blocked";
  if (/待补|待确认|中/.test(statusText)) return "is-waiting";
  return "is-ready";
}

function cockpitMarketMetricLabel(draft) {
  const score = Number(draft.score || 0);
  if (score >= 84) return "优先测试";
  if (score >= 78) return "可小批测试";
  if (score >= 70) return "先补资料";
  return "暂缓";
}

