function selectCockpitMarketDraft(id) {
  const draft = listingDraftCatalog.find((item) => item.id === id);
  if (!draft) return;
  const previousY = window.scrollY;
  const listScroll = document.querySelector("#view-cockpit .cockpit-market-list")?.scrollLeft || 0;
  state.activeCockpitMarketDraft = id;
  renderCockpitMarketBoard();
  requestAnimationFrame(() => {
    const list = document.querySelector("#view-cockpit .cockpit-market-list");
    if (list) list.scrollLeft = listScroll;
    window.scrollTo({ top: previousY, behavior: "auto" });
  });
}

function listingCategoryProfile(draft) {
  const draftId = String(draft?.id || "");
  const matched = listingCategoryProfiles[draftId] || null;
  if (isSaasPublicMvpMode() && (!matched || isLegacySampleMediaDraftKey(draftId))) return null;
  return matched || listingCategoryProfiles.incense;
}

function listingDraftStatusClass(draft) {
  if (draft.status.includes("待补")) return "is-waiting";
  if (draft.risk.includes("高")) return "is-blocked";
  return "";
}

function renderListingDraftQueue() {
  return listingDraftCatalog
    .map((draft) => {
      const isActive = draft.id === state.activeListingDraft;
      return `
        <button class="product-queue-row ${isActive ? "is-active" : ""} ${listingDraftStatusClass(draft)}" type="button" data-product-draft="${escapeHtml(draft.id)}" data-product-row-jump="report" aria-pressed="${isActive}">
          <img src="${escapeHtml(draft.thumb)}" alt="${escapeHtml(draft.titleCn)}预览图" loading="lazy">
          <span>
            <b>${escapeHtml(draft.titleCn)}</b>
            <small>${escapeHtml(draft.status)} · ${escapeHtml(draft.badge)} · ${escapeHtml(draft.titleEn)}</small>
          </span>
          <em>${escapeHtml(draft.score)}</em>
        </button>
      `;
    })
    .join("");
}

function getBulkHandoffDrafts() {
  if (isSaasPublicMvpMode() && Array.isArray(state.saasBulkAcceptedCandidates) && state.saasBulkAcceptedCandidates.length) {
    return state.saasBulkAcceptedCandidates.map((candidate, index) => ({
      id: `saas-bulk-${candidate.candidate_id || index + 1}`,
      titleCn: candidate.name,
      titleEn: candidate.name,
      status: "批量候选草稿",
      badge: candidate.source_type === "manual" ? "商家资料" : "AI CEO 调研",
      score: Number(candidate.score || 0),
      conclusion: (candidate.reasons || []).join("；") || "已进入批量候选草稿，等待补货源事实。",
      next: "补价格、图片、物流、类目和店铺政策后再生成发布确认单。",
      missing: candidate.missing_facts || [],
      risk: "真实发布仍需确认",
    }));
  }
  return bulkHandoffDraftIds
    .map((id) => bulkListingDraftCatalog.find((draft) => draft.id === id))
    .filter(Boolean);
}

function bindSaasMediaManifestPreviewEvents(view = document.querySelector("#view-media")) {
  if (!view || view.dataset.saasManifestPreviewEventsBound) return;
  view.dataset.saasManifestPreviewEventsBound = "1";
  view.addEventListener("click", (event) => {
    const reworkButton = event.target.closest("[data-media-rework-job]");
    if (reworkButton && view.contains(reworkButton)) {
      void retrySaasMediaAssetJob(reworkButton.dataset.mediaReworkJob || "", reworkButton);
      return;
    }
    const card = event.target.closest(".saas-generated-assets-grid [data-asset-preview]");
    if (card && view.contains(card)) openAssetPreview(card.dataset.assetPreview);
  });
  view.addEventListener("keydown", (event) => {
    if (event.key !== "Enter" && event.key !== " ") return;
    const card = event.target.closest(".saas-generated-assets-grid [data-asset-preview]");
    if (!card || !view.contains(card)) return;
    event.preventDefault();
    openAssetPreview(card.dataset.assetPreview);
  });
}

function bindRestoredMediaStudioEvents() {
  const view = document.querySelector("#view-media");
  if (!view) return;
  const bindOnce = (element, type, handler, key = `${type}HandlerBound`) => {
    if (!element || element.dataset[key]) return;
    element.dataset[key] = "1";
    element.addEventListener(type, handler);
  };
  const mediaSourceFileInput = view.querySelector("#mediaSourceFileInput");
  bindOnce(view.querySelector("#mediaBrowseFileButton"), "click", () => mediaSourceFileInput?.click());
  bindOnce(mediaSourceFileInput, "change", (event) => {
    void handleMediaSourceFile(event.target.files?.[0], event);
    event.target.value = "";
  });
  const mediaDropPanel = view.querySelector("#mediaNewTaskDropPanel");
  if (mediaDropPanel && !mediaDropPanel.dataset.dropHandlerBound) {
    mediaDropPanel.dataset.dropHandlerBound = "1";
    ["dragenter", "dragover"].forEach((type) => {
      mediaDropPanel.addEventListener(type, (event) => {
        event.preventDefault();
        mediaDropPanel.classList.add("is-dragging");
      });
    });
    ["dragleave", "drop"].forEach((type) => {
      mediaDropPanel.addEventListener(type, (event) => {
        event.preventDefault();
        mediaDropPanel.classList.remove("is-dragging");
      });
    });
    mediaDropPanel.addEventListener("drop", (event) => void handleMediaSourceFile(event.dataTransfer?.files?.[0], event));
  }
  view.querySelectorAll(".media-channel-card").forEach((button) => {
    bindOnce(button, "click", () => {
      const mode = button.dataset.mediaChannel || "flow";
      keepViewportStill(() => {
        if (mode === "independent") {
          setMediaNewTaskMode();
          return;
        }
        const activeTab = view.querySelector(".media-project-tab.is-active") || view.querySelector(".media-project-tab");
        if (activeTab) syncMediaProjectDraft(activeTab);
        else setMediaChannelMode("flow");
      });
      showActionToast(
        mode === "independent"
          ? "已切换到独立上传：只生成本次素材草稿，不自动进入正式 Listing。"
          : "已切换到流程导入：只处理已有店铺资料、报告或 Listing 草稿的素材任务。",
      );
    });
  });
  bindOnce(view.querySelector(".media-project-tabs"), "click", (event) => {
    const button = event.target.closest(".media-project-tab");
    if (button) syncMediaProjectDraft(button);
  });
  view.querySelectorAll(".media-template-card").forEach((button) => bindOnce(button, "click", () => applyMediaTemplate(button)));
  [
    "#mediaPlatformSelect",
    "#mediaSizeSelect",
    "#mediaCountSelect",
    "#mediaTypeSelect",
    "#mediaSceneSelect",
    "#mediaFidelitySelect",
    "#mediaGenerationTierSelect",
    "#mediaTextRuleSelect",
    "#mediaVideoPresetSelect",
    "#mediaVoiceSelect",
  ].forEach((selector) => bindOnce(view.querySelector(selector), "change", () => syncMediaRequirementSummary()));
  bindOnce(view.querySelector(".media-canvas-grid"), "click", (event) => {
    const card = event.target.closest("[data-asset-preview]");
    if (card) openAssetPreview(card.dataset.assetPreview);
  });
  bindSaasMediaManifestPreviewEvents(view);
  bindOnce(view.querySelector("#mediaVideoDemo"), "click", () => {
    const text = "用现有商品图生成 6 秒或 10 秒产品展示视频的脚本与分镜，包含封面、字幕和镜头顺序，先不要发布。";
    addCeoMessage(text, "视频脚本与分镜已经生成到素材工坊；只有素材生成服务返回真实视频文件后，页面才会显示视频成片。");
    runMediaGenerationFromCeo(text);
    openAssetPreview("video");
  });
  bindOnce(view.querySelector("#mediaTalkDemo"), "click", () => {
    const text = "根据产品图和卖点生成英语短视频脚本、字幕、封面和分镜，风险点送决策中心。";
    addCeoMessage(text, "短视频脚本和分镜已生成，涉及功效、授权和发布动作的部分会留在决策中心。");
    runMediaGenerationFromCeo(text);
    openAssetPreview("video");
  });
  bindOnce(view.querySelector("#mediaGenerateImagesDraft"), "click", handleMediaGenerateImagesDraftClick);
  bindOnce(view.querySelector("#mediaScriptDraft"), "click", handleMediaScriptDraftClick);
  bindOnce(view.querySelector("#mediaConfirmDraft"), "click", handleSaasMediaWritebackClick);
}

function saasMediaReportRows(ctx = saasMerchantWorkbenchContext()) {
  const activeMediaDraft = String(state.activeMediaDraft || state.activeListingDraft || "");
  const activeComposer = state.saasListingComposerDraft || null;
  const activeListing = typeof activeListingDraft === "function" ? activeListingDraft() : null;
  const activeReport =
    activeComposer && activeMediaDraft
      ? {
          report_id: `local_${activeMediaDraft}`,
          report_type: activeComposer.source_type === "bulk_handoff" ? "bulk.handoff" : "product.listing",
          title: activeComposer.product || activeComposer.title || activeListing?.titleCn || "当前商品素材任务",
          created_at: activeComposer.created_at || new Date().toISOString(),
          local_media_draft_id: activeMediaDraft,
          report: {
            summary: "从 Listing 草稿进入素材工坊；素材通过后回写 Listing。",
          },
        }
      : null;
  const reports = [
    activeReport,
    latestSaasReportByTypes(["listing.package", "product.listing"]),
    latestSaasReportByTypes(["asset.brief", "media.brief", "asset.manifest"]),
    latestSaasReportByTypes(["ai_ceo.market_research", "market.report", "market.data_packet"]),
  ].filter(Boolean);
  const seen = new Set();
  const uniqueReports = reports.filter((report) => {
    const key = report.report_id || `${report.report_type}:${report.created_at || ""}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
  return uniqueReports;
}

function saasMediaReportSummary(record = null, ctx = saasMerchantWorkbenchContext()) {
  if (!record) return "等待商品草稿、图片需求或商家来源图。";
  return saasReportSummary(record) || record.report?.summary || "素材任务已写回素材工坊。";
}

function isLegacySampleMediaDraftKey(key) {
  return ["incense", "backflow-incense", "zen-incense"].includes(String(key || ""));
}

function isLegacySampleProductLabel(value) {
  const normalized = String(value || "").trim().toLowerCase();
  return [
    "jj-backflow-incense-debug-full",
    "jj-backflow-incense-debug-min",
    "jj-draft-proof-20260815-05",
    "assets/backflow-incense-",
    "source-backflow-incense-burner",
  ].some((marker) => normalized.includes(marker));
}

function activeMediaDraftProfileForDisplay() {
  const draftKey = String(state.activeMediaDraft || "");
  if (isSaasPublicMvpMode() && (!draftKey || isLegacySampleMediaDraftKey(draftKey))) {
    return null;
  }
  return mediaDraftAssetProfiles[draftKey] || null;
}

function activeMediaDraftProductNameForDisplay(ctx = saasMerchantWorkbenchContext()) {
  const profile = activeMediaDraftProfileForDisplay();
  if (profile?.name) return profile.name;
  const composer = state.saasListingComposerDraft || {};
  const activeListingRaw = typeof activeListingDraft === "function" ? activeListingDraft() : null;
  const activeListing =
    isSaasPublicMvpMode() && isLegacySampleMediaDraftKey(activeListingRaw?.id || state.activeListingDraft)
      ? null
      : activeListingRaw;
  const report = latestSaasReportByTypes(["listing.package", "product.listing", "ai_ceo.market_research", "market.report"]);
  const candidates = [
    composer.product,
    composer.title,
    activeListing?.titleCn,
    saasProductLabelForRecord(report),
    ctx.productLabel,
  ];
  const selected = candidates.find((value) => {
    const clean = publicRuntimeText(value || "").trim();
    return clean && !isLegacySampleProductLabel(clean);
  });
  return publicRuntimeText(selected || "当前商品");
}

const SAAS_MEDIA_LISTING_PROJECT_MATCH_CONTRACT = "media_asset_job_product_mismatch_blocked_v1";

function saasNormalizeListingProjectIdentity(value = null) {
  const raw = value && typeof value === "object" ? value : {};
  const clean = (field, limit, alias = "") => {
    const text = publicRuntimeText(raw[field] || (alias ? raw[alias] : "")).trim().slice(0, limit);
    return /^[A-Za-z0-9._:-]+$/.test(text) ? text : "";
  };
  const key = clean("key", 160);
  if (!key) return null;
  return {
    key,
    source_report_id: clean("source_report_id", 160, "source_id"),
    candidate_id: clean("candidate_id", 120),
  };
}

function saasListingProjectIdentityFromReport(record = {}) {
  const payload = record?.report && typeof record.report === "object" ? record.report : {};
  const candidates = [
    record?.listing_project_identity,
    payload.listing_project_identity,
    payload.merchant_product_fact_packet?.listing_project_identity,
    payload.sections?.listing_project_identity,
  ];
  for (const candidate of candidates) {
    const identity = saasNormalizeListingProjectIdentity(candidate);
    if (identity?.key) return identity;
  }
  return null;
}

function saasCurrentListingProjectIdentity(draft = state.saasListingComposerDraft) {
  const current = draft && typeof draft === "object" ? draft : {};
  const structuredIdentity = saasNormalizeListingProjectIdentity(current.listing_project_identity);
  const selectedCandidate = current.selected_product_candidate && typeof current.selected_product_candidate === "object"
    ? current.selected_product_candidate
    : {};
  const explicitKey = structuredIdentity?.key || publicRuntimeText(current.listing_project_key || "").trim().slice(0, 160);
  const activeListingRaw = typeof activeListingDraft === "function" ? activeListingDraft() : null;
  const activeListing =
    isSaasPublicMvpMode() && isLegacySampleMediaDraftKey(activeListingRaw?.id || state.activeListingDraft)
      ? null
      : activeListingRaw;
  const productCandidates = [
    selectedCandidate.name,
    current.product,
    current.title,
    current.fields?.title,
    activeListing?.titleCn,
  ];
  const product = productCandidates.find((value) => saasIsConcreteProductLabel(value)) || "";
  const sourceReportId = structuredIdentity
    ? structuredIdentity.source_report_id
    : publicRuntimeText(current.source_report_id || current.source_media_job_id || "").slice(0, 160);
  const candidateId = structuredIdentity
    ? structuredIdentity.candidate_id
    : publicRuntimeText(selectedCandidate.candidate_id || "").slice(0, 120);
  const normalizedProduct = publicRuntimeText(product).toLowerCase().replace(/[^a-z0-9\u4e00-\u9fff]+/g, "");
  if (!explicitKey && !sourceReportId && !candidateId && !normalizedProduct) {
    return { key: "", product: "", source_report_id: "", source_id: "", candidate_id: "" };
  }
  const keySeed = sourceReportId || candidateId
    ? [sourceReportId, candidateId].join("|")
    : [current.source_type || "listing", normalizedProduct].join("|");
  return {
    key: explicitKey || `listing-project-${Math.abs(hashString(keySeed)).toString(16)}`,
    product: publicRuntimeText(product).slice(0, 120),
    source_report_id: sourceReportId,
    source_id: sourceReportId,
    candidate_id: candidateId,
  };
}

function resetSaasListingPublishEvidenceForNewProject() {
  setSaasAiCeoTaskContextState("plain_consultation", false);
  state.saasLastPublishReadiness = null;
  state.saasLastPublishConfirmationEvidence = null;
  state.saasPreflightResults = [];
  state.saasPreTestCheck = null;
}

function saasBulkHandoffAttempt(candidate = {}, previous = {}) {
  const candidateId = String(candidate.candidate_id || "").trim();
  const retryCount = Number(previous.retry_count || 0);
  const name = saasCleanMarketCandidateName(candidate.name || "");
  const retryableFailure = Boolean(candidate.handoff_error) && candidate.handoff_retryable !== false;
  if (!candidateId || !saasIsConcreteProductLabel(name)) {
    return {
      candidate_id: candidateId || `invalid-${Date.now()}`,
      name: name || "未识别商品",
      status: "failed",
      error_reason: "缺少明确商品名，无法建立 Listing 草稿。",
      retryable: false,
      retry_count: retryCount,
    };
  }
  if (candidate.handoff_error && !(retryCount > 0 && retryableFailure)) {
    return {
      candidate_id: candidateId,
      name,
      status: "failed",
      error_reason: publicRuntimeText(candidate.handoff_error).slice(0, 180) || "草稿转换暂时失败。",
      retryable: retryableFailure,
      retry_count: retryCount,
    };
  }
  try {
    return {
      candidate_id: candidateId,
      name,
      status: "succeeded",
      error_reason: "",
      retryable: false,
      retry_count: retryCount,
      listing_draft: saasBulkCandidateToListingDraft({ ...candidate, name }),
    };
  } catch (error) {
    return {
      candidate_id: candidateId,
      name,
      status: "failed",
      error_reason: publicRuntimeText(error?.message || error).slice(0, 180) || "草稿转换暂时失败。",
      retryable: true,
      retry_count: retryCount,
    };
  }
}

function executeSaasBulkHandoffBatch(candidates = []) {
  const items = (Array.isArray(candidates) ? candidates : []).map((candidate) => saasBulkHandoffAttempt(candidate));
  const succeeded = items.filter((item) => item.status === "succeeded").length;
  const failed = items.filter((item) => item.status === "failed").length;
  state.saasBulkBatchRun = {
    contract_version: "2026-07-11-bulk-partial-success-v1",
    run_id: `bulk-run-${Date.now()}`,
    status: failed && succeeded ? "partial_success" : failed ? "failed" : "completed",
    paused: false,
    total: items.length,
    succeeded,
    failed,
    items,
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
    real_platform_writes_enabled: false,
  };
  state.saasBulkListingDrafts = items.filter((item) => item.status === "succeeded").map((item) => item.listing_draft);
  return state.saasBulkBatchRun;
}

function renderSaasBulkBatchRunPanel() {
  const run = state.saasBulkBatchRun && typeof state.saasBulkBatchRun === "object" ? state.saasBulkBatchRun : null;
  if (!run) return "";
  const statusLabel = {
    completed: "本批草稿已完成",
    partial_success: "部分完成，失败项可单独重试",
    failed: "本批未生成草稿",
    paused: "批次已暂停",
  }[run.paused ? "paused" : run.status] || "批次处理中";
  return `
    <section class="saas-bulk-run-panel is-${escapeHtml(run.paused ? "paused" : run.status || "pending")}" data-bulk-run-contract="bulk_partial_success_pause_retry_v1" aria-label="批次执行结果">
      <div class="saas-bulk-run-head">
        <div><span>本批执行</span><strong>${escapeHtml(statusLabel)}</strong><p>成功项保留草稿，失败项不会拖回整批；真实发布仍在确认中心。</p></div>
        <div class="saas-bulk-run-counts"><span>成功 ${escapeHtml(String(run.succeeded || 0))}</span><span>失败 ${escapeHtml(String(run.failed || 0))}</span></div>
      </div>
      <div class="saas-bulk-run-items">
        ${(run.items || [])
          .map(
            (item) => `
              <article class="is-${escapeHtml(item.status || "pending")}">
                <div><span>${item.status === "succeeded" ? "草稿已生成" : "需要处理"}</span><strong>${escapeHtml(item.name || "当前候选")}</strong></div>
                <p>${escapeHtml(item.status === "succeeded" ? "可继续补 Listing 字段和素材。" : item.error_reason || "请补资料后重试。")}</p>
                <div class="button-row">
                  ${item.status === "succeeded" ? `<button class="secondary-action" type="button" data-bulk-action="open-bulk-item" data-bulk-item="${escapeHtml(item.candidate_id || "")}">打开草稿</button>` : ""}
                  ${item.status === "failed" && item.retryable ? `<button class="secondary-action" type="button" data-bulk-action="retry-bulk-item" data-bulk-item="${escapeHtml(item.candidate_id || "")}">仅重试此项</button>` : ""}
                </div>
              </article>`,
          )
          .join("")}
      </div>
    </section>
  `;
}

function retrySaasBulkHandoffItem(candidateId = "") {
  const run = state.saasBulkBatchRun;
  if (!run || run.paused) {
    showActionToast(run?.paused ? "批次已暂停，恢复后再重试。" : "还没有可重试的批次记录。");
    return false;
  }
  const candidate = (state.saasBulkCandidates || []).find((item) => String(item?.candidate_id || "") === String(candidateId));
  const index = (run.items || []).findIndex((item) => String(item?.candidate_id || "") === String(candidateId));
  if (!candidate || index < 0) return false;
  const previous = run.items[index];
  const retried = saasBulkHandoffAttempt(candidate, { retry_count: Number(previous.retry_count || 0) + 1 });
  run.items[index] = retried;
  run.succeeded = run.items.filter((item) => item.status === "succeeded").length;
  run.failed = run.items.filter((item) => item.status === "failed").length;
  run.status = run.failed && run.succeeded ? "partial_success" : run.failed ? "failed" : "completed";
  run.updated_at = new Date().toISOString();
  state.saasBulkListingDrafts = run.items.filter((item) => item.status === "succeeded").map((item) => item.listing_draft);
  state.saasBulkAcceptedCandidates = (state.saasBulkCandidates || []).filter((item) =>
    run.items.some((runItem) => runItem.status === "succeeded" && runItem.candidate_id === item.candidate_id),
  );
  state.bulkApprovedCount = run.succeeded;
  renderBulkFactory();
  showActionToast(retried.status === "succeeded" ? `“${retried.name}”已重试成功，其他草稿未受影响。` : `“${retried.name}”仍未完成，请先补资料。`);
  return retried.status === "succeeded";
}

function openSaasBulkHandoffItem(candidateId = "") {
  const runItem = (state.saasBulkBatchRun?.items || []).find(
    (item) => item.status === "succeeded" && String(item.candidate_id || "") === String(candidateId),
  );
  if (!runItem?.listing_draft) return false;
  state.saasListingComposerDraft = runItem.listing_draft;
  resetSaasListingPublishEvidenceForNewProject();
  state.saasListingComposerInput = [runItem.name, ...(runItem.listing_draft.selected_product_candidate?.reasons || [])].filter(Boolean).join("\n");
  state.saasListingSourceMode = "bulk_handoff";
  state.activeListingDraft = "";
  state.activeMediaDraft = `saas-bulk-${runItem.candidate_id}`;
  state.sourceHandoffDraft = state.activeMediaDraft;
  state.activeFlowKey = "product";
  setView("product", { preserveFlowKey: true });
  renderProductListingCenter();
  setProductInlineFeedback(`已打开“${runItem.name}”。先补价格、图片、物流、类目和店铺政策，再生成发布确认单。`);
  return true;
}

