function renderMediaProjectTabs() {
  const view = document.querySelector("#view-media");
  const hadTabs = Boolean(view?.querySelector(".media-project-tabs"));
  restorePreservedViewMarkup("media", ".media-project-tabs");
  bindSaasMediaManifestPreviewEvents(view);
  if (!hadTabs) bindRestoredMediaStudioEvents();
  if (isSaasPublicMvpMode()) {
    renderSaasMediaStudioStatus();
    return;
  }
  const tabs = document.querySelector(".media-project-tabs");
  if (!tabs) return;
  tabs.innerHTML = listingDraftCatalog
    .map((draft, index) => {
      const isActive = draft.id === state.activeMediaDraft;
      const note = (draft.mediaPlan || []).map((item) => item[1]).slice(0, 3).join("、") || "主图、场景图、详情页";
      const gap = (draft.missing || []).slice(0, 4).join("、") || "尺寸、重量、材质";
      const status = draft.id.startsWith("bulk-")
        ? "批量铺货接力 · 待素材"
        : `${draft.status} · ${draft.badge}`;
      return `
        <button class="media-project-tab ${isActive ? "is-active" : ""}" type="button"
          data-media-draft="${escapeHtml(draft.id)}"
          data-media-draft-title="${escapeHtml(draft.titleCn)}"
          data-media-draft-note="${escapeHtml(note)}"
          data-media-draft-gap="${escapeHtml(gap)}"
          data-media-draft-status="${escapeHtml(status)}">
          <span>${String(index + 1).padStart(2, "0")}</span>
          <strong>${escapeHtml(draft.titleCn)}</strong>
          <small>${escapeHtml(draft.titleEn)}</small>
          <em>${draft.id.startsWith("bulk-") ? "批量接力" : "流程导入"}</em>
        </button>
      `;
    })
    .join("");
  const activeTab =
    Array.from(tabs.querySelectorAll(".media-project-tab")).find(
      (button) => button.dataset.mediaDraft === state.activeMediaDraft,
    ) || tabs.querySelector(".media-project-tab");
  if (activeTab) syncMediaProjectDraft(activeTab);
}

