function getPublishDraft() {
  return listingDraftCatalog.find((draft) => draft.id === state.publishFlow.draftId) || activeListingDraft();
}

function isPublishFlowForDraft(draft) {
  return state.publishFlow.draftId === draft.id;
}

function publishFlowStatusForDraft(draft) {
  return isPublishFlowForDraft(draft) ? state.publishFlow.status : "idle";
}

function sourceFactsCompletedForDraft(draft) {
  const facts = productFactsForDraft(draft);
  const requiredKeys = [
    "source_link",
    "purchase_price",
    "source_location",
    "product_dimensions",
    "package_dimensions",
    "package_weight",
    "material",
    "included",
  ];
  return requiredKeys.every((key) => isFilledOperationalValue(facts[key]));
}

function taxonomyCheckedForDraft(draft) {
  return state.taxonomyStatus === "checked";
}

function ebayPoliciesReadyForDraft(draft) {
  return state.ebayPolicyStatus === "ready";
}

function missingItemsForDraft(draft) {
  if (state.sourceManualStatus === "saved" && !sourceFactsCompletedForDraft(draft)) {
    return manualSourceMissingLabels();
  }
  return sourceFactsCompletedForDraft(draft) ? [] : Array.isArray(draft.missing) ? draft.missing.filter(Boolean) : [];
}

function publishGateForDraft(draft) {
  if (!draft) {
    return {
      locked: true,
      blockers: ["还没有可校验的商品草稿"],
      reportLevel: "资料缺口",
      sourceHealth: "等待真实商品资料",
      demoFactsCompleted: false,
    };
  }
  const missing = missingItemsForDraft(draft);
  const blockers = [];
  if (!sourceFactsCompletedForDraft(draft) && missing.length) {
    blockers.push(`供应商资料未补齐：${missing.slice(0, 5).join("、")}`);
  }
  if (!taxonomyCheckedForDraft(draft) && String(draft.categoryId || "").includes("待")) {
    blockers.push("eBay 类目参数还没校验：系统需要确认商品放在哪个类目，并返回这个类目必填哪些参数");
  }
  if (!ebayPoliciesReadyForDraft(draft)) {
    blockers.push("店铺默认物流、支付、退货规则还没读取或确认：连接账号后系统会优先套用已确认模板，减少重复填写");
  }
  const reportLevel = blockers.length ? "数据增强报告" : "发布前报告";
  const sourceHealth = missing.length
    ? "可做刊登草稿，不能真实发布"
    : "商品资料已齐，真实发布仍要后端校验";
  return {
    locked: blockers.length > 0,
    blockers,
    reportLevel,
    sourceHealth,
    demoFactsCompleted: false,
  };
}

function publishActionLabel(draft) {
  const status = publishFlowStatusForDraft(draft);
  if (status === "published") return "查看发布结果";
  if (status === "pending") return "继续发布确认";
  if (status === "blocked") return "查看发布前缺口";
  if (publishGateForDraft(draft).locked) return "检查发布条件";
  return "提交发布确认";
}

function publishActionHint(draft) {
  const status = publishFlowStatusForDraft(draft);
  if (status === "published") return `已生成受控 itemId：${state.publishFlow.simulatedItemId || "LOCAL-ITEM"}`;
  if (status === "pending") return "已生成发布确认单，等待你在确认中心点头。";
  if (status === "blocked") return "发布暂未满足条件：先补供应商资料、类目字段和店铺政策，再继续生成确认单。";
  const gate = publishGateForDraft(draft);
  if (gate.locked) return `${gate.reportLevel}：可以看草稿，但真实发布前还要补 ${gate.blockers.length} 类资料。`;
  return "发布动作从这里发起：先生成确认单，再到确认中心点头。";
}

function productFactsForDraft(draft) {
  if (!draft?.id) return {};
  const saved = state.manualProductFacts?.[draft.id];
  return saved && typeof saved === "object" ? saved : {};
}

function productReadinessFields(draft) {
  const facts = productFactsForDraft(draft);
  return [
    ["source_link", "货源链接", facts.source_link],
    ["purchase_price", "采购价", facts.purchase_price],
    ["moq", "起订/代发", facts.moq],
    ["source_location", "发货地", facts.source_location],
    ["product_dimensions", "商品尺寸", facts.product_dimensions],
    ["package_dimensions", "包装尺寸", facts.package_dimensions],
    ["package_weight", "包装重量", facts.package_weight],
    ["material", "材质/规格", facts.material],
    ["included", "配件说明", facts.included],
    ["fulfillment_route", "履约方式", facts.fulfillment_route],
    ["quality_checks", "需要确认", facts.quality_checks],
    ["category_candidate", "类目候选", facts.category_candidate],
    ["policy_note", "三类政策", facts.policy_note],
  ];
}

function isFilledOperationalValue(value) {
  const text = String(value || "").trim();
  if (!text) return false;
  const compact = text.replace(/\s+/g, "").toLowerCase();
  if (["-", "--", "...", "n/a", "na", "none", "null"].includes(compact)) return false;
  if (/待|未确认|不清楚|unknown|pending|tbd/.test(text)) return false;
  return true;
}

function collectManualSourceFacts() {
  const fields = {};
  document.querySelectorAll("[data-source-manual-field]").forEach((input) => {
    fields[input.dataset.sourceManualField] = input.value.trim();
  });
  return {
    ...state.manualSourceFacts,
    ...fields,
    saved_at: formatDecisionTime(new Date()),
  };
}

function buildSaasAiCeoSupplierFactIntake(facts = {}) {
  const source = facts && typeof facts === "object" ? facts : {};
  const cleanText = (value, limit) => {
    const text = String(value || "").trim();
    if (!isFilledOperationalValue(text) || text.length > limit || /[\u0000-\u001f<>]/.test(text)) return "";
    return text;
  };
  const parsePositive = (value, maximum) => {
    const number = Number(value);
    return Number.isFinite(number) && number > 0 && number <= maximum ? number : null;
  };

  let packageWeightG = null;
  const weightMatch = String(source.package_weight || "")
    .trim()
    .match(/^([0-9]+(?:\.[0-9]+)?)\s*(kg|千克|公斤|g|克)?$/i);
  if (weightMatch) {
    const multiplier = /^(kg|千克|公斤)$/i.test(weightMatch[2] || "") ? 1000 : 1;
    packageWeightG = parsePositive(Number(weightMatch[1]) * multiplier, 100000);
  }

  let packageDimensionsCm = null;
  const dimensionsMatch = String(source.package_dimensions || "")
    .trim()
    .match(/^([0-9]+(?:\.[0-9]+)?)\s*[x×*]\s*([0-9]+(?:\.[0-9]+)?)\s*[x×*]\s*([0-9]+(?:\.[0-9]+)?)\s*(?:cm|厘米)?$/i);
  if (dimensionsMatch) {
    const values = dimensionsMatch.slice(1, 4).map((value) => parsePositive(value, 1000));
    if (values.every((value) => value !== null)) {
      packageDimensionsCm = { length: values[0], width: values[1], height: values[2] };
    }
  }

  let unitCost = "";
  const rawCost = String(source.purchase_price || "").trim();
  const codedCost = rawCost.match(/^(CNY|RMB|USD|EUR|GBP|AUD|CAD|HKD|JPY|SGD)\s+([0-9]+(?:\.[0-9]{1,2})?)$/i);
  const symbolCost = rawCost.match(/^(¥|￥|\$|€|£)\s*([0-9]+(?:\.[0-9]{1,2})?)$/);
  if (codedCost && parsePositive(codedCost[2], 1000000000) !== null) {
    unitCost = `${codedCost[1].toUpperCase()} ${codedCost[2]}`;
  } else if (symbolCost && parsePositive(symbolCost[2], 1000000000) !== null) {
    const currency = { "¥": "CNY", "￥": "CNY", "$": "USD", "€": "EUR", "£": "GBP" }[symbolCost[1]];
    unitCost = `${currency} ${symbolCost[2]}`;
  }

  const supplierFacts = {};
  const material = cleanText(source.material, 120);
  const itemLocation = cleanText(source.source_location, 160);
  if (material) supplierFacts.material = material;
  if (packageWeightG !== null) supplierFacts.package_weight_g = packageWeightG;
  if (packageDimensionsCm) supplierFacts.package_dimensions_cm = packageDimensionsCm;
  if (itemLocation) supplierFacts.item_location = itemLocation;
  if (unitCost) supplierFacts.unit_cost = unitCost;
  const requiredKeys = ["material", "package_weight_g", "package_dimensions_cm", "item_location", "unit_cost"];
  const missingSupplierFactKeys = requiredKeys.filter((key) => !Object.prototype.hasOwnProperty.call(supplierFacts, key));
  return {
    supplier_facts: supplierFacts,
    missing_supplier_fact_keys: missingSupplierFactKeys,
    complete: missingSupplierFactKeys.length === 0,
  };
}

function confirmManualSourceFactsForAiCeo(facts = {}) {
  const intake = buildSaasAiCeoSupplierFactIntake(facts);
  const merchantConfirmed =
    intake.complete &&
    window.confirm(
      "请核对：材质、包裹重量、包装尺寸、发货地和单件采购成本均来自你的真实供应商资料。确认后只允许生成可审核的 Listing 草稿，不会自动发布、付款或写入 eBay。",
    );
  const attestation = {
    contract_version: "jiejing_ai_ceo_supplier_fact_form_v1",
    source: "manual_supplier_form",
    supplier_facts: intake.supplier_facts,
    supplier_facts_verified: merchantConfirmed === true,
    merchant_confirmation_received: merchantConfirmed === true,
    missing_supplier_fact_keys: intake.missing_supplier_fact_keys,
    confirmed_at: merchantConfirmed === true ? new Date().toISOString() : "",
  };
  state.saasAiCeoSupplierFactAttestation = attestation;
  return attestation;
}

function supplierFactsForSaasAiCeoCommand(command = {}) {
  const text = String(command?.text || "").toLowerCase();
  const explicitlyUnknownProductFacts =
    /没有供应商|无供应商|没有实物|无实物|商品参数.{0,8}(?:未知|没有|未提供)|(?:重量|尺寸|材质|采购价).{0,20}(?:都|均)?未知|严禁编造|不要编造|不得编造/i.test(text);
  if (explicitlyUnknownProductFacts) return {};
  const explicitlyEbay = text.includes("ebay");
  const namesOtherPlatform = /淘宝|天猫|京东|拼多多|亚马逊|amazon|shopify|shopee|lazada|temu|tiktok shop|抖音小店|快手小店|微信小店/i.test(text);
  if (namesOtherPlatform && !explicitlyEbay) return {};
  const route = String(command?.route || command?.intent || "").toLowerCase();
  const isEbayWorkflow = explicitlyEbay || ["listing", "ebay_workflow"].includes(route) || /listing|刊登|上架/.test(text);
  if (!isEbayWorkflow) return {};
  const attestation = state.saasAiCeoSupplierFactAttestation;
  if (!attestation || typeof attestation !== "object") return {};
  const raw = attestation.supplier_facts && typeof attestation.supplier_facts === "object" ? attestation.supplier_facts : {};
  const supplierFacts = {};
  for (const key of ["material", "package_weight_g", "package_dimensions_cm", "item_location", "unit_cost"]) {
    if (raw[key] !== undefined && raw[key] !== null && raw[key] !== "") supplierFacts[key] = raw[key];
  }
  return {
    supplier_facts: supplierFacts,
    supplier_facts_verified:
      attestation.supplier_facts_verified === true && attestation.merchant_confirmation_received === true,
  };
}

function manualSourceMissingItems(facts = state.manualSourceFacts || {}) {
  const checks = [
    { key: "package_weight", label: "包裹重量" },
    { key: "package_dimensions", label: "包装尺寸" },
    { key: "dropship_rule", label: "供应商代发规则" },
  ];
  return checks.filter((item) => !isFilledOperationalValue(facts[item.key]));
}

function manualSourceMissingLabels(facts = state.manualSourceFacts || {}) {
  return manualSourceMissingItems(facts).map((item) => item.label);
}

function manualSourceFilledLabels(facts = state.manualSourceFacts || {}) {
  const labels = [];
  if (isFilledOperationalValue(facts.package_weight)) labels.push(`包裹重量 ${facts.package_weight}`);
  if (isFilledOperationalValue(facts.package_dimensions)) labels.push(`包装尺寸 ${facts.package_dimensions}`);
  if (isFilledOperationalValue(facts.dropship_rule)) labels.push(`代发规则 ${facts.dropship_rule}`);
  return labels;
}

function manualSourceFeedbackText() {
  if (state.sourceManualStatus !== "saved") {
    return "当前建议：不接 API 也可以继续。先把链接、采购价、重量、尺寸、发货地和是否支持代发填进来，缺口会进入待补资料。";
  }
  const facts = state.manualSourceFacts || {};
  const missing = manualSourceMissingLabels(facts);
  const filled = manualSourceFilledLabels(facts);
  if (!missing.length) {
    return `手动资料已保存。${filled.join("、")} 已补齐，可以继续进入产品刊登、物流测算和发布前确认。`;
  }
  const filledText = filled.length ? `已记录：${filled.join("、")}。` : "";
  return `手动资料已保存。${filledText}还缺 ${missing.join("、")}，这些会进入待补资料，不会再把已填写的重量重复提示成缺口。`;
}

function sourceFactsFromManualInput(draft, facts = state.manualSourceFacts || {}) {
  const dropshipText =
    facts.dropship_rule === "支持"
      ? "供应商支持代发；真实下单、付款和地址写入仍需确认"
      : facts.dropship_rule === "不支持"
        ? "供应商不支持直发，建议国内中转后再走橙联 / SpeedPAK"
        : "待确认供应商是否支持无票据代发";
  return {
    source_link: facts.source_link || "",
    purchase_price: facts.purchase_price || "",
    moq: facts.moq || "",
    source_location: facts.source_location || "",
    product_dimensions: facts.product_dimensions || "",
    package_weight: facts.package_weight || "",
    package_dimensions: facts.package_dimensions || "",
    material: facts.material || "",
    included: facts.included || "",
    fulfillment_route: dropshipText,
    quality_checks: facts.quality_checks || "",
    category_candidate: facts.category_candidate || "",
    policy_note: facts.policy_note || "",
  };
}

function collectProductReadinessFacts(draft) {
  const fields = {};
  document.querySelectorAll("[data-product-readiness-field]").forEach((input) => {
    fields[input.dataset.productReadinessField] = input.value.trim();
  });
  return {
    ...productFactsForDraft(draft),
    ...fields,
    saved_at: formatDecisionTime(new Date()),
  };
}

