function runtimeListingValidation() {
  const validations = state.runtimeValidationSummary?.validations || [];
  return validations.find((item) => item.task_type === "listing.package" || String(item.task_id || "").includes("listing.package")) || null;
}

function runtimeListingStatusMeta() {
  if (!state.runtimeConnected) {
    return {
      tone: "neutral",
      label: "等待后端复核",
      title: "资料会先保存在当前工作台",
      copy: "后端工作记录连接后，保存资料会回写并重新校验。现在不会误说已经完成真实平台复核。",
      detail: "当前仍可继续整理草稿，但不代表已经写入真实 eBay。",
    };
  }
  const validation = runtimeListingValidation();
  if (!validation) {
    return {
      tone: "amber",
      label: "等待后端复核",
      title: "保存资料后会重新检查刊登包",
      copy: "AI CEO 会检查刊登包是否包含 eBay 固定骨架、类目字段、店铺三类政策和发布锁。",
      detail: "还没有拿到 listing.package 的复核结果。",
    };
  }
  const status = validation.validation_status || "";
  const ready = status.includes("ready") || status.includes("manifest_ready");
  if (ready) {
    return {
      tone: "green",
      label: "底座已复核",
      title: "刊登包可以进入确认中心",
      copy: "Runtime 已确认刊登资料包达到发布前确认标准；真实发布、改价、库存、政策和采购付款仍然被确认中心和执行服务锁住。",
      detail: validation.summary || "刊登包已通过 Runtime 复核。",
    };
  }
  return {
    tone: "red",
    label: "仍有缺口",
    title: "刊登包还不能进入发布确认",
    copy: "系统会继续停在补资料，不会让 AI 用猜测信息去发布商品。",
    detail: validation.summary || "仍需补齐货源事实、类目字段或店铺政策。",
  };
}

function renderRuntimeListingStatusCard() {
  const meta = runtimeListingStatusMeta();
  return `
    <div class="product-runtime-check is-${meta.tone}">
      <div>
        <span>${escapeHtml(meta.label)}</span>
        <strong>${escapeHtml(meta.title)}</strong>
        <p>${escapeHtml(meta.copy)}</p>
      </div>
      <small>${escapeHtml(meta.detail)}</small>
    </div>
  `;
}

