function renderPublishFlowCard(draft) {
  const status = publishFlowStatusForDraft(draft);
  const gate = publishGateForDraft(draft);
  const isPublished = status === "published";
  const isPending = status === "pending";
  const isBlocked = status === "blocked" || (!isPublished && !isPending && gate.locked);
  const steps = [
    ["草稿资料", "done", "标题、描述、类目、图片需求已形成"],
    ["发布前校验", isPublished || isPending ? "done" : isBlocked ? "blocked" : "current", "检查字段、政策、价格、库存和风险"],
    ["待我确认", isPublished ? "done" : isPending ? "current" : "wait", "你确认后才允许执行发布动作"],
    ["模拟发布结果", isPublished ? "done" : "wait", isPublished ? state.publishFlow.simulatedItemId : "等待确认后生成"],
  ];
  const blockerMarkup = gate.locked
    ? `
      <div class="product-publish-gate is-locked">
        <div>
          <span>发布锁</span>
          <strong>现在不能直接发布，只能继续做草稿和演示闭环</strong>
          <p>正式版到这里会停住：缺资料就补资料，缺授权就去连接账号；不会让 AI 用猜的资料上架。</p>
        </div>
        <ul>
          ${gate.blockers.map((item) => `<li>${escapeHtml(item)}</li>`).join("")}
        </ul>
      </div>
    `
    : `
      <div class="product-publish-gate">
        <div>
          <span>发布前校验</span>
          <strong>教程资料已齐，下一步送确认中心</strong>
          <p>正式版仍会由后端重新检查 eBay 类目字段、三类业务政策、利润、库存和操作日志。</p>
        </div>
      </div>
    `;
  return `
    <div class="product-publish-flow-card" aria-label="发布闭环">
      <div class="product-publish-flow-head">
        <div>
          <span>发布闭环位置</span>
          <strong>${isPublished ? "已完成演示发布，结果已写入 AI 汇报" : isPending ? "确认中心正在等待你点头" : isBlocked ? "这里先做发布前检查，不直接发布" : "这里就是以后真实发布的入口"}</strong>
          <p>${isPublished ? `演示版已生成 ${escapeHtml(state.publishFlow.simulatedItemId)}。正式版会由后端调用 eBay API，并返回真实 itemId / Listing 链接。` : "产品刊登负责把资料准备齐；确认中心只负责最后的高风险动作。演示版不会写入 eBay。"}</p>
        </div>
        <span class="pill ${isPublished ? "green" : isPending ? "amber" : isBlocked ? "red" : "neutral"}">${isPublished ? "已模拟发布" : isPending ? "待你确认" : isBlocked ? "发布锁开启" : "可发起确认"}</span>
      </div>
      ${blockerMarkup}
      <div class="product-publish-stepper">
        ${steps
          .map(
            ([label, stepStatus, note], index) => `
              <article class="is-${stepStatus}">
                <b>${String(index + 1).padStart(2, "0")}</b>
                <strong>${escapeHtml(label)}</strong>
                <small>${escapeHtml(note)}</small>
              </article>
            `,
          )
          .join("")}
      </div>
      <div class="product-publish-readiness-grid">
        ${publishReadinessItems(draft)
          .map(
            ([label, value, note]) => `
              <article>
                <span>${escapeHtml(label)}</span>
                <strong>${escapeHtml(value)}</strong>
                <p>${escapeHtml(note)}</p>
              </article>
            `,
          )
          .join("")}
      </div>
    </div>
  `;
}

