function renderSaasListingStatusBar({
  draft = state.saasListingComposerDraft,
  reportsReady = false,
  confirmationCount = 0,
} = {}) {
  const hasInput = Boolean((state.saasListingComposerInput || "").trim());
  const hasSource = Boolean(draft || hasInput || reportsReady);
  const hasDraft = Boolean(draft);
  const currentState = hasDraft ? "上架项目已生成" : hasSource ? "商品资料已接入" : "等待商品资料";
  const items = [
    {
      title: "商品资料",
      value: hasSource ? "已接入" : "未接入",
      state: hasSource ? "done" : "active",
    },
    {
      title: "市场结论",
      value: draft || reportsReady ? "可查看" : "待生成",
      state: draft || reportsReady ? "done" : hasSource ? "active" : "wait",
    },
    {
      title: "Listing 草稿",
      value: hasDraft ? "可编辑" : "待生成",
      state: hasDraft ? "done" : hasSource ? "active" : "wait",
    },
    {
      title: "素材/利润",
      value: hasDraft ? "可补字段" : "等待草稿",
      state: hasDraft ? "active" : "wait",
    },
    {
      title: "发布确认",
      value: confirmationCount ? `${confirmationCount} 个确认项` : "待确认",
      state: confirmationCount ? "done" : hasDraft ? "active" : "wait",
    },
  ];
  return `
    <section class="saas-listing-v2-status-bar" aria-label="Listing 刊登状态">
      <div class="saas-listing-v2-status-head">
        <span>刊登状态</span>
        <strong>${escapeHtml(currentState)}</strong>
      </div>
      <div class="saas-listing-v2-status-items">
        ${items
          .map(
            (item) => `
              <article class="is-${escapeHtml(item.state)}">
                <div>
                  <strong>${escapeHtml(item.title)}</strong>
                  <span>${escapeHtml(item.value)}</span>
                </div>
              </article>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

function renderSaasListingOpportunityPanel(opportunity = {}) {
  const score = Number(opportunity.score || 0);
  const tone = score >= 80 ? "green" : score >= 60 ? "amber" : "neutral";
  const reasons = Array.isArray(opportunity.reasons) ? opportunity.reasons.slice(0, 3) : [];
  const candidates = Array.isArray(opportunity.candidates) ? opportunity.candidates.slice(0, 3) : [];
  return `
    <article class="saas-listing-v2-opportunity is-${escapeHtml(tone)}" aria-label="市场结论">
      <div class="saas-listing-v2-opportunity-main">
        <span>市场结论</span>
        <strong>${escapeHtml(opportunity.product || "还没有选定商品")}</strong>
        <p>${escapeHtml(opportunity.summary || "选择来源后，JIEJING 会把它整理成可编辑 Listing 草稿。")}</p>
        <div class="saas-listing-v2-source-row">
          <em>来源：${escapeHtml(opportunity.source || "等待来源")}</em>
        </div>
      </div>
      <div class="saas-listing-v2-score">
        <small>推荐度</small>
        <b>${score ? score : "--"}</b>
        <small>${score ? "草稿级评分" : "等待资料"}</small>
      </div>
      <div class="saas-listing-v2-reasons">
        ${reasons.length ? reasons.map((reason) => `<span>${escapeHtml(reason)}</span>`).join("") : `<span>先选择来源或粘贴商品资料</span>`}
      </div>
      ${
        candidates.length
          ? `<div class="saas-listing-v2-candidate-row" aria-label="AI CEO 推荐商品卡">
              ${candidates
                .map(
                  (candidate) => `
                    <button type="button"
                      class="${candidate.name === opportunity.product ? "is-selected" : ""}"
                      data-saas-listing-candidate-id="${escapeHtml(candidate.candidate_id)}"
                      aria-pressed="${candidate.name === opportunity.product ? "true" : "false"}">
                      <span>${escapeHtml(candidate.name)}</span>
                      <small>${escapeHtml(String(candidate.score || "--"))}</small>
                    </button>
                  `,
                )
                .join("")}
            </div>`
          : ""
      }
    </article>
  `;
}

function renderSaasListingDraftField(label, field, value = "", options = {}) {
  const tag = options.multiline ? "textarea" : "input";
  const rows = options.rows || 3;
  const placeholder = options.placeholder || "";
  const className = [
    "saas-listing-v2-field",
    options.wide ? "is-wide" : "",
    options.compact ? "is-compact" : "",
  ].filter(Boolean).join(" ");
  if (tag === "textarea") {
    return `
      <label class="${className}">
        <span>${escapeHtml(label)}</span>
        <textarea data-saas-listing-draft-field="${escapeHtml(field)}" rows="${rows}" placeholder="${escapeHtml(placeholder)}">${escapeHtml(value || "")}</textarea>
      </label>
    `;
  }
  return `
    <label class="${className}">
      <span>${escapeHtml(label)}</span>
      <input data-saas-listing-draft-field="${escapeHtml(field)}" type="text" value="${escapeHtml(value || "")}" placeholder="${escapeHtml(placeholder)}" />
    </label>
  `;
}

