  const readyCount = listingDraftCatalog.filter((item) => !item.status.includes("待补") && !item.risk.includes("高")).length;
  const missingCount = listingDraftCatalog.reduce((sum, item) => sum + missingItemsForDraft(item).length, 0);
  const cautionCount = listingDraftCatalog.filter((item) => item.risk.includes("中") || item.risk.includes("高") || item.status.includes("待补")).length;

