function saveDecisionDefault(confirmId) {
  const card = getConfirmationById(confirmId);
  if (!card) return null;
  const rule = getConfirmationDefaultRule(card);
  const savedRule = {
    action: "approve",
    ruleTitle: rule.title,
    scope: rule.scope,
    config: rule.config,
    savedAt: formatDecisionTime(),
  };
  state.savedDecisionDefaults[confirmId] = savedRule;
  persistSavedDecisionDefaults();
  upsertActivity(`default-rule-${confirmId}`, {
    role: "AI CEO",
    title: `保存默认确认规则：${rule.title}`,
    action: `商家已确认「${cleanDefaultAction(card.defaultAction)}」。同类${rule.scope}以后按默认配置走，只有关键变化才再次打扰。`,
    sources: [
      `确认卡：${card.title}`,
      `依据：${card.evidence}`,
      "确认中心：确认一次后保存默认配置",
      "当前权限：核心决策才确认",
    ],
    result: `${rule.config} 规则变化、金额变化、账号/授权变化或平台风险升高时，仍会重新进入确认中心。`,
    status: "已完成",
    confidence: "100%",
    report: buildDefaultRuleReport(card, savedRule),
  });
  return savedRule;
}

