function submitPublishConfirmation(draft = activeListingDraft()) {
  const gate = publishGateForDraft(draft);
  if (gate.locked) {
    state.publishFlow = {
      status: "blocked",
      draftId: draft.id,
      simulatedItemId: "",
      listingUrl: "",
      confirmedAt: "",
      demoFactsCompleted: false,
    };
    state.confirmFilter = "immediate";
    setView("confirm");
    renderConfirmations();
    renderGlobalFlowBar();
    addAiMessage(`「${draft.titleCn}」还不能直接进入发布确认。我已经把发布前缺口送到待我确认：先补供应商资料、类目字段和三类店铺政策；演示时也可以用样例资料继续跑闭环。`);
    showActionToast("已打开发布前缺口：先看清楚为什么不能直接发布。");
    return;
  }
  state.publishFlow = {
    status: state.publishFlow.status === "published" && state.publishFlow.draftId === draft.id ? "published" : "pending",
    draftId: draft.id,
    simulatedItemId: state.publishFlow.draftId === draft.id ? state.publishFlow.simulatedItemId : "",
    listingUrl: state.publishFlow.draftId === draft.id ? state.publishFlow.listingUrl : "",
    confirmedAt: state.publishFlow.draftId === draft.id ? state.publishFlow.confirmedAt : "",
    demoFactsCompleted: state.publishFlow.draftId === draft.id ? state.publishFlow.demoFactsCompleted === true : false,
  };
  state.confirmFilter = "immediate";
  setView("confirm");
  renderConfirmations();
  renderGlobalFlowBar();
  addAiMessage(
    state.publishFlow.status === "published"
      ? `「${draft.titleCn}」已经完成演示发布，可以在待我确认查看发布结果，也可以到 AI 汇报看执行记录。`
      : `已为「${draft.titleCn}」生成发布确认单。你在确认中心点头后，演示版会生成模拟 eBay itemId；正式版才会由后端调用 eBay。`,
  );
  showActionToast(state.publishFlow.status === "published" ? "已打开发布结果。" : "已生成发布确认单：下一步只需要确认是否模拟发布。");
}

function completeSimulatedPublish() {
  const draft = getPublishDraft();
  if (state.publishFlow.status === "blocked") {
    showActionToast("当前仍有发布前缺口。请先补资料，再继续发布确认。");
    renderConfirmations();
    return;
  }
  const now = new Date();
  const itemId = `LOCAL-${draft.sku.replace(/[^A-Z0-9]/gi, "").slice(-6).toUpperCase()}-${String(now.getHours()).padStart(2, "0")}${String(now.getMinutes()).padStart(2, "0")}`;
  state.publishFlow = {
    status: "published",
    draftId: draft.id,
    simulatedItemId: itemId,
    listingUrl: `https://www.ebay.com/itm/${itemId}`,
    confirmedAt: formatDecisionTime(now),
    demoFactsCompleted: true,
  };
  const flow = state.publishFlow;
  upsertActivity(`publish-simulation-${draft.id}`, {
    role: "发布执行",
    title: `${draft.titleCn} 已完成演示发布闭环`,
    action: `商家在确认中心确认后，系统生成模拟 eBay 发布结果 ${flow.simulatedItemId}，并把发布记录回写到 AI 汇报。`,
    sources: [
      `产品刊登草稿：${draft.title}`,
      `Category：${draft.category} / ${draft.categoryId}`,
      `三类政策：${draft.policies.fulfillment} / ${draft.policies.payment} / ${draft.policies.returns}`,
      "确认中心：商家点击确认模拟发布",
      "执行边界：演示版不调用真实 eBay API",
    ],
    result: `演示发布成功：${flow.simulatedItemId}。自动客服已接收商品档案；正式版会返回真实 itemId、Listing URL、执行日志和失败原因。`,
    status: "已完成",
    confidence: "100%",
    report: buildPublishSimulationReport(draft, flow),
  });
  activeEvidenceIndex = activities.findIndex((item) => item.id === `publish-simulation-${draft.id}`);
  renderActivities();
  renderProductListingCenter();
  renderConfirmations();
  renderServiceKnowledgeSync();
  renderServiceKnowledgePanel();
  renderConnect();
  renderGlobalFlowBar();
  setText("#serviceActionFeedback", `${draft.titleCn} 商品档案已同步给自动客服：普通规格咨询可自动回复；退款、补偿、差评和明确承诺仍需人工接管。`);
  addAiMessage(`演示发布已完成：${draft.titleCn} 生成 ${flow.simulatedItemId}。我已把发布结果、字段、政策和确认记录写入 AI 汇报，并把商品档案交给自动客服学习。`);
  syncRuntimePublishExecution(draft, flow);
  showActionToast(`已模拟发布成功：${flow.simulatedItemId}`);
}

function runtimePublishConfirmationId() {
  const publishConfirmation = state.runtimeConfirmations.find((item) => item.action_type === "publish_listing");
  return publishConfirmation?.confirmation_id || "";
}

async function syncRuntimePublishExecution(draft, flow) {
  const confirmationId = runtimePublishConfirmationId();
  if (!state.runtimeSelectedRunId || !confirmationId) {
    return;
  }
  try {
    await runtimeFetch(`/runs/${encodeURIComponent(state.runtimeSelectedRunId)}/confirmations/${encodeURIComponent(confirmationId)}/decision`, {
      method: "POST",
      body: JSON.stringify({
        decision: "approve",
        decided_by: "merchant_demo",
        note: `SaaS controlled draft confirmed simulated publish for ${draft.titleCn}.`,
      }),
    });
    const execution = await runtimeFetch(`/runs/${encodeURIComponent(state.runtimeSelectedRunId)}/confirmations/${encodeURIComponent(confirmationId)}/execute`, {
      method: "POST",
      body: JSON.stringify({
        requested_by: "merchant_demo",
        demo_mode: true,
        payload: {
          source: "jiejing_saas_publish_confirmation",
          simulated_item_id: flow.simulatedItemId,
          listing_url: flow.listingUrl,
          product: draft.titleCn,
        },
      }),
    });
    await refreshRuntimeState({ silent: true });
    addAiMessage(`ExecutionService 已记录「${draft.titleCn}」的发布确认交接：${runtimeValidationLabel(execution.execution_result?.status || "")}。演示版没有写入 eBay；正式版以后会在这里替换成真实 eBay 执行适配器。`);
  } catch (error) {
    state.runtimeError = `发布确认交接 Runtime 失败：${error.message}`;
    showActionToast("本地演示发布已完成，但 Runtime 执行服务交接失败。");
    renderRuntimeBridgePanel();
  }
}

function continuePublishWithDemoFacts() {
  const draft = getPublishDraft();
  state.supplierFactsStatus = "saved";
  state.taxonomyStatus = "checked";
  state.ebayPolicyStatus = "ready";
  state.publishFlow = {
    status: "pending",
    draftId: draft.id,
    simulatedItemId: "",
    listingUrl: "",
    confirmedAt: "",
    demoFactsCompleted: true,
  };
  state.confirmFilter = "immediate";
  renderConfirmations();
  renderProductListingCenter();
  renderGlobalFlowBar();
  addAiMessage(`已用教程资料补齐「${draft.titleCn}」的尺寸、重量、类目和店铺政策样例。下一步可以确认模拟发布；正式版不会允许这样代替真实供应商资料。`);
  showActionToast("教程资料已补齐：现在可以确认模拟发布。");
}

async function syncProductReadinessToRuntime(draft, facts) {
  if (!state.runtimeSelectedRunId) {
    if (state.runtimeConnected && state.runtimeRuns[0]?.run_id) {
      state.runtimeSelectedRunId = state.runtimeRuns[0].run_id;
    } else {
      setProductInlineFeedback("本地页面已保存资料。后端工作记录连接后，点击刷新即可把这份资料回写校验。");
      return;
    }
  }
  try {
    const payload = await runtimeFetch(`/runs/${encodeURIComponent(state.runtimeSelectedRunId)}/listing-facts`, {
      method: "POST",
      body: JSON.stringify({
        updated_by: "merchant_demo",
        facts: {
          ...facts,
          product: draft.titleEn || draft.titleCn,
          title_cn: draft.titleCn,
          ebay_title: draft.title,
          price: draft.price,
          quantity: draft.quantity,
          category_id: facts.category_candidate || draft.categoryId,
        },
      }),
    });
    state.runtimeValidationSummary = payload.validation_summary || state.runtimeValidationSummary;
    await refreshRuntimeState({ silent: true });
    addAiMessage(`AI CEO 已重新校验「${draft.titleCn}」的产品经理刊登资料包。结果：${runtimeValidationLabel(payload.validation?.status || "")}。真实发布仍然停在确认中心和后端执行边界。`);
    showActionToast("AI CEO 已重新校验刊登资料：缺口状态已回写。");
  } catch (error) {
    state.runtimeError = `补资料回写后端工作记录失败：${error.message}`;
    setProductInlineFeedback("资料已保存在当前工作台，但后端回写失败。刷新后可再试。");
    showActionToast("资料已保存，但后端回写失败。");
    renderRuntimeBridgePanel();
  }
}

function saveProductReadinessFacts(draft = activeListingDraft()) {
  if (!draft) {
    setProductInlineFeedback("还没有可保存的商品草稿。请先上传商品图片、货源链接或填写真实规格。");
    showActionToast("请先导入真实商品资料。");
    return;
  }
  const facts = collectProductReadinessFacts(draft);
  state.manualProductFacts = {
    ...state.manualProductFacts,
    [draft.id]: facts,
  };
  state.supplierFactsStatus = sourceFactsCompletedForDraft(draft) ? "saved" : "partial";
  state.sourceManualStatus = "saved";
  const gate = publishGateForDraft(draft);
  state.publishFlow = {
    status: gate.locked ? "blocked" : "pending",
    draftId: draft.id,
    simulatedItemId: "",
    listingUrl: "",
    confirmedAt: "",
    demoFactsCompleted: false,
  };
  if (!gate.locked) state.confirmFilter = "immediate";
  upsertActivity(`product-readiness-${draft.id}`, {
    role: "发布前资料",
    title: `${draft.titleCn} 商品资料已保存`,
    action: "商家在产品刊登里保存了商品事实；捷境不会据此伪造 eBay 类目校验或店铺政策状态。",
    sources: [
      `货源链接：${facts.source_link}`,
      `采购价：${facts.purchase_price}`,
      `尺寸重量：${facts.product_dimensions} / ${facts.package_dimensions} / ${facts.package_weight}`,
      `材质与配件：${facts.material} / ${facts.included}`,
      `三类政策：${facts.policy_note}`,
      "执行边界：保存资料不等于完成类目、政策或发布校验",
    ],
    result: gate.locked
      ? `${draft.titleCn} 仍被 ${gate.blockers.length} 项真实缺口阻断；补齐后才生成发布确认单。`
      : `${draft.titleCn} 已满足当前校验，可以进入发布确认。`,
    status: gate.locked ? "待补资料" : "已完成",
    confidence: gate.locked ? "待核对" : "已核对",
    report: {
      summary: [
        ["商品", draft.titleCn],
        ["采购价", facts.purchase_price],
        ["包装重量", facts.package_weight],
        ["类目候选", facts.category_candidate],
        ["下一步", gate.locked ? "补齐真实缺口" : "确认中心"],
      ],
      boards: [
        {
          title: "本次补齐的资料",
          items: [
            `货源：${facts.source_link}`,
            `发货地：${facts.source_location}`,
            `包装：${facts.package_dimensions} / ${facts.package_weight}`,
            `履约：${facts.fulfillment_route}`,
          ],
        },
        {
          title: "继续人工确认的边界",
          items: ["真实 eBay 发布", "采购付款", "退款/补偿", "广告预算", "店铺政策写回"],
        },
      ],
    },
  });
  renderProductListingCenter();
  renderActivities();
  renderGlobalFlowBar();
  syncProductReadinessToRuntime(draft, facts);
  if (gate.locked) {
    setProductInlineFeedback(`商品资料已保存，但仍需处理：${gate.blockers.join("；")}。`);
    addAiMessage(`已保存「${draft.titleCn}」的商品资料。系统没有把未验证的类目或店铺政策标成完成；当前仍需补齐发布前缺口。`);
    showActionToast("商品资料已保存；仍有发布前缺口。");
    return;
  }
  setView("confirm");
  renderConfirmations();
  addAiMessage(`已保存「${draft.titleCn}」的真实商品资料，并完成当前发布前校验。现在已生成发布确认单；真实发布仍需动作时确认。`);
  showActionToast("资料已保存：已生成发布确认单。");
}

function globalFlowViewKey(view = state.view) {
  return {
    cockpit: "market",
    product: "product",
    media: "media",
    bulk: "market",
    activity: state.publishFlow.status === "published" ? "confirm" : "goal",
    confirm: "confirm",
    connect: "source",
    dna: "source",
  }[view] || "market";
}

function globalFlowSnapshot() {
  const published = state.publishFlow.status === "published";
  const pending = state.publishFlow.status === "pending";
  const blocked = state.publishFlow.status === "blocked";
  const currentKey = state.activeFlowKey || globalFlowViewKey();
  const completed = new Set(["goal", "market"]);
  if (state.view === "connect") completed.add("source");
  if (state.activeListingDraft) completed.add("product");
  if (state.activeMediaDraft || state.mediaGenerationStatus === "done") completed.add("media");
  if (state.activeListingDraft) completed.add("finance");
  if (blocked || pending || published) completed.add("confirm");
  const draft = getPublishDraft();
  if (published) {
    return {
      currentKey,
      completed,
      pill: "闭环已跑通",
      tone: "green",
      title: `${draft.titleCn} 已完成演示发布闭环`,
      copy: `已生成 ${state.publishFlow.simulatedItemId}，发布记录已写入 AI 汇报，商品档案已同步给自动客服。正式版仍要经过 eBay 官方授权、系统执行服务和操作日志。`,
    };
  }
  if (pending) {
    return {
      currentKey: "confirm",
      completed,
      pill: "等待确认",
      tone: "amber",
      title: `${draft.titleCn} 等待发布确认`,
      copy: "产品刊登已经把草稿准备好，现在只差确认中心点头。演示版确认后生成模拟 itemId，正式版确认后才会由后端调用 eBay。",
    };
  }
  if (blocked) {
    return {
      currentKey: "confirm",
      completed,
      pill: "发布前缺口",
      tone: "red",
      title: `${draft.titleCn} 还不能进入真实发布`,
      copy: "系统已停在发布锁：先补供应商资料、eBay 类目字段和三类业务政策。演示版可以用样例资料继续跑闭环，正式版不能跳过。",
    };
  }
  return {
    currentKey,
    completed,
    pill: "",
    tone: "neutral",
    title: "",
    copy: "",
  };
}

