function loopTaskStatus(key) {
  const published = state.publishFlow.status === "published";
  const pending = state.publishFlow.status === "pending";
  if (key === "ceo") return "done";
  if (key === "data") return "done";
  if (key === "market") return "done";
  if (key === "source") return state.sourceHandoffStatus === "sent" ? "done" : "current";
  if (key === "product") return state.sourceHandoffStatus === "sent" ? "current" : state.activeListingDraft ? "ready" : "waiting";
  if (key === "media") return state.activeMediaDraft || state.mediaGenerationStatus === "done" ? "ready" : "waiting";
  if (key === "service") return state.activeListingDraft ? "ready" : "waiting";
  if (key === "finance") return state.activeListingDraft ? "ready" : "waiting";
  if (key === "confirm") return published ? "done" : pending ? "current" : "waiting";
  if (key === "summary") return published ? "done" : pending ? "ready" : "waiting";
  return "waiting";
}

function currentGateSummary() {
  const draft = typeof activeListingDraft === "function" ? activeListingDraft() : null;
  const gate = draft ? publishGateForDraft(draft) : { locked: true, blockers: ["还没有选中商品草稿"] };
  if (draft?.risk?.includes("高") || state.activeProject === "stainless-cup") {
    return {
      tone: "red",
      label: "红灯",
      title: "暂停发布",
      body: "利润、认证、履约或平台风险没有过线时，AI 继续整理资料，但发布按钮必须锁住。",
    };
  }
  if (gate.locked) {
    return {
      tone: "amber",
      label: "黄灯",
      title: "可做草稿，不能发布",
      body: `还缺 ${gate.blockers.length} 类关键资料。AI 可以继续出报告、图片和 Listing 草稿，真实发布前必须补齐。`,
    };
  }
  return {
    tone: "green",
    label: "绿灯",
    title: "可进入发布前确认",
    body: "资料已达到演示发布前检查标准；正式版仍要由后端校验并进入确认中心。",
  };
}

