function pulseFlowTarget(selector, options = {}) {
  const { focusInput = false } = options;
  setTimeout(() => {
    const target = document.querySelector(selector);
    if (!target) return;
    target.scrollIntoView({ behavior: "smooth", block: "center" });
    target.classList.remove("flow-focus-pulse");
    void target.offsetWidth;
    target.classList.add("flow-focus-pulse");
    if (focusInput) {
      const input = target.matches("input, textarea") ? target : target.querySelector("input, textarea");
      input?.focus({ preventScroll: true });
    }
  }, 80);
}

function saasAiCeoResearchContinuationPrompt(command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  const priorGoal = sanitizeSaasCeoCommandSourceText(current?.text || "").slice(0, 220);
  const projectId = saasCurrentMerchantProjectId();
  const contextLabel = projectId ? "当前已选商品" : "当前商品项目";
  const projectScopeInstruction = projectId
    ? "围绕当前已经选定的商品补充市场证据、竞品、风险和仍缺的商品事实；不要更换商品，也不要新增候选商品。需要换品时必须显式新建商品项目。"
    : "继续补充不重复的可售候选、可核对证据、风险和仍缺的商品事实。";
  return [
    `请基于${contextLabel}继续下一轮调研。`,
    projectScopeInstruction,
    priorGoal ? `上一轮目标：${priorGoal}` : "延续当前对话中的选品约束。",
    "本轮只做调研和保存可核对结果，不生成素材、不写入 eBay，也不执行付款、退款、广告或采购。",
  ].join("\n");
}

function submitSaasAiCeoResearchContinuation(button = null) {
  if (state.saasAiCeoResearchContinuationSubmitting || !requireSaasProtectedSessionForAction()) return false;
  setView("cockpit", {
    preserveFlowKey: true,
    aiCeoTaskContextMode: "active_product_task",
    aiCeoTaskContextExpanded: true,
  });
  const form = document.querySelector("#view-cockpit #ceoForm, #ceoForm");
  const input = form?.querySelector?.("#ceoInput") || document.querySelector("#ceoInput");
  if (!form || !input) {
    showActionToast("AI CEO 输入框暂时不可用，请刷新工作台后重试。");
    return false;
  }
  bindCeoForm(document);
  input.value = saasAiCeoResearchContinuationPrompt();
  input.dispatchEvent(new Event("input", { bubbles: true }));
  form.dataset.enforceProjectIdentity = "true";
  state.saasAiCeoResearchContinuationSubmitting = true;
  if (button) button.disabled = true;
  if (typeof form.requestSubmit === "function") form.requestSubmit();
  else form.dispatchEvent(new Event("submit", { bubbles: true, cancelable: true }));
  Promise.resolve(state.saasLastCeoCommandPersistPromise).finally(() => {
    state.saasAiCeoResearchContinuationSubmitting = false;
    if (button?.isConnected) button.disabled = false;
  });
  return true;
}

function handleGlobalFlowNavigation(button) {
  const key = button.dataset.globalFlowKey || "";
  const view = button.dataset.globalFlowView || "cockpit";
  const sourceView = state.view || "";
  state.activeFlowKey = key;
  if (view === "cockpit" && key === "research") {
    submitSaasAiCeoResearchContinuation(button);
    return;
  }
  if (view === "product" && key === "recent") {
    activateSaasListingMode("recent");
    pulseFlowTarget("#view-product .saas-recent-product-tasks");
    return;
  }
  if (key === "goal") {
    const currentProjectId = saasCurrentMerchantProjectId();
    const explicitProjectEntry = ["product", "media", "confirm"].includes(sourceView) && Boolean(currentProjectId);
    setView("cockpit", {
      preserveFlowKey: true,
      aiCeoTaskContextMode: explicitProjectEntry ? "explicit_project_entry" : "plain_consultation",
      aiCeoTaskContextExpanded: explicitProjectEntry,
      aiCeoTaskContextProjectId: explicitProjectEntry ? currentProjectId : "",
      aiCeoTaskContextStartedAt: "",
      aiCeoTaskContextStartedAtReliable: false,
    });
    pulseFlowTarget("#view-cockpit .cockpit-chat-panel", { focusInput: true });
    return;
  }
  if (key === "market") {
    setView("cockpit", {
      preserveFlowKey: true,
      aiCeoTaskContextMode: "active_product_task",
      aiCeoTaskContextExpanded: true,
    });
    pulseFlowTarget("#view-cockpit .cockpit-market-panel");
    return;
  }
  if (key === "account") state.saasSettingsTab = "account";
  if (key === "model") state.saasSettingsTab = "model";
  if (key === "billing") state.saasSettingsTab = "billing";
  setView(view, {
    preserveFlowKey: Boolean(key),
    ...(view === "cockpit" && key
      ? { aiCeoTaskContextMode: "active_product_task", aiCeoTaskContextExpanded: true }
      : {}),
  });
  if (key === "source") pulseFlowTarget("#view-connect .source-intake-panel");
  else if (key === "product" || key === "finance") pulseFlowTarget("#view-product");
  else if (key === "media") pulseFlowTarget("#view-media");
  else if (key === "confirm") pulseFlowTarget("#view-confirm");
  else if (key === "bulk") pulseFlowTarget("#view-bulk");
  else if (key === "service") pulseFlowTarget("#view-service");
  else if (key === "account" || key === "model") pulseFlowTarget("#view-connect");
  else if (key === "billing") pulseFlowTarget("#view-connect .saas-settings-clean-content");
  else if (key === "audit") pulseFlowTarget("#view-activity");
  else if (key) pulseFlowTarget(`#view-${view}`);
}

