function refreshSaasMediaGeneratedAssetSurfaces() {
  const view = document.querySelector("#view-media");
  if (!view) return;
  const ctx = saasMerchantWorkbenchContext();
  const canvasGrid = view.querySelector(".media-canvas-grid");
  if (canvasGrid) setJiejingTrustedHtml(canvasGrid, trustedJiejingHtml(renderSaasMediaCanvasGrid(ctx), "media.canvas_grid"));
  const generatedPanel = view.querySelector(".saas-media-generated-assets");
  if (generatedPanel) {
    replaceJiejingTrustedHtml(generatedPanel, trustedJiejingHtml(renderSaasMediaGeneratedAssetsPanel(ctx), "media.generated_assets"));
  }
}

const saasMediaJobCurrentSessionBackendEvidence = new WeakSet();
const saasMediaJobUntrustedUiCacheEvidence = new WeakSet();

function markSaasMediaJobsAsCurrentSessionBackendEvidence(jobs = []) {
  (Array.isArray(jobs) ? jobs : [jobs]).forEach((job) => {
    if (!job || typeof job !== "object") return;
    saasMediaJobCurrentSessionBackendEvidence.add(job);
    saasMediaJobUntrustedUiCacheEvidence.delete(job);
  });
  return jobs;
}

function markSaasMediaJobsAsUntrustedUiCache(jobs = []) {
  (Array.isArray(jobs) ? jobs : [jobs]).forEach((job) => {
    if (!job || typeof job !== "object") return;
    saasMediaJobUntrustedUiCacheEvidence.add(job);
    saasMediaJobCurrentSessionBackendEvidence.delete(job);
  });
  return jobs;
}

function saasMediaJobHasCurrentSessionBackendEvidence(job = null) {
  return Boolean(
    job &&
      typeof job === "object" &&
      saasMediaJobCurrentSessionBackendEvidence.has(job) &&
      !saasMediaJobUntrustedUiCacheEvidence.has(job),
  );
}

function upsertSaasMediaAssetJobForDisplay(job = {}, replaceId = "") {
  if (!job || typeof job !== "object") return;
  const jobId = String(job.media_job_id || job.idempotency_key || job.queue_job_id || "");
  state.saasMediaAssetJobs = [
    job,
    ...(state.saasMediaAssetJobs || []).filter((item) => {
      const currentId = String(item?.media_job_id || item?.idempotency_key || item?.queue_job_id || "");
      return currentId && currentId !== jobId && currentId !== replaceId;
    }),
  ].slice(0, 8);
  saveSaasProtectedStateSnapshot();
  const panel = document.querySelector("#view-media .saas-media-asset-jobs");
  if (panel) replaceJiejingTrustedHtml(panel, trustedJiejingHtml(renderSaasMediaAssetJobsPanel(), "media.asset_jobs"));
  refreshSaasMediaGeneratedAssetSurfaces();
}

function readSaasMediaReviewEvidenceFromActiveModal(mediaJobId, hasVideoAsset = false) {
  const modal = document.querySelector("#assetModal");
  const boundJobId = String(modal?.dataset?.mediaReviewJobId || "").trim();
  if (!modal || modal.hidden || !mediaJobId || boundJobId !== mediaJobId) return null;
  const checks = Array.from(modal.querySelectorAll("[data-media-review-check]"));
  const checkedIds = new Set(
    checks
      .filter((input) => input.checked === true)
      .map((input) => String(input.dataset.mediaReviewCheck || "").trim())
      .filter(Boolean),
  );
  const requiredIds = [
    "product_structure",
    "product_appearance",
    "product_claims",
    ...(hasVideoAsset ? ["video_structure", "video_usage"] : []),
    "commercial_rights",
    "platform_claims",
    "listing_draft_boundary",
  ];
  if (checks.length !== requiredIds.length || requiredIds.some((id) => !checkedIds.has(id))) return null;
  return {
    media_job_id: mediaJobId,
    acknowledged_review_items: requiredIds,
    fact_consistency_confirmed: ["product_structure", "product_appearance", "product_claims"].every((id) => checkedIds.has(id)),
    commercial_rights_confirmed: checkedIds.has("commercial_rights"),
    platform_rules_checked: ["platform_claims", "listing_draft_boundary"].every((id) => checkedIds.has(id)),
    motion_and_usage_consistency_confirmed:
      !hasVideoAsset || ["video_structure", "video_usage"].every((id) => checkedIds.has(id)),
  };
}

async function approveLatestSaasMediaAssetJobForListingDraft() {
  const job = latestSaasMediaAssetJobWithManifest({ requireCurrentProject: true });
  const latestUnscopedJob = latestSaasMediaAssetJobWithManifest({ requireCurrentProject: false });
  const mediaJobId = String(job?.media_job_id || "").trim();
  if (!mediaJobId) {
    if (latestUnscopedJob && !saasMediaAssetJobMatchesListingProject(latestUnscopedJob)) {
      showActionToast("最近的素材属于另一个商品，已阻止审核。请先切回对应商品或为当前商品重新生成素材。");
      return null;
    }
    showActionToast("还没有可审核的真实素材任务。");
    return null;
  }
  if (saasMediaAssetJobIsConceptOnly(job)) {
    showActionToast("这是没有真实商品来源图的概念参考，不能通过 Listing 审核。请先上传实物图或有权使用的供应商来源图后重新生成。");
    return null;
  }
  if (job.live_provider_called !== true || !saasMediaManifestAssetsForListing(job).length) {
    showActionToast("素材服务没有返回可核验的真实文件，本次结果不能审核或回写 Listing。");
    return null;
  }
  const hasVideoAsset = saasMediaManifestAssetCards(job).some((asset) => asset.isVideo);
  const evidence = readSaasMediaReviewEvidenceFromActiveModal(mediaJobId, hasVideoAsset);
  if (!evidence || evidence.media_job_id !== mediaJobId) {
    showActionToast("素材审核未保存：请在当前素材预览中逐项确认，任务切换或少勾一项都会阻止提交。");
    return null;
  }
  try {
    const payload = await saasFetch(`/media-asset-jobs/${encodeURIComponent(mediaJobId)}/review`, {
      method: "POST",
      body: JSON.stringify({
        decision: "approve_for_listing_draft",
        fact_consistency_confirmed: evidence.fact_consistency_confirmed,
        commercial_rights_confirmed: evidence.commercial_rights_confirmed,
        platform_rules_checked: evidence.platform_rules_checked,
        motion_and_usage_consistency_confirmed: evidence.motion_and_usage_consistency_confirmed,
        acknowledged_review_items: evidence.acknowledged_review_items,
        note: hasVideoAsset
          ? "商家完整查看视频并确认产品结构、动作与真实用法一致，仅允许回写 Listing 草稿。"
          : "商家在素材预览中逐项确认，仅允许回写 Listing 草稿。",
      }),
    });
    const reviewed = payload?.media_asset_job;
    if (!reviewed) throw new Error("后端没有返回素材审核记录");
    markSaasMediaJobsAsCurrentSessionBackendEvidence(reviewed);
    upsertSaasMediaAssetJobForDisplay(reviewed, mediaJobId);
    state.mediaGenerationStatus = "generated";
    setText("#mediaProductionStatus", "素材已审核 · 可以回写 Listing 草稿");
    syncMediaGenerationActionState(readMediaGenerationConfig());
    showActionToast("素材审核已记录：现在可以回写 Listing 草稿，不会写入 eBay。");
    return reviewed;
  } catch (error) {
    showActionToast(`素材审核没有保存：${publicRuntimeText(error?.message || error).slice(0, 120)}`);
    return null;
  }
}

async function retrySaasMediaAssetJob(mediaJobId, button = null) {
  const cleanId = String(mediaJobId || "").trim();
  if (!cleanId) return null;
  const sourceJob = (state.saasMediaAssetJobs || []).find((job) => String(job?.media_job_id || "") === cleanId) || {};
  if (!(await requestMediaReworkAcceptance(sourceJob))) return null;
  const originalLabel = button?.textContent || "生成新版本";
  if (button) {
    button.disabled = true;
    button.textContent = "正在创建";
  }
  try {
    const payload = await saasFetch(`/media-asset-jobs/${encodeURIComponent(cleanId)}/retry`, {
      method: "POST",
      body: JSON.stringify({
        reason: "商家在素材工坊要求重做并保留上一版本",
        run_mode: "queued",
      }),
    });
    const mediaJob = payload?.media_asset_job && typeof payload.media_asset_job === "object" ? payload.media_asset_job : null;
    if (!mediaJob?.media_job_id) throw new Error("后端没有返回新素材版本");
    markSaasMediaJobsAsCurrentSessionBackendEvidence(mediaJob);
    upsertSaasMediaAssetJobForDisplay(mediaJob);
    state.mediaGenerationStatus = "submitted";
    setText("#mediaProductionStatus", `${saasMediaAssetJobVersionLabel(mediaJob)} 已创建 · 正在后台生成`);
    setText("#mediaPreviewNote", "旧版本已保留；新版本完成后仍需核对实物一致性、商用权和 eBay 素材规则。");
    showActionToast(`${saasMediaAssetJobVersionLabel(mediaJob)} 已创建：旧版本不会被覆盖。`);
    void pollSaasMediaAssetJobUntilReview({
      mediaJobId: mediaJob.media_job_id,
      sourceText: "素材工坊重做并保留上一版本",
      config: readMediaGenerationConfig(),
    });
    return mediaJob;
  } catch (error) {
    showActionToast(`新版本没有创建：${publicRuntimeText(error?.message || error).slice(0, 120)}`);
    return null;
  } finally {
    if (button) {
      button.disabled = false;
      button.textContent = originalLabel;
    }
  }
}

function requestMediaReworkAcceptance(sourceJob = {}) {
  if (pendingMediaGenerationAcceptance) return Promise.resolve(false);
  closeModals();
  const estimateText = saasMediaAssetJobCostLabel(sourceJob);
  setText("#mediaAcceptanceRole", "素材重做确认");
  setText("#mediaAcceptanceTitle", "确认创建新版本");
  setText(
    "#mediaAcceptanceIntro",
    "捷境会保留当前版本，并按原商品、来源图和生成要求创建一个新的待审核版本。",
  );
  setText("#mediaAcceptanceBoundary", estimateText);
  setText("#mediaAcceptanceSafety", "新版本仍需审核实物一致性和图片权利；不会自动发布、付款或写入 eBay。");
  const confirmButton = document.querySelector("#mediaAcceptanceConfirm");
  if (confirmButton) {
    confirmButton.textContent = "确认创建新版本";
    confirmButton.onclick = () => settleMediaGenerationAcceptance(true);
  }
  if (!mediaAcceptanceModal || !confirmButton) return Promise.resolve(false);
  mediaAcceptanceModal.hidden = false;
  document.body.classList.add("site-locked");
  return new Promise((resolve) => {
    pendingMediaGenerationAcceptance = resolve;
    window.setTimeout(() => confirmButton.focus(), 0);
  });
}

function saasMediaSourceAssetForListingDraft(draft = {}) {
  const packet =
    draft?.merchant_product_fact_packet && typeof draft.merchant_product_fact_packet === "object"
      ? draft.merchant_product_fact_packet
      : {};
  const records = Array.isArray(packet.source_records) ? packet.source_records : [];
  const candidates = records
    .filter(
      (record) =>
        record &&
        typeof record === "object" &&
        record.type === "merchant_product_image" &&
        Boolean(String(record.asset_id || "").trim()),
    )
    .map((record) => {
      const width = Math.max(0, Number(record.width || 0));
      const height = Math.max(0, Number(record.height || 0));
      const ratio = width && height ? width / height : 0;
      const squareScore = ratio ? Math.max(0, 120 - Math.abs(Math.log(ratio)) * 100) : 0;
      const resolutionScore = width && height ? Math.min(80, (width * height) / 10000) : 0;
      return {
        asset_id: String(record.asset_id || "").trim(),
        sha256: String(record.sha256 || "").trim().toLowerCase(),
        rights_status: String(record.rights_status || "").trim(),
        source_index: Number(record.source_index || 0),
        width,
        height,
        selection_score: squareScore + resolutionScore,
      };
    })
    .sort(
      (left, right) =>
        right.selection_score - left.selection_score ||
        (left.source_index || Number.MAX_SAFE_INTEGER) - (right.source_index || Number.MAX_SAFE_INTEGER),
    );
  if (!candidates.length) return null;
  const selected = candidates[0];
  return {
    asset_id: selected.asset_id,
    sha256: selected.sha256,
    rights_status: selected.rights_status,
    source_index: selected.source_index,
    width: selected.width,
    height: selected.height,
  };
}

function currentMediaStudioProductFacts(config = {}) {
  const ctx = isSaasPublicMvpMode() ? saasMerchantWorkbenchContext() : {};
  const activeDraftRaw = typeof activeListingDraft === "function" ? activeListingDraft() : null;
  const activeDraft =
    isSaasPublicMvpMode() && isLegacySampleMediaDraftKey(activeDraftRaw?.id || state.activeListingDraft)
      ? null
      : activeDraftRaw;
  const composer = state.saasListingComposerDraft || {};
  const merchantPacket =
    composer.merchant_product_fact_packet && typeof composer.merchant_product_fact_packet === "object"
      ? composer.merchant_product_fact_packet
      : {};
  const packetFacts = {
    ...(merchantPacket.derived_listing_suggestions && typeof merchantPacket.derived_listing_suggestions === "object"
      ? merchantPacket.derived_listing_suggestions
      : {}),
    ...(merchantPacket.source_confirmed_facts && typeof merchantPacket.source_confirmed_facts === "object"
      ? merchantPacket.source_confirmed_facts
      : {}),
    ...(merchantPacket.merchant_confirmed_facts && typeof merchantPacket.merchant_confirmed_facts === "object"
      ? merchantPacket.merchant_confirmed_facts
      : {}),
  };
  const listingProject = saasCurrentListingProjectIdentity(composer);
  const latestReport = latestSaasReportByTypes(["listing.package", "product.listing", "ai_ceo.market_research", "market.report"]);
  const productName = publicRuntimeText(
    composer.product ||
      composer.title ||
      activeDraft?.titleCn ||
      latestReport?.title ||
      "当前商品",
  );
  const store = ctx.store || activeSaasStore();
  const upload = state.saasMediaSourceUpload && typeof state.saasMediaSourceUpload === "object" ? state.saasMediaSourceUpload : null;
  const reportSourceAsset = saasMediaSourceAssetForListingDraft(composer);
  const structuredListingProject = saasNormalizeListingProjectIdentity(composer.listing_project_identity);
  const structuredUploadProject = saasNormalizeListingProjectIdentity(upload?.listing_project_identity);
  const rawUploadProject = upload?.listing_project_identity && typeof upload.listing_project_identity === "object" ? upload.listing_project_identity : {};
  const uploadHasProjectBinding = Boolean(
    String(upload?.listing_project_key || "").trim() ||
      [rawUploadProject.key, rawUploadProject.source_report_id, rawUploadProject.source_id, rawUploadProject.candidate_id].some((value) =>
        String(value || "").trim(),
      ),
  );
  const standaloneUploadMatches = Boolean(
    upload &&
      state.mediaTaskEntry === "single" &&
      config.entry === "single" &&
      !listingProject.key &&
      !structuredListingProject &&
      !uploadHasProjectBinding,
  );
  const uploadMatchesProject =
    standaloneUploadMatches ||
    (Boolean(upload && listingProject.key && upload.listing_project_key === listingProject.key) &&
      (!structuredListingProject ||
        Boolean(
          structuredUploadProject &&
          structuredUploadProject.key === structuredListingProject.key &&
          structuredUploadProject.source_report_id === structuredListingProject.source_report_id &&
          structuredUploadProject.candidate_id === structuredListingProject.candidate_id,
        )));
  const sourceAssetId = uploadMatchesProject ? upload.asset_id || "" : reportSourceAsset?.asset_id || "";
  const sourceImageSha256 = uploadMatchesProject ? upload.sha256 || "" : reportSourceAsset?.sha256 || "";
  const referenceImages = [config.referenceImageUrl]
    .map((url) => String(url || "").trim())
    .filter((url, index, values) => /^https:\/\//i.test(url) && values.indexOf(url) === index);
  const material = publicRuntimeText(activeDraft?.material || packetFacts.material || composer.material || "待补");
  const dimensions = activeDraft?.dimensions || packetFacts.product_dimensions_cm || composer.publish_prefill?.product_dimensions_cm || composer.dimensions || null;
  const netWeightG = packetFacts.net_weight_g || "";
  const allowedClaims = [
    productName && productName !== "当前商品" ? `商品名称：${productName}` : "",
    material && !["待补", "待确认"].includes(material) ? `材质：${material}` : "",
    dimensions ? `尺寸：${publicRuntimeText(dimensions)}` : "",
    netWeightG ? `商品净重：${publicRuntimeText(netWeightG)} g（不等于包装重量）` : "",
  ].filter(Boolean);
  return {
    product: productName,
    listing_project_identity: listingProject.key
      ? {
          key: listingProject.key,
          source_report_id: listingProject.source_report_id || listingProject.source_id || "",
          candidate_id: listingProject.candidate_id || "",
        }
      : null,
    listing_project_key: listingProject.key,
    listing_draft_id: listingProject.key || "",
    listing_source_id: listingProject.source_report_id || listingProject.source_id || "",
    selected_candidate_id: listingProject.candidate_id,
    marketplace: store?.marketplace || "EBAY_US",
    source: config.entry === "single" ? "merchant_upload_or_local_image" : "listing_or_ai_ceo_workflow",
    supplier_facts: {
      material,
      package_dimensions_cm: dimensions,
      net_weight_g: netWeightG,
      logistics: activeDraft?.logistics || composer.logistics || "待补",
    },
    material_pending_label: ["待补", "待确认"].includes(material),
    dimensions_pending_label: !dimensions,
    allowed_claims: allowedClaims,
    forbidden_claims: ["未验证认证", "医疗功效", "未经授权品牌词", "夸大性能承诺"],
    reference_images: referenceImages,
    source_asset_id: sourceAssetId,
    source_image_sha256: sourceImageSha256,
    private_source_transport: sourceAssetId ? "backend_asset_id" : "",
    source_rights_status: uploadMatchesProject ? upload?.rights_status || "" : reportSourceAsset?.rights_status || "",
    source_bridge_contract: reportSourceAsset && !uploadMatchesProject ? "ai_ceo_private_source_asset_to_media_v1" : "merchant_media_upload_v1",
    target_marketplace_rules: {
      platform: "ebay",
      marketplace: store?.marketplace || "EBAY_US",
      no_auto_publish: true,
    },
  };
}

function saasMediaGenerationGroundingGate(productFacts = {}, config = {}) {
  const referenceImages = Array.isArray(productFacts.reference_images) ? productFacts.reference_images : [];
  const hasGroundedSource =
    Boolean(String(productFacts.source_asset_id || "").trim()) ||
    productFacts.private_source_transport === "backend_asset_id" ||
    referenceImages.some((url) => /^https:\/\//i.test(String(url || "").trim()));
  const qualityMode = config.qualityMode || mediaQualityModeKey(config.fidelity);
  const videoDurationSeconds = Number.isFinite(Number(config.videoDurationSeconds))
    ? Number(config.videoDurationSeconds)
    : mediaVideoDurationSeconds(config.videoPreset);
  const videoRequested = [6, 10].includes(videoDurationSeconds);
  const conceptOnly = !hasGroundedSource || qualityMode === "creative_exploration";
  return {
    allowed: hasGroundedSource || (qualityMode === "creative_exploration" && !videoRequested),
    conceptOnly,
    hasGroundedSource,
    videoRequested,
  };
}

function syncMediaGenerationActionState(config = readMediaGenerationConfig()) {
  const button = document.querySelector("#mediaGenerateImagesDraft");
  if (!button) return null;
  const groundingGate = saasMediaGenerationGroundingGate(currentMediaStudioProductFacts(config), config);
  const latestManifestJob = latestSaasMediaAssetJobWithManifest({ requireCurrentProject: true });
  const writebackGate = saasApprovedMediaWritebackGate(latestManifestJob);
  const hasCurrentSessionBackendEvidence = saasMediaJobHasCurrentSessionBackendEvidence(latestManifestJob);
  const listingWritebackAllowed = writebackGate.allowed && hasCurrentSessionBackendEvidence;
  button.disabled = !groundingGate.allowed;
  button.textContent = groundingGate.allowed
    ? groundingGate.conceptOnly
      ? "生成概念参考图"
      : "按当前设置生成"
    : "先上传来源图或选择概念探索";
  button.title = groundingGate.allowed
    ? groundingGate.conceptOnly
      ? "只生成不可刊登的概念参考图，不会回写 Listing"
      : "基于真实来源图生成待审核素材"
    : "默认刊登素材必须先上传有权使用的真实商品图；无来源图时只能选择创意场景探索";
  button.dataset.mediaGenerationGate = groundingGate.allowed
    ? groundingGate.conceptOnly
      ? "concept_only"
      : "source_grounded"
    : "needs_source";
  const writebackButton = document.querySelector("#mediaConfirmDraft");
  if (writebackButton) {
    writebackButton.disabled = !listingWritebackAllowed;
    writebackButton.textContent = listingWritebackAllowed
      ? "校验并回写产品刊登"
      : writebackGate.allowed && !hasCurrentSessionBackendEvidence
        ? "刷新后校验素材再回写"
      : groundingGate.conceptOnly
        ? "概念图不可回写 Listing"
        : latestManifestJob
          ? "完成素材审核后回写"
          : "生成并审核素材后回写";
    writebackButton.title = listingWritebackAllowed
      ? "点击后会重新向后端读取当前素材状态；校验通过才只回写产品刊登草稿"
      : writebackGate.allowed && !hasCurrentSessionBackendEvidence
        ? "这是本地展示缓存，不能授权回写；等待已登录会话刷新后端素材状态"
      : groundingGate.conceptOnly
        ? "概念探索没有真实商品来源图，只能用于判断方向，不能作为刊登素材"
        : latestManifestJob
          ? "先完成当前商品素材的实物一致性、商业使用权和平台规则审核"
          : "先基于有权使用的真实商品来源图生成素材并完成审核";
    writebackButton.dataset.mediaWritebackGate = listingWritebackAllowed
      ? "revalidation_required"
      : writebackGate.allowed && !hasCurrentSessionBackendEvidence
        ? "untrusted_ui_cache"
        : writebackGate.reason || "blocked";
  }
  if (listingWritebackAllowed) {
    setText(
      "#mediaDecisionSummary",
      "当前商品的素材已完成来源、实物一致性、商业使用权和平台规则审核；可以回写 Listing 草稿，真实发布仍需进入确认中心。",
    );
    setText("#mediaProductionTarget", "已审核素材可以回写产品刊登草稿");
  } else if (groundingGate.conceptOnly) {
    setText(
      "#mediaDecisionSummary",
      `当前任务：${config.entryLabel}，${config.count}概念参考图。没有真实商品来源图；结果只用于判断构图和场景方向，不可回写 Listing。`,
    );
    setText("#mediaProductionTarget", "只作概念方向参考，不进入产品刊登");
  } else if (!groundingGate.allowed) {
    setText("#mediaProductionTarget", "上传真实来源图后再生成待审核素材");
  } else {
    setText("#mediaProductionTarget", "审核实物一致性后回写产品刊登草稿");
  }
  return groundingGate;
}

function buildSaasMediaAssetJobPayload(sourceText, config = {}) {
  const store = activeSaasStore();
  const imageCount = Math.max(1, Math.min(Number.parseInt(config.count, 10) || 4, 4));
  const imageSizes = [config.size || "1:1"].filter(Boolean);
  const sceneTypes = [config.scene || "white_background", config.type || "listing_assets"].filter(Boolean);
  const productFacts = currentMediaStudioProductFacts(config);
  const groundedReferenceImages = (Array.isArray(productFacts.reference_images) ? productFacts.reference_images : [])
    .map((url) => String(url || "").trim())
    .filter((url) => /^https:\/\//i.test(url));
  const generationTier = config.generationTierKey || mediaGenerationTierKey(config.generationTier);
  const qualityMode = config.qualityMode || mediaQualityModeKey(config.fidelity);
  const factLocks = Array.isArray(config.factLocks) && config.factLocks.length ? [...config.factLocks] : [...MEDIA_FACT_LOCKS];
  const groundingGate = saasMediaGenerationGroundingGate(productFacts, config);
  const outputSafetyMode = groundingGate.conceptOnly ? "concept_reference_only" : "reference_grounded_listing_draft";
  const videoPreset = String(config.videoPreset || "").trim();
  const videoDurationSeconds = Number(config.videoDurationSeconds || mediaVideoDurationSeconds(videoPreset));
  const videoRequested = [6, 10].includes(videoDurationSeconds);
  const videoIntent = "appearance_showcase";
  const motionConstraints = [
    "camera_motion_only",
    "product_remains_static",
    "no_hands_or_people",
    "no_use_or_installation_demo",
    "no_open_close_fold_bend_or_transform",
  ];
  const videoPrompt = videoRequested
    ? `Create a ${videoDurationSeconds}-second appearance-only eBay product showcase for ${productFacts.product || "the confirmed product"}. Use the grounded product image as the first frame. Camera motion only; the product must remain completely static. Do not show hands, people, use, installation, opening, closing, folding, bending, transformation or implied operation. Preserve exact product geometry, parts, proportions, color, material and visible brand marks. Do not add unsupported claims, prices or promotional text.`
    : "";
  const imageBudgetByTier = { draft: 60, standard: 120, high_quality: 260 };
  const videoBudgetByDuration = { 6: 900, 10: 1500 };
  const idempotencySource = JSON.stringify({
    store_id: store?.store_id || "",
    listing_project_identity: productFacts.listing_project_identity || null,
    listing_project_key: productFacts.listing_project_key || "",
    source_asset_id: String(productFacts.source_asset_id || "").trim(),
    source_image_sha256: String(productFacts.source_image_sha256 || "").trim().toLowerCase(),
    reference_images: [...groundedReferenceImages].sort(),
    sourceText,
    platform: config.platform || "",
    count: imageCount,
    size: imageSizes.join(","),
    scene: sceneTypes.join(","),
    type: config.type || "",
    generation_tier: generationTier,
    quality_mode: qualityMode,
    fact_locks: factLocks,
    video_preset: videoPreset,
    video_duration_seconds: videoDurationSeconds,
    video_requested: videoRequested,
    video_intent: videoIntent,
    motion_constraints: motionConstraints,
    commercial_rights_confirmed: config.commercialRightsConfirmed === true,
    concept_only_accepted: config.conceptOnlyAccepted === true,
  });
  return {
    provider_job_key: "media.asset_generation",
    title: `${productFacts.product || "当前商品"}素材清单`,
    idempotency_key: `media-studio-${Math.abs(hashString(idempotencySource))}`,
    inputs: {
      model_provider: state.saasModelSettings?.provider || "account_model_or_platform_default",
      media_provider: "provider_neutral",
      creative_job_spec: {
        job_type: "eBay_listing_asset_package",
        platform: config.platform || "eBay",
        output_count: imageCount,
        output_type: config.type || "listing_assets",
        image_sizes: imageSizes,
        scene_types: sceneTypes,
        text_rule: "no_text_no_numbers_no_certifications",
        fidelity: config.fidelity || "fact_checked",
        generation_tier: generationTier,
        quality_mode: qualityMode,
        fact_locks: factLocks,
        facts_may_not_be_unlocked_by_merchant: true,
        output_safety_mode: outputSafetyMode,
        reference_image_required_for_listing_use: true,
        video_preset: videoPreset || "不生成视频",
        video_duration_seconds: videoDurationSeconds,
        video_prompt: videoPrompt,
        video_intent: videoIntent,
        motion_constraints: motionConstraints,
        workflow_source: "media_studio_generate_button",
        blocked_claims: ["unverified_certification", "medical_claim", "brand_authorization_without_proof"],
      },
      product_facts: productFacts,
      commercial_rights_confirmed: config.commercialRightsConfirmed === true,
      concept_only_accepted: config.conceptOnlyAccepted === true,
      live_provider_requested: true,
      video_generation_requested: videoRequested,
      image_count: imageCount,
      image_sizes: imageSizes,
      scene_types: sceneTypes,
      reference_image_url: groundedReferenceImages[0] || "",
      video_script: videoRequested ? `${videoDurationSeconds} second product demo` : "",
      video_prompt: videoPrompt,
      video_duration_seconds: videoDurationSeconds,
      generation_tier: generationTier,
      quality_mode: qualityMode,
      cost_limit_cents:
        imageCount * (imageBudgetByTier[generationTier] || imageBudgetByTier.standard) +
        (videoRequested ? videoBudgetByDuration[videoDurationSeconds] || 1500 : 0),
      timeout_seconds: videoRequested ? 600 : generationTier === "high_quality" ? 90 : 60,
    },
    run_mode: "queued",
  };
}

async function pollSaasMediaAssetJobUntilReview({ mediaJobId, sourceText, config, optimisticId = "" } = {}) {
  const cleanMediaJobId = String(mediaJobId || "").trim();
  if (!cleanMediaJobId) return null;
  state.saasMediaAssetJobPolls = state.saasMediaAssetJobPolls || {};
  if (state.saasMediaAssetJobPolls[cleanMediaJobId]) return null;
  state.saasMediaAssetJobPolls[cleanMediaJobId] = true;
  try {
    for (let attempt = 0; attempt < 240; attempt += 1) {
      if (attempt) await new Promise((resolve) => window.setTimeout(resolve, 2000));
      let response;
      try {
        response = await saasFetch(`/media-asset-jobs/${encodeURIComponent(cleanMediaJobId)}`);
      } catch (error) {
        if (attempt < 239) continue;
        throw error;
      }
      const mediaJob = response?.media_asset_job && typeof response.media_asset_job === "object" ? response.media_asset_job : null;
      if (!mediaJob) continue;
      markSaasMediaJobsAsCurrentSessionBackendEvidence(mediaJob);
      upsertSaasMediaAssetJobForDisplay(mediaJob, optimisticId);
      const status = String(mediaJob.status || "");
      const liveAssetsReturned =
        mediaJob.live_provider_called === true && Array.isArray(mediaJob.asset_manifest) && mediaJob.asset_manifest.length > 0;
      if (liveAssetsReturned && ["waiting_review", "approved_for_listing"].includes(status)) {
        state.mediaGenerationStatus = "generated";
        runMediaGenerationFromCeo(sourceText, {
          ...config,
          backendMediaJobId: cleanMediaJobId,
          returnedAssetCount: mediaJob.asset_manifest.length,
          conceptOnly: saasMediaAssetJobIsConceptOnly(mediaJob),
          hasGroundedSource: saasMediaGenerationGroundingGate(saasMediaAssetJobProductFacts(mediaJob), config).hasGroundedSource,
        });
        refreshSaasMediaGeneratedAssetSurfaces();
        const conceptOnly = saasMediaAssetJobIsConceptOnly(mediaJob);
        setText("#mediaProductionStatus", conceptOnly ? "概念图已返回 · 不可用于刊登" : "真实素材已返回 · 等待审核");
        setText(
          "#mediaPreviewNote",
          conceptOnly ? "已生成概念参考图；仅供视觉方向讨论，不可审核为 Listing 素材。" : "真实图片或视频已进入素材清单，先审核实物一致性、商业使用权和 eBay 素材规则，再回写 Listing。",
        );
        showActionToast(conceptOnly ? "概念参考图已返回：不可用于刊登。" : "真实素材已返回：先审核，不会直接发布。");
        return mediaJob;
      }
      if (["needs_rework", "validation_failed", "failed", "cancelled"].includes(status)) {
        state.mediaGenerationStatus = "needs_rework";
        setText("#mediaProductionStatus", "素材任务需要调整 · 没有生成可用素材");
        setText("#mediaPreviewNote", "请查看任务缺口并调整商品事实或素材要求；本次结果不会回写 Listing。");
        showActionToast("素材任务没有生成可用结果，请调整资料后重试。");
        return mediaJob;
      }
      state.mediaGenerationStatus = status === "running" ? "submitted" : "queued";
      setText("#mediaProductionStatus", status === "running" ? "素材正在生成 · 可以继续浏览其他页面" : "素材任务已排队 · 可以继续浏览其他页面");
    }
    setText("#mediaProductionStatus", "素材仍在后台生成 · 稍后刷新查看");
    setText("#mediaPreviewNote", "任务没有被取消；生成完成后会进入素材清单，未审核前不会回写 Listing。");
    return null;
  } catch (error) {
    console.warn(`[JIEJING media job polling skipped] ${error?.message || error}`);
    setText("#mediaProductionStatus", "暂时无法刷新素材进度 · 稍后重试");
    return null;
  } finally {
    delete state.saasMediaAssetJobPolls[cleanMediaJobId];
  }
}

function saasMediaQueueFailureView(error = {}) {
  const status = Number(error?.status || error?.payload?.status || 0);
  const backendReason = publicRuntimeText(
    error?.payload?.error || error?.payload?.message || error?.message || "素材任务暂未创建。",
  ).slice(0, 180);
  if (status === 402) {
    return {
      statusText: "素材点不足 · 后端任务未创建",
      note: `${backendReason} 本次没有调用生成服务，也没有消耗素材点；补充素材点后可从当前步骤重试。`,
      toast: "素材点不足：没有调用生成服务，也没有消耗素材点。",
    };
  }
  if (status === 422) {
    return {
      statusText: "商品资料待补 · 后端任务未创建",
      note: `${backendReason} 补齐页面提示的资料后可从当前步骤重试，本次没有调用生成服务。`,
      toast: "商品资料尚未通过生成前检查：本次没有调用生成服务。",
    };
  }
  return {
    statusText: "素材草稿已整理 · 后端任务暂未创建",
    note: `${backendReason} 本次不会标记为可发布素材，请从当前步骤重试。`,
    toast: "素材任务暂未创建：本次不会作为可发布素材。",
  };
}

async function queueSaasMediaAssetJobFromStudio(sourceText, config = {}) {
  if (!isSaasPublicMvpMode()) return null;
  const store = activeSaasStore();
  if (!store?.store_id) {
    setText("#mediaProductionStatus", "素材草稿已整理 · 等待店铺工作区");
    setText("#mediaPreviewNote", "还没有可用的店铺工作区，素材只保留为本页草稿，不会标记为可发布素材。");
    return null;
  }
  const payload = buildSaasMediaAssetJobPayload(sourceText, config);
  const optimisticId = `local-${payload.idempotency_key}`;
  upsertSaasMediaAssetJobForDisplay({
    media_job_id: optimisticId,
    idempotency_key: payload.idempotency_key,
    job: { job_spec: payload },
    status: "queued",
    merchant_visible_states: ["素材任务正在创建"],
    asset_manifest: [],
    asset_manifest_validation: { status: "queued" },
    asset_version: {
      contract_version: "2026-07-11-media-asset-version-v1",
      version: 1,
      generation_reason: "initial_generation",
      immutable_prior_versions: true,
    },
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString(),
  });
  try {
    const response = await saasFetch(`/stores/${encodeURIComponent(store.store_id)}/provider-jobs/queue`, {
      method: "POST",
      body: JSON.stringify(payload),
    });
    const mediaJob = response.media_asset_job && typeof response.media_asset_job === "object" ? response.media_asset_job : null;
    if (!mediaJob?.media_job_id) throw new Error("media asset job missing from backend response");
    markSaasMediaJobsAsCurrentSessionBackendEvidence(mediaJob);
    upsertSaasMediaAssetJobForDisplay(mediaJob, optimisticId);
    const liveAssetsReturned = mediaJob.live_provider_called === true && Array.isArray(mediaJob.asset_manifest) && mediaJob.asset_manifest.length > 0;
    state.mediaGenerationStatus = liveAssetsReturned ? "generated" : "submitted";
    if (liveAssetsReturned) {
      runMediaGenerationFromCeo(sourceText, {
        ...config,
        backendMediaJobId: mediaJob.media_job_id,
        returnedAssetCount: mediaJob.asset_manifest.length,
        conceptOnly: saasMediaAssetJobIsConceptOnly(mediaJob),
        hasGroundedSource: saasMediaGenerationGroundingGate(saasMediaAssetJobProductFacts(mediaJob), config).hasGroundedSource,
      });
      refreshSaasMediaGeneratedAssetSurfaces();
    } else {
      renderMediaQualityBoard(config);
      renderGlobalFlowBar();
      void pollSaasMediaAssetJobUntilReview({
        mediaJobId: mediaJob.media_job_id,
        sourceText,
        config,
        optimisticId,
      });
    }
    const conceptOnly = saasMediaAssetJobIsConceptOnly(mediaJob);
    setText("#mediaProductionStatus", liveAssetsReturned ? conceptOnly ? "概念图已返回 · 不可用于刊登" : "真实素材已返回 · 等待审核" : "素材任务已创建 · 等待生成结果");
    setText(
      "#mediaPreviewNote",
      liveAssetsReturned
        ? conceptOnly ? "已生成概念参考图；仅供视觉方向讨论，不可审核为 Listing 素材。" : "真实图片或视频已进入素材清单，先审核实物一致性、商业使用权和 eBay 素材规则，再回写 Listing。"
        : "素材任务已提交，正在等待生成服务返回文件；可以继续浏览，勿重复提交。",
    );
    showActionToast(liveAssetsReturned ? conceptOnly ? "概念参考图已返回：不可用于刊登。" : "真实素材已返回：先审核，不会直接发布。" : "素材任务已创建：未返回真实图片前不会标记为已出图。");
    return mediaJob;
  } catch (error) {
    console.warn(`[JIEJING media job queue skipped] ${error?.message || error}`);
    const failure = saasMediaQueueFailureView(error);
    upsertSaasMediaAssetJobForDisplay(
      {
        media_job_id: `local-media-job-error-${Date.now()}`,
        status: "needs_rework",
        merchant_visible_states: ["素材任务暂未创建"],
        asset_manifest: [],
        asset_manifest_validation: { status: "backend_unavailable" },
        created_at: new Date().toISOString(),
        updated_at: new Date().toISOString(),
      },
      optimisticId,
    );
    setText("#mediaProductionStatus", failure.statusText);
    setText("#mediaPreviewNote", failure.note);
    showActionToast(failure.toast);
    return null;
  }
}

async function handleMediaGenerateImagesDraftClick() {
  if (pendingMediaGenerationAcceptance) return;
  const config = readMediaGenerationConfig();
  const productFacts = currentMediaStudioProductFacts(config);
  const groundingGate = saasMediaGenerationGroundingGate(productFacts, config);
  if (!groundingGate.allowed) {
    state.mediaGenerationStatus = "needs_source";
    setMediaNewTaskMode();
    setText("#mediaProductionStatus", groundingGate.videoRequested ? "视频需要真实商品图 · 尚未调用生成服务" : "先上传真实商品图 · 尚未调用生成服务");
    setText(
      "#mediaPreviewNote",
      groundingGate.videoRequested
        ? "视频必须以真实商品图作为首帧，只允许镜头运动，不会凭文字虚构商品用法。"
        : "默认刊登素材必须基于实拍图或有权使用的供应商图。上传后再生成，避免浪费额度和生成与实物不符的图片。",
    );
    showActionToast("先上传真实商品图：本次没有调用付费素材服务。只有明确选择“创意场景探索”时，才允许生成不可刊登的概念参考图。");
    return;
  }
  const acceptanceConfirmed = await requestMediaGenerationAcceptance(groundingGate);
  if (!acceptanceConfirmed) {
    state.mediaGenerationStatus = "needs_rights_confirmation";
    if (groundingGate.conceptOnly) state.mediaGenerationStatus = "needs_concept_acceptance";
    setText(
      "#mediaProductionStatus",
      groundingGate.conceptOnly ? "概念参考边界尚未确认 · 未调用生成服务" : "图片权利尚未确认 · 未调用生成服务",
    );
    setText(
      "#mediaPreviewNote",
      groundingGate.conceptOnly
        ? "请先确认当前结果只作概念参考、不可刊登；未确认前不会预留或消耗素材点。"
        : "请先确认你有权把这张商品图用于商业素材和 AI 再生成；未确认前不会预留或消耗素材点。",
    );
    showActionToast("已停止：本次没有调用付费素材服务，也没有消耗素材点。");
    return;
  }
  config.commercialRightsConfirmed = groundingGate.hasGroundedSource === true;
  config.conceptOnlyAccepted = groundingGate.conceptOnly === true;
  const text =
    config.entry === "single"
      ? `请基于本次商品图，使用「${config.template}」，按 ${config.platform} 生成 ${config.count} ${config.type}，尺寸使用 ${config.size}，场景为 ${config.scene}，质量为 ${config.generationTier}，还原要求为 ${config.fidelity}，并列出正式发布前需要补充的资料。`
      : `请基于当前商品草稿，使用「${config.template}」，按 ${config.platform} 生成 ${config.count} ${config.type}，尺寸使用 ${config.size}，场景为 ${config.scene}，质量为 ${config.generationTier}，还原要求为 ${config.fidelity}，输出后回写到商品草稿。`;
  addCeoMessage(text, "我会先整理素材草稿和素材清单任务；通过审核前不会把图片、视频脚本或详情页标记为可发布素材。");
  state.mediaGenerationStatus = "submitted";
  renderMediaQualityBoard(config);
  renderGlobalFlowBar();
  setText("#mediaProductionStatus", "素材草稿已整理 · 正在创建素材任务");
  setText("#mediaPreviewNote", "素材草稿会进入素材清单审核；正式发布前仍需核对真实尺寸、材质、重量、图片权利和平台规则。");
  showActionToast("素材草稿已整理：正在创建后端素材任务。");
  queueSaasMediaAssetJobFromStudio(text, config);
}

async function handleMediaScriptDraftClick() {
  const config = readMediaGenerationConfig();
  const returnedVideo = saasMediaManifestAssetCards().find((card) => card.isVideo);
  if (returnedVideo) {
    openAssetPreview(returnedVideo.key);
    return;
  }
  const product = activeMediaDraftProductNameForDisplay();
  const scriptPreset = config.videoDurationSeconds ? config.videoPreset : "10 秒产品展示视频";
  const text = `请只为“${product}”生成一份${scriptPreset}的${config.voice}视频脚本与分镜。必须包含开场钩子、逐镜头画面、字幕、商品事实待确认项和发布前审核清单；不要声称视频文件已经生成，不要发布。`;
  setText("#mediaProductionStatus", "正在生成脚本与分镜 · 不生成虚假视频");
  showActionToast("正在生成文字脚本；视频文件只有素材生成服务实际返回后才会显示。");
  const command = buildSaasCeoCommand(text, saasMerchantWorkbenchContext());
  const payload = await requestSaasAiCeoChat(command);
  const chat = payload?.ai_ceo_chat && typeof payload.ai_ceo_chat === "object" ? payload.ai_ceo_chat : {};
  const status = String(chat.status || "");
  const script = saasAiCeoProductizedAnswerText(chat.answer || "", status);
  if (!script || /blocked|failed|unavailable/.test(status)) {
    setText("#mediaProductionStatus", "脚本暂未生成 · 可以稍后重试");
    showActionToast("脚本暂未生成：AI 连接没有返回可用内容，本次不会显示视频占位结果。");
    return;
  }
  state.saasMediaScriptDraft = {
    contract_version: "2026-07-10-media-script-draft-v1",
    product,
    script,
    videoProviderReady: saasMediaGenerationState().videoReady === true,
    created_at: new Date().toISOString(),
    triggers_real_platform_write: false,
  };
  upsertActivity("media-script-draft", {
    role: "素材生成",
    title: `${product}视频脚本与分镜`,
    action: "AI 根据当前商品草稿生成文字脚本、镜头表、字幕和待确认事实；素材生成服务没有返回视频文件时，不标记为已生成视频。",
    sources: [`商品：${product}`, `规格：${scriptPreset}`, `语言：${config.voice}`],
    result: script,
    status: "脚本已生成",
    confidence: "待商家审核",
  });
  setText("#mediaProductionStatus", "脚本与分镜已生成 · 视频文件未生成");
  showActionToast("脚本与分镜已生成；当前没有视频文件，不会冒充视频成品。");
  openAssetPreview("script");
}

function syncMediaProjectDraft(button) {
  if (!button) return;
  if (button.dataset.mediaSaasReal === "1") {
    syncSaasMediaProjectDraft(button);
    return;
  }
  state.mediaTaskEntry = "project";
  setMediaChannelMode("flow");
  state.activeMediaDraft = button.dataset.mediaDraft || "incense";
  const title = button.dataset.mediaDraftTitle || "当前商品";
  const note = button.dataset.mediaDraftNote || "主图、场景图、详情页和视频脚本";
  const gap = button.dataset.mediaDraftGap || "尺寸、重量、材质";
  const status = button.dataset.mediaDraftStatus || "市场判断已完成 · 待素材";
  const profile = mediaDraftAssetProfiles[state.activeMediaDraft] || mediaDraftAssetProfiles.incense;
  document
    .querySelectorAll(".media-project-tab")
    .forEach((item) => item.classList.toggle("is-active", item === button));
  const sourceImg = document.querySelector(".media-input-thumb");
  if (sourceImg && profile?.source) sourceImg.src = profile.source;
  document.querySelectorAll(".media-canvas-card[data-asset-preview]").forEach((card) => {
    const key = card.dataset.assetPreview;
    const image = profile?.images?.[key] || profile?.source || "assets/jiejing-app-icon.svg";
    const cardTitle = profile?.cardTitles?.[key];
    const img = card.querySelector(".asset-preview-photo img");
    if (img) img.src = image;
    const strong = card.querySelector("strong");
    if (strong && cardTitle) strong.textContent = cardTitle;
    const copy = card.querySelector("p");
    if (copy && cardTitle) {
      copy.textContent =
        key === "video"
          ? `为「${title}」生成短视频封面、字幕脚本、字幕节奏和镜头顺序。`
          : `为「${title}」生成${cardTitle}，发布前核对实物和规格。`;
    }
  });
  setText("#mediaProjectPill", status);
  setText("#mediaProductionTitle", `${title}：${note}`);
  setText("#mediaProductionStatus", status);
  setText("#mediaProductionNeed", note);
  setText("#mediaProductionGap", gap);
  setText("#mediaSourceLabel", "流程导入");
  setText("#mediaSourceTitle", `流程导入：${title}商品草稿`);
  setText("#mediaSourceNote", "该商品已完成市场经理报告和产品经理刊登草稿，素材工坊自动读取图片需求、卖点、字段草稿和待补资料。");
  setText("#mediaFactLabel", "当前商品");
  setText("#mediaFactTitle", title);
  setText("#mediaFactNote", `下一步生成：${note}。待补资料：${gap}。`);
  setText("#mediaGapTitle", gap);
  setText("#mediaPreviewTitle", `${title}流程素材包`);
  setText("#mediaPreviewNote", `素材工坊已自动导入「${title}」的市场报告和产品经理刊登草稿。请选择平台、张数、尺寸和图片要求后生成本轮素材。`);
  setText("#mediaRouteStatus", "流程导入");
  setText("#mediaEntryStatus", "流程导入");
  setText("#mediaEntryNote", "读取市场报告和产品刊登草稿，不需要重复上传。");
  setText("#mediaRunStatus strong", `已切换到：${title}`);
  setText("#mediaRunStatus p", "可按右侧设置生成素材草稿；不会触发真实发布。");
  setText("#mediaLocalPath", "当前商品草稿");
  setText("#mediaLocalPathNote", "这是流程导入素材单；如需单独处理桌面的 1688 货源图，切换到“独立上传”通道后拖入图片。批量铺货通过的商品，也会先进入流程导入线。");
  const config = readMediaGenerationConfig({ entry: "project" });
  setText(
    "#mediaDecisionSummary",
    `当前是流程导入素材单：市场报告和产品刊登草稿已完成，使用「${config.template}」，按「${config.type}」和「${config.scene}」生成素材后回写产品刊登。`,
  );
  renderMediaQualityBoard(config);
}

function recordPdfExport(items, title, success = true) {
  const sourceTitles = items.map((item) => `${activityWorkType(item.role)}：${item.title}`).slice(0, 6);
  const statusText = success ? "已生成" : "被浏览器拦截";
  state.lastPdfTitle = title;
  upsertActivity(`pdf-export-${Date.now()}`, {
    role: "归档助手",
    title: `PDF 汇报${statusText}：${title}`,
    action:
    "商家点击 PDF 汇报后，系统把当前项目的 AI 汇报、来源记录、输出结论和待确认事项整理成可打印汇报。",
    sources: sourceTitles.length
      ? sourceTitles
      : ["当前项目暂无可导出的 AI 汇报"],
    result: success
      ? "PDF 汇报窗口已打开；如果需要保存，使用浏览器打印窗口选择“另存为 PDF”。这次导出动作已写入 AI 汇报。"
      : "浏览器阻止了弹窗。请允许当前页面弹窗后再次点击 PDF 汇报；这次尝试仍已写入 AI 汇报。",
    status: success ? "已完成" : "待处理",
    confidence: success ? "100%" : "60%",
  });
  setActivityFeedback(
    success
      ? `PDF 汇报已生成：${title}。这次导出动作已写入 AI 汇报。`
      : `PDF 汇报没有打开：${title}。浏览器可能拦截了弹窗。`,
  );
}

function runtimeStatusLabel(status = "") {
  if (!status) return "未连接";
  if (status === "completed") return "已完成";
  if (status === "completed_with_blocks") return "已完成，有缺口";
  if (status.includes("block")) return "被安全拦截";
  if (status.includes("partial")) return "部分完成";
  if (status.includes("success")) return "已完成";
  return status;
}

function runtimeStatusTone(status = "") {
  if (!status || !state.runtimeConnected) return "neutral";
  if (status === "completed") return "green";
  if (status === "completed_with_blocks" || status.includes("partial")) return "amber";
  if (status.includes("block") || status.includes("fail")) return "red";
  return "green";
}

function runtimeValidationLabel(status = "") {
  if (!status) return "未校验";
  if (status.includes("ready") || status === "manifest_ready") return "已就绪";
  if (status === "simulated_no_platform_write") return "已记录交接";
  if (status === "brief_only") return "任务包";
  if (status.includes("blocked")) return "待补齐";
  if (status.includes("missing")) return "缺资料";
  return status;
}

function runtimeValidationTone(status = "") {
  if (!status) return "neutral";
  if (status.includes("ready") || status === "manifest_ready") return "green";
  if (status === "simulated_no_platform_write") return "green";
  if (status === "brief_only") return "amber";
  if (status.includes("blocked") || status.includes("missing")) return "red";
  return "neutral";
}

function runtimeValidationTitle(key = "") {
  return (
    {
      report_contract: "报告可接力检查",
      listing_validation: "刊登资料包",
      asset_manifest_validation: "素材清单",
      customer_learning_validation: "客服学习包",
      finance_review_validation: "财务复核包",
      confirmation_package_validation: "确认中心包",
      ceo_final_report_validation: "CEO 汇总",
    }[key] || runtimeSectionTitle(key)
  );
}

function runtimeValidationIsBlocked(item = {}) {
  const status = String(item.validation_status || "");
  return status.includes("blocked") || status.includes("missing") || status.includes("fail");
}

function runtimeActionForTaskType(taskType = "") {
  if (taskType === "listing.package" || taskType === "source.match" || taskType === "finance.review") return "open-product";
  if (taskType === "asset.brief") return "open-media";
  if (taskType === "customer.learn_product") return "open-service";
  if (taskType === "confirmation.package") return "open-confirm";
  return "open-activity";
}

function runtimeMerchantAdvice(item = {}) {
  const taskType = item.task_type || "";
  const blocked = runtimeValidationIsBlocked(item);
  if (item.validation_key === "report_contract") {
    const map = {
      "market.data_packet": ["市场资料还不能支撑判断", "需要 eBay 信号、公开搜索、跨平台参考、货源和物流来源状态，齐了以后市场报告才可靠。", "回 AI 汇报看来源"],
      "market.report": ["市场报告还不能接下一步", "报告必须有品类概况、买家画像、价格带、竞品、关键词、风险和结论，否则产品经理无法继续刊登。", "回 AI 汇报"],
      "source.match": ["货源和履约资料还不完整", "需要明确货源路线、供应商候选、成本、包装、供应商问题和采购边界。", "回产品刊登补资料"],
      "listing.package": ["刊登资料还没达到 eBay 草稿标准", "标题、类目、状态、价格、库存、Item Specifics、图片视频、包裹资料和三政策必须能被系统读取。", "回产品刊登"],
      "asset.brief": ["素材任务还不能开工", "需要明确主图、场景图、详情页、视频、尺寸、数量和商用边界，素材工坊才知道生成什么。", "回素材工坊"],
      "customer.learn_product": ["客服还没学完产品", "客服需要产品档案、买家问题、FAQ、回复边界、自动回复模板和人工接管规则。", "回自动客服"],
      "finance.review": ["利润复核还缺字段", "需要售价、采购、平台费、物流、店铺订阅分摊、退货预留和下一步动作。", "回产品刊登补费用"],
      "confirmation.package": ["确认边界还不清楚", "系统必须知道哪些能自动做、哪些按默认规则、哪些每次确认、哪些直接禁止。", "查看确认中心"],
      "ceo.final_report": ["CEO 汇总还不能交付", "最终汇总要说清当前状态、来源健康度、报告是否齐、发布锁和下一步最小动作。", "回 AI 汇报"],
    };
    const [title, detail, next] = map[taskType] || ["报告还不能接下一步", "这份报告缺少系统可读取的固定栏目，补齐后才能继续推进。", "查看详情"];
    return {
      title: blocked ? title : `${runtimeTaskTitle(taskType)}已可接力`,
      detail: blocked ? detail : "这份报告的固定栏目已经齐，后续模块可以读取它继续推进；真实发布仍然要走确认中心。",
      next: blocked ? next : "查看确认中心",
      action: blocked ? runtimeActionForTaskType(taskType) : "open-confirm",
    };
  }
  const byKey = {
    listing_validation: ["刊登资料还缺关键项", "通常是供应商真实资料、eBay 类目字段、店铺三类政策或发布锁还没齐。", "回产品刊登补资料", "open-product"],
    asset_manifest_validation: ["素材清单还缺交付物", "素材必须有文件、尺寸、来源和商用状态，不能只写“已生成”。", "回素材工坊", "open-media"],
    customer_learning_validation: ["客服学习包还不完整", "客服要先掌握产品档案、FAQ、回复边界和人工接管规则。", "同步客服资料", "open-service"],
    finance_review_validation: ["费用利润还没算完整", "售价、采购、平台费、物流、包装、退货预留和利润金额要齐。", "补费用口径", "open-product"],
    confirmation_package_validation: ["确认中心边界还不完整", "发布、采购付款、退款、广告、改价、库存、政策和敏感客服承诺必须明确停点。", "检查确认中心", "open-confirm"],
    ceo_final_report_validation: ["AI CEO 汇总还缺下一步", "最终汇总必须把状态、来源健康度、发布锁和下一步最小动作说清楚。", "重生成 AI 汇报", "open-activity"],
  };
  const [title, detail, next, action] = byKey[item.validation_key] || ["有岗位包待补齐", item.summary || "系统定位到一个缺口，补齐后会继续推进。", "查看详情", "open-activity"];
  return {
    title: blocked ? title : `${runtimeValidationTitle(item.validation_key)}已就绪`,
    detail: blocked ? detail : "这部分已经达到可交接标准，后续模块可以读取并继续推进。",
    next: blocked ? next : "查看确认中心",
    action: blocked ? action : "open-confirm",
  };
}

function runtimeValidationPreviewItems(items = []) {
  const score = (item) => {
    const blocked = runtimeValidationIsBlocked(item) ? 0 : 20;
    const contract = item.validation_key === "report_contract" ? 4 : 0;
    const order = {
      "listing.package": 1,
      "asset.brief": 2,
      "customer.learn_product": 3,
      "finance.review": 4,
      "confirmation.package": 5,
      "market.report": 6,
      "ceo.final_report": 7,
    }[item.task_type] || 9;
    return blocked + contract + order;
  };
  return [...items].sort((a, b) => score(a) - score(b)).slice(0, 6);
}

function runtimeDirectValidationsFromReport(result) {
  const report = result?.report || {};
  return [
    "report_contract",
    "listing_validation",
    "asset_manifest_validation",
    "customer_learning_validation",
    "finance_review_validation",
    "confirmation_package_validation",
    "ceo_final_report_validation",
  ]
    .map((key) => {
      const validation = report[key];
      if (!validation) return null;
      return {
        task_id: result.task_id,
        task_type: result.task_type,
        validation_key: key,
        validator: validation.validator,
        validation_status: validation.status,
        summary: validation.summary,
      };
    })
    .filter(Boolean);
}

function runtimeValidationsForResult(result) {
  const fromSummary = (state.runtimeValidationSummary?.validations || []).filter((item) => item.task_id === result.task_id);
  return fromSummary.length ? fromSummary : runtimeDirectValidationsFromReport(result);
}

