function hasCompletedSaasOnboarding() {
  if (
    !isSaasPublicMvpMode() &&
    state.saasConnected &&
    ((state.saasStores || []).length ||
      (state.saasConnections || []).length ||
      (state.saasDataPackets || []).length ||
      (state.saasMediaAssetJobs || []).length ||
      (state.saasReports || []).length ||
      (state.saasConfirmations || []).length ||
      (state.saasExecutionResults || []).length)
  ) {
    return true;
  }
  // Public SaaS first-day guidance must be account-scoped; backend data must not bypass onboarding.
  try {
    return saasOnboardingDoneStorageKeys()
      .filter((key) => !(isSaasPublicMvpMode() && key === `${saasStorageKeys.onboardingDone}:browser`))
      .some((key) => localStorage.getItem(key) === "1");
  } catch (error) {
    return false;
  }
}

function markSaasOnboardingCompleted() {
  try {
    saasOnboardingDoneStorageKeys().forEach((key) => localStorage.setItem(key, "1"));
  } catch (error) {
    // Onboarding persistence is best effort; the in-session route still opens the workbench.
  }
}

