async function ensureSaasProtectedSessionForMutation() {
  if (!hasSaasProtectedSessionCandidate()) {
    const error = new Error("捷境登录已失效，请重新登录。");
    error.status = 401;
    error.code = "saas_session_expired";
    handleSaasUnrecoverableSession(error);
    throw error;
  }
  const session = await saasFetch("/me", { method: "GET", cache: "no-store" });
  if (!(session?.user?.user_id || session?.identity?.user_id)) {
    const error = new Error("捷境登录已失效，请重新登录。");
    error.status = 401;
    error.code = "saas_session_expired";
    handleSaasUnrecoverableSession(error);
    throw error;
  }
  return session;
}

async function saasFetchNdjsonWithTimeout(path, options = {}, timeoutMs = 60000, hooks = {}) {
  await ensureSaasProtectedSessionForMutation();
  const controller = typeof AbortController !== "undefined" ? new AbortController() : null;
  const headers = {
    accept: "application/x-ndjson, application/json",
    "content-type": "application/json",
    ...(options.headers || {}),
  };
  if (state.saasToken && shouldAttachSaasBearerToken()) headers.authorization = `Bearer ${state.saasToken}`;
  let timer = null;
  try {
    timer = setTimeout(() => {
      recordOptionalSaasSoftTimeout(path, timeoutMs);
      controller?.abort();
    }, timeoutMs);
    const response = await fetch(`${state.saasApiBase}${path}`, {
      ...options,
      cache: options.cache || "no-store",
      credentials: options.credentials || "include",
      headers,
      ...(controller ? { signal: controller.signal } : {}),
    });
    if (!response.ok) {
      const detail = await response.text();
      let payload = null;
      try {
        payload = JSON.parse(detail);
      } catch {
        payload = null;
      }
      const error = new Error(saasBackendErrorMessage(response.status, detail, payload));
      error.status = response.status;
      error.payload = payload;
      if (response.status === 401) {
        error.code = "saas_session_expired";
        handleSaasUnrecoverableSession(error);
        throw error;
      }
      if (payload?.ai_ceo_chat && typeof payload.ai_ceo_chat === "object") {
        return { ...payload, _http_status: Number(response.status || 0) || 0 };
      }
      throw error;
    }
    const contentType = response.headers.get("content-type") || "";
    if (contentType.includes("application/json")) return response.json();
    if (!contentType.includes("application/x-ndjson") || !response.body?.getReader) {
      throw new Error("AI CEO 流式响应协议暂时不可用，请稍后重试。");
    }
    const reader = response.body.getReader();
    const decoder = new TextDecoder("utf-8");
    let buffer = "";
    let streamedText = "";
    let finalPayload = null;
    const consumeLine = (line) => {
      const raw = String(line || "").trim();
      if (!raw) return;
      let event = null;
      try {
        event = JSON.parse(raw);
      } catch {
        return;
      }
      if (!event || typeof event !== "object" || event.secret_exposed === true) return;
      if (event.type === "delta" && typeof event.delta === "string" && event.delta) {
        streamedText = `${streamedText}${event.delta}`.slice(0, 120000);
        hooks.onDelta?.(event.delta, streamedText);
      } else if (event.type === "accepted") {
        hooks.onStage?.(event.stage || "model", event);
      } else if (event.type === "final" && event.payload && typeof event.payload === "object") {
        const logicalHttpStatus = Number(event.http_status || event.payload.http_status || 0) || 0;
        finalPayload = {
          ...event.payload,
          ...(logicalHttpStatus ? { _http_status: logicalHttpStatus } : {}),
        };
      }
      hooks.onEvent?.(event);
    };
    while (true) {
      const { value, done } = await reader.read();
      buffer += decoder.decode(value || new Uint8Array(), { stream: !done });
      const lines = buffer.split(/\r?\n/);
      buffer = lines.pop() || "";
      lines.forEach(consumeLine);
      if (done) break;
    }
    consumeLine(buffer);
    if (!finalPayload) throw new Error("AI CEO 流式响应未返回最终结果，请直接重试本轮问题。");
    return finalPayload;
  } catch (error) {
    if (error?.name === "AbortError") throw new Error(`AI CEO response timed out after ${timeoutMs}ms`);
    throw error;
  } finally {
    if (timer) clearTimeout(timer);
  }
}

