async function ensureSaasDemoSession() {
  const accountEpoch = saasAccountSessionEpoch;
  loadSaasSessionFromStorage();
  if (state.saasToken || hasSaasPersistentSessionHint()) {
    try {
      const me = await saasFetch("/me");
      assertSaasAccountSessionCurrent(accountEpoch);
      assertSaasLiveIdentityScope(me);
      if (me.user?.user_id) {
        state.saasIdentity = me.identity || null;
        state.saasUser = me.user || null;
        state.saasCompany = me.company || null;
        saveSaasSessionToStorage();
        return me;
      }
    } catch (error) {
      assertSaasAccountSessionCurrent(accountEpoch);
      // A temporary network failure is not proof that the login expired.
      if (!isSaasUnrecoverableSessionError(error)) throw error;
      if (!isSaasUnrecoverableSessionError(error) || state.saasSessionExpiryHandled !== true) {
        clearSaasSessionFromStorage({ preserveCeoThread: true, preservePendingListingGeneration: true });
      }
      throw error;
    }
  }
  if (!state.saasDemoBootstrapEnabled) {
    throw new Error(
      "当前公网页面需要已有捷境账号会话。运营测试入口仅限本地或明确启用 operator bootstrap 时使用。",
    );
  }

  const credentials = {
    email:
      safeWindowConfig("JIEJING_CONFIG", "operatorBootstrapEmail") ||
      safeWindowConfig("__JIEJING_CONFIG__", "operatorBootstrapEmail") ||
      "",
    password:
      safeWindowConfig("JIEJING_CONFIG", "operatorBootstrapPassword") ||
      safeWindowConfig("__JIEJING_CONFIG__", "operatorBootstrapPassword") ||
      "",
    company_name:
      safeWindowConfig("JIEJING_CONFIG", "operatorBootstrapCompany") ||
      safeWindowConfig("__JIEJING_CONFIG__", "operatorBootstrapCompany") ||
      "JIEJING Operator Workspace",
  };
  if ((!credentials.email || !credentials.password) && !isSaasPublicMvpMode() && defaultJiejingDemoBootstrapEnabled()) {
    const suffix = `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`;
    credentials.email = `operator-${suffix}@local.invalid`;
    credentials.password = `local-${suffix}`;
  }
  if (!credentials.email || !credentials.password) {
    throw new Error("Operator bootstrap requires explicit credentials from window.JIEJING_CONFIG.");
  }
  let session;
  try {
    session = await saasFetch("/auth/demo-session", {
      method: "POST",
      body: JSON.stringify(credentials),
    });
  } catch (error) {
    try {
      session = await saasFetch("/auth/register", {
        method: "POST",
        body: JSON.stringify(credentials),
      });
    } catch (registerError) {
      session = await saasFetch("/auth/login", {
        method: "POST",
        body: JSON.stringify({ email: credentials.email, password: credentials.password }),
      });
    }
  }
  assertSaasAccountSessionCurrent(accountEpoch);
  state.saasToken = session.token || "";
  saveSaasSessionToStorage();
  const me = await saasFetch("/me");
  assertSaasAccountSessionCurrent(accountEpoch);
  assertSaasLiveIdentityScope(me);
  state.saasIdentity = me.identity || null;
  state.saasUser = me.user || null;
  state.saasCompany = me.company || null;
  return me;
}

async function ensureSaasDemoStoreAndConnection() {
  if (state.saasStoreEnsurePromise) return state.saasStoreEnsurePromise;
  const accountEpoch = saasAccountSessionEpoch;
  const ensurePromise = (async () => {
  await ensureSaasDemoSession();
  assertSaasAccountSessionCurrent(accountEpoch);
  const storesPayload = await saasFetch("/stores");
  assertSaasAccountSessionCurrent(accountEpoch);
  state.saasStores = storesPayload.stores || [];
  const allConnectionsPayload = await saasFetch("/connections");
  assertSaasAccountSessionCurrent(accountEpoch);
  state.saasConnections = allConnectionsPayload.connections || [];
  const preferredStoreId = storedSaasStoreId();
  let store = preferredSaasStore(state.saasStores, {
    connections: state.saasConnections,
    preferredStoreId,
  });
  if (!store) {
    const created = await saasFetch("/stores", {
      method: "POST",
      body: JSON.stringify({
        platform: "ebay",
        store_name: "等待 eBay 授权",
        marketplace: "EBAY_US",
        stage: state.dna?.merchantStage || "store_opened",
        settings: {
          created_from: isSaasPublicMvpMode() ? "merchant_saas_onboarding" : "saas_frontend_store_onboarding",
          operator_seed: !isSaasPublicMvpMode() && state.saasDemoBootstrapEnabled === true,
          merchant_created_workspace: isSaasPublicMvpMode(),
          account_display_name: saasAccountDisplayName(),
          placeholder_store_name: true,
          real_platform_writes_enabled: isSaasRealPlatformWritesEnabled(),
        },
      }),
    });
    assertSaasAccountSessionCurrent(accountEpoch);
    store = created.store;
    state.saasStores = [store];
  }
  saveSaasSessionToStorage(store.store_id);

  if (!saasConnectionsForStoreId(store.store_id).some((item) => item.platform === "ebay")) {
    const connection = await saasFetch(`/stores/${encodeURIComponent(store.store_id)}/connections`, {
      method: "POST",
      body: JSON.stringify({
        platform: "ebay",
        connection_type: "oauth",
        status: "read_only_pending",
        scopes: ["sell.inventory.readonly", "sell.account.readonly", "sell.fulfillment.readonly"],
        create_secret_ref: !isSaasPublicMvpMode() && state.saasDemoBootstrapEnabled === true,
        metadata: {
          note: "Merchant eBay read-only workspace is pending official connection. No raw platform credential is stored in the front end.",
        },
      }),
    });
    assertSaasAccountSessionCurrent(accountEpoch);
    state.saasConnections = [connection.connection, ...state.saasConnections];
  }
  return store;
  })();
  state.saasStoreEnsurePromise = ensurePromise;
  try {
    return await ensurePromise;
  } finally {
    if (state.saasStoreEnsurePromise === ensurePromise) state.saasStoreEnsurePromise = null;
  }
}

function getLatestSaasEbaySyncSummary() {
  const direct = state.saasEbaySync && typeof state.saasEbaySync === "object" ? state.saasEbaySync : {};
  const latestTask = (state.saasTasks || []).find((task) => task && typeof task === "object" && task.task_type === "ebay_read_only_sync") || null;
  const taskOutput = latestTask?.output && typeof latestTask.output === "object" ? latestTask.output : {};
  const worker = direct.worker_result && typeof direct.worker_result === "object" ? direct.worker_result : {};
  const liveReadResult =
    (direct.live_read_result && typeof direct.live_read_result === "object" && direct.live_read_result) ||
    (worker.live_read_result && typeof worker.live_read_result === "object" && worker.live_read_result) ||
    (taskOutput.live_read_result && typeof taskOutput.live_read_result === "object" && taskOutput.live_read_result) ||
    {};
  const dataPacket =
    (direct.data_packet && typeof direct.data_packet === "object" && direct.data_packet) ||
    (worker.data_packet && typeof worker.data_packet === "object" && worker.data_packet) ||
    {};
  return {
    sync: { ...taskOutput, ...direct },
    live_read_result: liveReadResult,
    data_packet: dataPacket,
    task: latestTask,
  };
}

function getLatestSaasDataPacketRecord(latestSync = {}) {
  const storedPackets = sortedSaasDataPackets(state.saasDataPackets || []);
  const preferredIds = [
    activeSaasStore()?.store_id,
    storedSaasStoreId(),
    latestSaasConnection()?.store_id,
  ].map(normalizeSaasRecordStoreId).filter(Boolean);
  for (const storeId of preferredIds) {
    const match = storedPackets.find((packet) => packet.platform === "ebay" && saasRecordStoreId(packet) === storeId);
    if (match) return match;
  }
  const official = storedPackets.find(
    (packet) => packet.platform === "ebay" && (packet.source_mode === "official_api" || packet.packet?.source_label === "official_api"),
  );
  if (official) return official;
  const stored = storedPackets.find((packet) => !packet.platform || packet.platform === "ebay") || storedPackets[0];
  if (stored) return stored;
  return latestSync.data_packet && latestSync.data_packet.packet_id ? latestSync.data_packet : null;
}

