function safeEbayOAuthAuthorizationUrl(value = "") {
  if (!value) return "";
  try {
    const url = new URL(value);
    const allowedHosts = new Set(["auth.ebay.com", "auth.sandbox.ebay.com"]);
    if (
      url.protocol !== "https:" ||
      !allowedHosts.has(url.hostname) ||
      url.port ||
      url.username ||
      url.password ||
      url.pathname !== "/oauth2/authorize"
    ) {
      return "";
    }
    return url.toString();
  } catch (error) {
    return "";
  }
}

