function renderSaasCeoModuleHandoffPanel(view = "product", ctx = saasMerchantWorkbenchContext(), command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  const copy = saasCeoModuleHandoffCopy(view);
  if (!current) {
    return `
      <section class="saas-ceo-module-handoff is-empty" aria-label="AI CEO 指令来源">
        <div>
          <span>AI CEO 指令来源</span>
          <strong>${escapeHtml(copy.label)} 等待 AI CEO 分发任务</strong>
          <p>回到 AI CEO 输入商品、链接、图片、订单问题或经营目标后，这里会显示目标、店铺资料来源和下一步。</p>
        </div>
        <button class="secondary-action compact-action" type="button" data-global-flow-view="cockpit" data-global-flow-key="goal">回到 AI CEO</button>
      </section>
    `;
  }
  const route = current.routes.find((item) => item.view === view) || current.routes[0] || {};
  const storeDataLabel = current.source_label || ctx.sourceLabel || (ctx.hasPacket ? "店铺资料已读取" : "等待店铺资料");
  const routeLabels = current.routes.map((item) => item.label).join("、");
  return `
    <section class="saas-ceo-module-handoff" aria-label="AI CEO 指令来源">
      <div>
        <span>AI CEO 指令来源</span>
        <strong>${escapeHtml(copy.label)} 已接到：${escapeHtml(current.title)}</strong>
        <p>${escapeHtml(current.text)}</p>
      </div>
      <div class="saas-ceo-module-meta">
        <article>
          <span>店铺资料</span>
          <strong>${escapeHtml(storeDataLabel)}</strong>
          <small>${escapeHtml(ctx.hasPacket ? "来源可追溯" : "连接 eBay 或补充商品资料后继续")}</small>
        </article>
        <article>
          <span>本模块下一步</span>
          <strong>${escapeHtml(route.status || current.status_label)}</strong>
          <small>${escapeHtml(route.note || copy.next)}</small>
        </article>
        <article>
          <span>分发路径</span>
          <strong>${escapeHtml(routeLabels)}</strong>
          <small>${escapeHtml(current.high_risk ? "高风险动作已标记，必须进入决策中心。" : "真实写入仍保留确认边界。")}</small>
        </article>
      </div>
    </section>
  `;
}

function saasCeoModuleGoalView(command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  if (!current || current.intent === "general_chat") return "";
  const route = primarySaasCeoRoute(current);
  if (current.high_risk || current.intent === "confirm" || route?.view === "confirm") return "confirm";
  return route?.view || "";
}

function shouldShowSaasCeoModuleGoalStrip(view = "product", command = state.saasLastCeoCommand) {
  const targetView = saasCeoModuleGoalView(command);
  if (!targetView) return false;
  return targetView === view;
}

function saasCeoModuleGoalCopy(view = "product", command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  const base = {
    bulk: {
      title: "小批量实验目标已带入",
      next: "先选数量、货源和边界，再把能试的候选送到 Listing 和素材。",
      boundary: "不自动发布、不采购付款；需要你确认的动作会停到决策中心。",
    },
    media: {
      title: "素材目标已带入",
      next: "先整理商品草稿和来源图，再生成主图、详情页、场景图和视频脚本。",
      boundary: "素材只回写草稿；真实发布、承诺和平台写入仍要确认。",
    },
    service: {
      title: "客服订单目标已带入",
      next: "先看消息、订单和回复边界，再起草可用回复。",
      boundary: "退款、补偿、重发、地址修改和明确承诺会停到决策中心。",
    },
    confirm: {
      title: "高风险动作已拦住",
      next: "这里只处理需要你点头的动作；未确认前不执行。",
      boundary: "发布、付款、退款、广告、改价、库存和敏感客服承诺必须由你确认。",
    },
  }[view] || {
    title: "AI CEO 目标已带入",
    next: "继续处理当前模块的下一步。",
    boundary: "真实动作仍按确认中心边界执行。",
  };
  return {
    ...base,
    goal: saasCeoTaskGoalLabel(current),
    commandText: publicRuntimeText(current?.text || "").slice(0, 180),
  };
}

function renderSaasModuleAiGoalStrip(view = "product", command = state.saasLastCeoCommand) {
  if (!shouldShowSaasCeoModuleGoalStrip(view, command)) return "";
  const copy = saasCeoModuleGoalCopy(view, command);
  return `
    <section class="saas-module-ai-goal-strip" data-ai-ceo-module-goal-strip="ai_ceo_module_goal_v1" data-ai-ceo-module-view="${escapeHtml(view)}" aria-label="AI CEO 已带入目标">
      <div class="saas-module-ai-goal-main">
        <span>来自 AI CEO</span>
        <strong>${escapeHtml(copy.title)}</strong>
        <p>${escapeHtml(copy.commandText || copy.goal)}</p>
      </div>
      <div class="saas-module-ai-goal-steps" aria-label="目标、下一步和边界">
        <article>
          <span>目标</span>
          <strong>${escapeHtml(copy.goal)}</strong>
        </article>
        <article>
          <span>下一步</span>
          <strong>${escapeHtml(copy.next)}</strong>
        </article>
        <article>
          <span>边界</span>
          <strong>${escapeHtml(copy.boundary)}</strong>
        </article>
      </div>
      <button class="secondary-action compact-action" type="button" data-global-flow-view="cockpit" data-global-flow-key="goal">回 AI CEO 修改目标</button>
    </section>
  `;
}

function renderSaasModuleAiGoalStripIntoView(view = "product", options = {}) {
  const shell = document.querySelector(`#view-${view}`);
  if (!shell) return null;
  shell.querySelectorAll(".saas-module-ai-goal-strip").forEach((node) => node.remove());
  const html = renderSaasModuleAiGoalStrip(view);
  if (!html) return null;
  const anchor = options.anchorSelector ? shell.querySelector(options.anchorSelector) : shell.firstElementChild;
  if (anchor) {
    anchor.insertAdjacentHTML(options.position === "after" ? "afterend" : "beforebegin", html);
  } else {
    shell.insertAdjacentHTML("afterbegin", html);
  }
  return shell.querySelector(".saas-module-ai-goal-strip");
}

function shouldShowSaasAiCeoWorkDetail(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || latest.pending) return false;
  if (isSaasAiCeoPlainConsultationTurn(latest)) return false;
  const route = String(latest.route || "");
  const status = String(latest.status || "");
  const sourceCount = normalizeSaasAiCeoSourceRecords(latest.source_records || []).length;
  const workCount = normalizeSaasAiCeoWorkRecords(latest.work_records || []).length;
  const confirmationCount = normalizeSaasAiCeoConfirmationItems(latest.confirmation_items || []).length;
  return Boolean(
    sourceCount ||
      workCount ||
      confirmationCount ||
      latest.decision_center_required ||
      latest.long_term_memory ||
      latest.writes_merchant_rule ||
      ["ebay_workflow", "external_realtime", "confirmation_required", "merchant_rule_memory"].includes(route) ||
      ["realtime_search_answered", "realtime_search_answered_without_model", "external_data_source_required"].includes(status),
  );
}

function isSaasAiCeoPlainConsultationTurn(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || latest.pending) return false;
  const route = String(latest.route || "general_chat");
  const status = String(latest.status || "");
  const realtimeStatuses = ["realtime_search_answered", "realtime_search_answered_without_model", "external_data_source_required"];
  return Boolean(
    route === "general_chat" &&
      !realtimeStatuses.includes(status) &&
      !latest.decision_center_required &&
      !latest.long_term_memory &&
      !latest.writes_merchant_rule,
  );
}

function renderSaasAiCeoWorkDetailMarkup(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || !shouldShowSaasAiCeoWorkDetail(latest)) return "";
  const sourceCount = normalizeSaasAiCeoSourceRecords(latest.source_records || []).length;
  const summary = latest.decision_center_required
    ? "查看确认边界"
    : sourceCount
      ? "查看来源"
      : "查看处理详情";
  return `
    <details class="saas-ai-ceo-work-detail">
      <summary>${escapeHtml(summary)}</summary>
      <div class="saas-ai-ceo-work-detail-body">
        ${renderSaasAiCeoOperatingRowsMarkup(latest)}
        ${renderSaasAiCeoSourceRecordsMarkup(latest.source_records)}
        ${renderSaasAiCeoWorkRecordsMarkup(latest.work_records)}
        ${renderSaasAiCeoConfirmationItemsMarkup(latest.confirmation_items)}
      </div>
    </details>
  `;
}

function shouldShowSaasAiCeoRecoveryHint(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || latest.pending) return false;
  const status = String(latest.status || "");
  return ["blocked_before_model_chat", "blocked_missing_model_config", "model_call_failed", "external_data_source_required"].includes(status);
}

function renderSaasAiCeoRecoveryHintMarkup(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || !shouldShowSaasAiCeoRecoveryHint(latest)) return "";
  const text = String(latest.assistant_text || "");
  const blockers = Array.from(new Set(latest.blocked_by || []));
  const hasCurrentStoreMissing = blockers.includes("merchant_model_api_key_not_saved") || blockers.includes("current_store_model_connection_missing");
  const hasPlatformDefaultMissing = blockers.some((item) => String(item || "").startsWith("platform_model_"));
  const isUsageBlock = /用量|额度|余额|账单|套餐|计费/.test(text);
  const isAccountBlock = /登录|会话|店铺上下文|店铺状态|没有可用店铺|受保护/.test(text);
  const isRealtimeBlock = latest.status === "external_data_source_required" || /实时|联网|搜索|来源|行情|新闻|provider/i.test(text);
  const hasCurrentAccountMissing = blockers.includes("current_account_model_connection_missing");
  const isModelSetupBlock = hasCurrentStoreMissing || hasCurrentAccountMissing || hasPlatformDefaultMissing;
  const label = isUsageBlock ? "用量提示" : isAccountBlock ? "店铺状态" : isRealtimeBlock ? "实时数据源" : "AI 连接";
  const title = isUsageBlock
    ? "AI 已收到，但模型额度需要先恢复"
    : isAccountBlock
      ? "AI 已收到，但需要先恢复店铺状态"
      : isRealtimeBlock
        ? "AI 已接通，但实时数据源需要先恢复"
        : isModelSetupBlock
          ? "当前账号还没有可用的 AI 连接"
          : "AI 已收到，但 AI 连接需要先恢复";
  const detail = isUsageBlock
    ? "先去设置看 AI 与素材的连接和用量；不用在这里重复粘贴密钥。"
    : isAccountBlock
      ? "先刷新登录和店铺资料；如果仍没有店铺，就到设置连接 eBay 或导入资料。"
      : isRealtimeBlock
        ? "普通咨询和 eBay 工作流可以继续；需要最新网页、新闻或行情时，系统会先拿到后端来源再回答。"
        : hasPlatformDefaultMissing
          ? "可以到「设置 -> AI 与素材」查看当前账号连接；如果使用捷境默认 AI，请等待平台连接恢复，或先接通当前账号自己的 AI。"
          : hasCurrentStoreMissing || hasCurrentAccountMissing
            ? "可以到「设置 -> AI 与素材」查看当前账号连接；保存后会跟随这个捷境账号用于账号下店铺。"
            : "先去设置查看 AI 连接；凭证仍只在后端安全边界处理。";
  const primaryKey = isAccountBlock ? "account" : "model";
  const primaryLabel = isAccountBlock ? "去账号与店铺" : "去 AI 与素材";
  return `
    <div class="saas-ai-ceo-recovery-hint" data-ai-ceo-recovery-hint="merchant_safe_ai_recovery_v1">
      <span>${escapeHtml(label)}</span>
      <div>
        <strong>${escapeHtml(title)}</strong>
        <small>${escapeHtml(detail)}</small>
      </div>
      <div class="saas-ai-ceo-recovery-actions">
        <button class="secondary-action compact-action" type="button" data-saas-action="refresh">刷新状态</button>
        <button class="primary-action compact-action" type="button" data-global-flow-view="connect" data-global-flow-key="${escapeHtml(primaryKey)}">${escapeHtml(primaryLabel)}</button>
      </div>
    </div>
  `;
}

const saasAiCeoMarketImportTargets = new Map();

function rememberSaasAiCeoMarketImportTarget(turn = {}, renderedProduct = "") {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest) return null;
  const target = {
    ...latest,
    rendered_product: saasIsConcreteProductLabel(renderedProduct) ? publicRuntimeText(renderedProduct) : "",
  };
  if (target.assistant_id) saasAiCeoMarketImportTargets.set(`assistant:${target.assistant_id}`, target);
  if (target.market_report_id) saasAiCeoMarketImportTargets.set(`report:${target.market_report_id}`, target);
  while (saasAiCeoMarketImportTargets.size > 80) {
    saasAiCeoMarketImportTargets.delete(saasAiCeoMarketImportTargets.keys().next().value);
  }
  return target;
}

function renderSaasAiCeoListingHandoffMarkup(turn = {}) {
  const eligibility = saasAiCeoMarketResearchEligibility(turn);
  if (!eligibility.eligible) return "";
  const latest = eligibility.latest;
  const product = saasAiCeoMarketProductLabel(latest) || "这次调研";
  const sourceCount = normalizeSaasAiCeoSourceRecords(latest.source_records || []).length;
  rememberSaasAiCeoMarketImportTarget(latest, product);
  return `
    <div class="saas-ai-ceo-listing-handoff" data-ai-ceo-market-handoff="ai_ceo_market_to_listing_cta_v1">
      <div>
        <span>可以继续做 Listing</span>
        <strong>${escapeHtml(product)}</strong>
        <small>${sourceCount ? `已带 ${sourceCount} 条公开来源；` : ""}导入后只生成本地草稿，真实发布仍要经过确认中心。</small>
      </div>
      <button class="primary-action compact-action" type="button" data-saas-action="ai-ceo-import-market-to-listing" data-ai-ceo-assistant-id="${escapeHtml(latest.assistant_id || "")}" data-product-name="${escapeHtml(product)}">导入 Listing 草稿</button>
    </div>
  `;
}

function renderSaasAiCeoMarketReportDeliveryMarkup(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  const delivery = latest?.market_report_delivery;
  if (!delivery?.structured_report_saved || delivery.report_type !== "ai_ceo.market_research") return "";
  const answerProduct = saasAiCeoMarketProductLabel(latest);
  const title =
    (saasIsConcreteProductLabel(delivery.product) ? delivery.product : "") ||
    answerProduct ||
    delivery.title ||
    "这次市场调研";
  const sourceCopy = delivery.source_record_count ? `已带 ${delivery.source_record_count} 条公开来源；` : "";
  const authoritativeReport = saasAuthoritativeAiCeoMarketReportForTurn(latest);
  const blockedDraftAvailable =
    delivery.listing_import_ready !== true &&
    Boolean(authoritativeReport && saasAiCeoMarketReportCanStartBlockedListingDraft(authoritativeReport));
  if (delivery.listing_import_ready !== true && !blockedDraftAvailable) {
    return `
      <div class="saas-ai-ceo-market-report-delivery" data-ai-ceo-market-report-delivery="ai_ceo_market_report_delivery_v1" data-report-id="${escapeHtml(delivery.report_id)}">
        <div>
          <span>市场调研已保存</span>
          <strong>${escapeHtml(title)}</strong>
          <small>${sourceCopy}这份调研还不能导入 Listing。请先补齐候选商品和商家核对项。</small>
        </div>
      </div>
    `;
  }
  if (!authoritativeReport) {
    return `
      <div class="saas-ai-ceo-market-report-delivery" data-ai-ceo-market-report-delivery="ai_ceo_market_report_delivery_v1" data-report-id="${escapeHtml(delivery.report_id)}">
        <div>
          <span>市场调研已保存</span>
          <strong>${escapeHtml(title)}</strong>
          <small>${sourceCopy}正在恢复已保存的调研结果，恢复完成前不能导入 Listing。</small>
        </div>
      </div>
    `;
  }
  rememberSaasAiCeoMarketImportTarget(latest, title);
  return `
    <div class="saas-ai-ceo-market-report-delivery" data-ai-ceo-market-report-delivery="ai_ceo_market_report_delivery_v1" data-report-id="${escapeHtml(delivery.report_id)}">
      <div>
        <span>市场调研已保存</span>
        <strong>${escapeHtml(title)}</strong>
        <small>${sourceCopy}${blockedDraftAvailable ? "可以导入为待补资料草稿；缺失事实继续阻断发布。" : "可以导入 Listing 草稿。"}真实发布、改价、库存、广告、退款、付款和政策修改仍要经过确认中心。</small>
      </div>
      <button class="primary-action compact-action" type="button" data-saas-action="ai-ceo-import-market-to-listing" data-report-id="${escapeHtml(delivery.report_id)}" data-ai-ceo-assistant-id="${escapeHtml(latest.assistant_id || "")}" data-product-name="${escapeHtml(title)}">导入 Listing 草稿</button>
    </div>
  `;
}

function saasAiCeoTurnRouteLabel(turn = {}) {
  const latest = turn && typeof turn === "object" ? turn : {};
  const directLabel = publicRuntimeText(latest.route_label || latest.intent_label || "");
  if (directLabel) return directLabel;
  const route = String(latest.route || latest.intent || "").toLowerCase();
  return (
    {
      product: "Listing",
      listing: "Listing",
      ebay_workflow: "eBay 工作流",
      bulk: "小批量选品",
      media: "素材工坊",
      service: "客服与订单",
      confirm: "决策中心",
      confirmation_required: "决策中心",
      external_realtime: "实时搜索",
      general_chat: "直接回答",
    }[route] || "AI CEO"
  );
}

function saasAiCeoPendingPreview(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || !latest.pending) return null;
  const route = String(latest.route || "general_chat");
  const routeLabel = latest.route_label || saasAiCeoTurnRouteLabel(latest);
  const userText = String(latest.user_text || "").trim();
  const templates = {
    product: {
      title: "先给你一个临时方向",
      summary: "我会先按 eBay Listing 项目处理：查市场和竞品信号，再整理标题、卖点、缺资料、价格风险和可导入草稿。",
      bullets: ["可以继续补成本、尺寸、图片或链接", "完整报告回来后可导入 Listing", "真实发布仍停在确认中心"],
    },
    listing: {
      title: "先给你一个临时方向",
      summary: "我会先按 eBay Listing 项目处理：查市场和竞品信号，再整理标题、卖点、缺资料、价格风险和可导入草稿。",
      bullets: ["可以继续补成本、尺寸、图片或链接", "完整报告回来后可导入 Listing", "真实发布仍停在确认中心"],
    },
    bulk: {
      title: "先按小批量选品处理",
      summary: "我会先整理候选品类、价格带、风险点和筛选理由；完整结果回来前，不会自动生成铺货或发布动作。",
      bullets: ["可补目标类目或预算", "先出候选清单", "通过后再进 Listing"],
    },
    media: {
      title: "先按素材任务处理",
      summary: "我会先把素材目标拆成主图、场景图、详情图或视频脚本；生成结果回来后还要逐项审核，不能直接用于刊登。",
      bullets: ["可补参考图或风格", "先出素材 brief", "通过审核再回写 Listing"],
    },
    service: {
      title: "先按客服与订单处理",
      summary: "我会先区分普通回复、物流事实、退款补偿和敏感承诺；涉及钱、地址、重发和明确承诺的内容会进决策中心。",
      bullets: ["可补订单号或消息原文", "先起草回复", "敏感承诺必须确认"],
    },
    confirm: {
      title: "先停在确认边界",
      summary: "这类请求可能涉及真实发布、付款、退款、广告、库存、政策或买家承诺；我只会整理确认项，不会替你点头执行。",
      bullets: ["先列风险和缺口", "需要你确认", "未确认不执行"],
    },
    general_chat: {
      title: "先给你一个短答方向",
      summary: "我会先查公开来源再组织回答；如果问题不需要最新资料，就直接给结论。普通聊天不会写入长期经营记忆。",
      bullets: ["可继续补充背景", "需要实时资料会先查来源", "不触发 eBay 写入"],
    },
  };
  const previewRoute = {
    ebay_workflow: "product",
    confirmation_required: "confirm",
    external_realtime: "general_chat",
    merchant_rule_memory: "general_chat",
  }[route] || route;
  const preview = templates[previewRoute] || templates.general_chat;
  return {
    ...preview,
    routeLabel,
    userText,
  };
}

function renderSaasAiCeoPendingPreviewMarkup(turn = {}) {
  const preview = saasAiCeoPendingPreview(turn);
  if (!preview) return "";
  return `
    <div class="saas-ai-ceo-pending-preview" data-ai-ceo-provisional-answer="quick_then_full_report_v1">
      <div class="saas-ai-ceo-pending-preview-head">
        <span>先短答</span>
        <strong>${escapeHtml(preview.title)}</strong>
        <small>${escapeHtml(preview.routeLabel || "AI CEO")}</small>
      </div>
      <p>${escapeHtml(preview.summary)}</p>
      <ul aria-label="这次可以先做什么">
        ${(preview.bullets || []).map((item) => `<li>${escapeHtml(item)}</li>`).join("")}
      </ul>
    </div>
  `;
}

function renderSaasAiCeoPendingStatusMarkup(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  if (!latest || !latest.pending) return "";
  const delayed = latest.status === "model_response_delayed";
  const stage = String(latest.pending_stage || "received");
  const title = delayed ? "正在继续整理完整回答" : stage === "sources" ? "正在搜索公开资料" : "正在思考";
  return `
    <div class="saas-ai-ceo-pending-status is-compact" role="status" aria-live="polite" aria-label="${escapeHtml(title)}" data-ai-ceo-pending-status="single_black_thinking_dot_v1" data-merchant-pending-contract="merchant_clear_pending_v4" data-pending-stage="${escapeHtml(stage)}">
      <span class="saas-ai-ceo-thinking-dot" aria-hidden="true"></span>
    </div>
  `;
}

function saasAiCeoPendingStageRows(turn = {}) {
  const latest = normalizeSaasAiCeoLatestTurn(turn);
  const stage = String(latest?.pending_stage || (latest?.status === "model_response_delayed" ? "handoff" : "received"));
  const route = String(latest?.route || "");
  const isWorkflow = route && route !== "general_chat";
  const rows = [
    { key: "received", label: "已接住", title: "已接住你的目标，正在判断问题类型", detail: "保留你的原始目标" },
    { key: "sources", label: "查来源", title: "正在查公开来源和当前店铺资料", detail: "先看证据再回答" },
    { key: "model", label: "AI 整理", title: "来源已接住，AI 正在整理成可用答复", detail: "生成商家能直接看的结论" },
    {
      key: "handoff",
      label: isWorkflow ? "准备草稿" : "准备回答",
      title: isWorkflow ? "正在生成下一步建议和可导入草稿" : "正在生成完整回答",
      detail: isWorkflow ? "只进草稿和确认中心" : "普通对话不写长期经营记忆",
    },
  ];
  const activeIndex = Math.max(0, rows.findIndex((item) => item.key === stage));
  return rows.map((item, index) => ({
    ...item,
    active: index === activeIndex,
    done: index < activeIndex,
  }));
}

function scheduleSaasAiCeoPendingWatchdog(messageId, command = state.saasLastCeoCommand) {
  if (!messageId || typeof window === "undefined") return;
  [
    {
      delay: 1200,
      stage: "sources",
      status: "searching_public_sources",
      text: "我已经接住这次目标，正在查公开来源和当前店铺资料；如果是长报告，会先保留目标再继续整理。",
    },
    {
      delay: 5200,
      stage: "model",
      status: "model_synthesis_pending",
      text: "来源和目标已经接住，AI 正在整理成商家能直接看的回答；真实发布、付款、退款、广告、授权和敏感客服承诺不会自动执行。",
    },
    {
      delay: 12000,
      stage: "handoff",
      status: "model_response_delayed",
      text: "这次内容较长，我还在查来源和整理答案。你可以继续补充资料；如果生成了市场调研，完成后可以直接导入 Listing 草稿。",
    },
  ].forEach((step) => {
    window.setTimeout(() => {
      const node = document.getElementById(messageId);
      if (!node || !node.classList.contains("is-pending")) return;
      const latest = normalizeSaasAiCeoLatestTurn({
        ...(state.saasAiCeoLatestTurn || {}),
        assistant_id: messageId,
        assistant_text: step.text,
        status: step.status,
        route: command?.route || state.saasAiCeoLatestTurn?.route || "",
        route_label: command?.route_label || state.saasAiCeoLatestTurn?.route_label || "",
        memory_policy: command?.memory_policy || state.saasAiCeoLatestTurn?.memory_policy || "transient_no_long_term_memory",
        pending_stage: step.stage,
        pending: true,
      });
      updateCeoAssistantPendingMessage(messageId, latest);
    }, step.delay);
  });
}

function sanitizeSaasCeoCommandSourceText(text = "") {
  return publicRuntimeText(text || "")
    .replace(/\bsk-[A-Za-z0-9_-]{12,}\b/g, "[model_key_redacted]")
    .replace(/\b(AIAK|AKID|ASIA)[A-Za-z0-9]{12,}\b/g, "[cloud_key_redacted]")
    .replace(/\b(access[_-]?token|refresh[_-]?token|api[_-]?key|password|secret)\s*[:=]\s*[^,\s;，；]+/gi, "$1=[redacted]")
    .slice(0, 900);
}

function saasAiCeoConversationHistoryForRequest() {
  const currentProjectId = saasCurrentMerchantProjectId();
  return (Array.isArray(state.saasAiCeoThread) ? state.saasAiCeoThread : [])
    .map(normalizeSaasAiCeoLatestTurn)
    .filter((turn) => turn && !turn.pending && turn.user_text && turn.assistant_text)
    .filter((turn) => {
      if (!currentProjectId) return true;
      const identity = saasNormalizeListingProjectIdentity(turn.listing_project_identity);
      return identity?.key === currentProjectId;
    })
    .slice(-8)
    .map((turn) => ({
      user_text: sanitizeSaasCeoCommandSourceText(turn.user_text).slice(0, 900),
      assistant_text: publicRuntimeText(turn.assistant_text).slice(0, 3200),
      route: ["general_chat", "ebay_workflow", "external_realtime", "confirmation_required", "merchant_rule_memory"].includes(turn.route)
        ? turn.route
        : "general_chat",
    }));
}

function recordSaasCeoCommandSourceRecord(command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  if (!current) return false;
  if (!shouldRecordSaasCeoCommandSourceRecord(current)) return false;
  const safeText = sanitizeSaasCeoCommandSourceText(current.text);
  const record = normalizeSaasSourceRecord(
    {
      id: `ceo-command-source-${current.id}`,
      title: `AI CEO 指令：${current.title}`,
      note: `${safeText}；分发路径：${current.routes.map((route) => route.label).join("、") || "等待分发"}。`,
      source_type: "merchant_ceo_command",
      captured_at: current.created_at || new Date().toISOString(),
      status: "merchant_command_recorded",
    },
    "merchant_ceo_command",
    0,
  );
  if (!record) return false;
  const existing = Array.isArray(state.saasSourceRecords) ? state.saasSourceRecords : loadSaasSourceRecords();
  state.saasSourceRecords = [record, ...existing.filter((item) => item.id !== record.id)].slice(0, 60);
  persistSaasSourceRecords();
  return true;
}

function shouldRecordSaasCeoCommandSourceRecord(command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  if (!current) return false;
  const route = String(current.route || "general_chat");
  const hasBusinessRoute = (current.routes || []).some((item) => item && item.view && item.view !== "connect");
  return Boolean(
    route !== "general_chat" ||
      hasBusinessRoute ||
      current.decision_center_required ||
      current.long_term_memory ||
      current.writes_merchant_rule,
  );
}

function newestSaasCeoCommand(...commands) {
  return (
    commands
      .map(normalizeSaasCeoCommand)
      .filter(Boolean)
      .sort((left, right) => String(right.created_at || "").localeCompare(String(left.created_at || "")))[0] || null
  );
}

function backendSaasCeoCommandFromPayload(payload = {}) {
  if (!payload || typeof payload !== "object") return null;
  const direct = payload.command && typeof payload.command === "object" ? payload.command : null;
  const wrapped = payload.merchant_ceo_command && typeof payload.merchant_ceo_command === "object" ? payload.merchant_ceo_command : null;
  return normalizeSaasCeoCommand(direct || wrapped?.command || null);
}

function applyBackendSaasCeoCommand(payload = {}) {
  const backendCommand = backendSaasCeoCommandFromPayload(payload);
  if (!backendCommand) return null;
  state.saasLastCeoCommand = newestSaasCeoCommand(backendCommand, state.saasLastCeoCommand);
  persistSaasLastCeoCommand(state.saasLastCeoCommand);
  recordSaasCeoCommandSourceRecord(state.saasLastCeoCommand);
  return state.saasLastCeoCommand;
}

async function persistSaasCeoCommandToBackend(command = state.saasLastCeoCommand) {
  const current = normalizeSaasCeoCommand(command);
  if (!current || !current.store_id || !hasSaasProtectedSessionCandidate()) return null;
  try {
    const payload = await saasFetch(`/stores/${encodeURIComponent(current.store_id)}/merchant-ceo/commands`, {
      method: "POST",
      keepalive: true,
      body: JSON.stringify({
        command: {
          ...current,
          text: sanitizeSaasCeoCommandSourceText(current.text),
          summary: sanitizeSaasCeoCommandSourceText(current.summary),
          title: sanitizeSaasCeoCommandSourceText(current.title),
        },
        real_platform_writes_enabled: isSaasRealPlatformWritesEnabled(),
      }),
    });
    return applyBackendSaasCeoCommand(payload);
  } catch (error) {
    console.warn(`[JIEJING optional API skipped] merchant-ceo command persistence: ${error.message}`);
    return null;
  }
}

function saasAiCeoPendingSourceAssetIds(attachments = state.saasAiCeoPendingAttachments) {
  return (Array.isArray(attachments) ? attachments : [])
    .map((item) => String(item?.asset_id || "").trim())
    .filter(Boolean)
    .slice(0, 8);
}

function saasAiCeoActiveListingContext() {
  const normalizeIdentity = (value = null) => {
    if (typeof saasNormalizeListingProjectIdentity === "function") {
      return saasNormalizeListingProjectIdentity(value);
    }
    const raw = value && typeof value === "object" ? value : {};
    const key = String(raw.key || "").trim().slice(0, 160);
    if (!/^[A-Za-z0-9._:-]+$/.test(key)) return null;
    return {
      key,
      source_report_id: String(raw.source_report_id || raw.source_id || "").trim().slice(0, 160),
      candidate_id: String(raw.candidate_id || "").trim().slice(0, 120),
    };
  };
  const identityFromReport = (record = null) => {
    if (typeof saasListingProjectIdentityFromReport === "function") {
      return saasListingProjectIdentityFromReport(record || {});
    }
    const body = record?.report && typeof record.report === "object" ? record.report : {};
    return normalizeIdentity(record?.listing_project_identity) || normalizeIdentity(body.listing_project_identity);
  };
  const routeProjectId = typeof saasMerchantProjectRouteId === "function" ? saasMerchantProjectRouteId() : "";
  const activeStoreId = String(
    typeof activeSaasStore === "function" ? activeSaasStore()?.store_id || "" : "",
  ).trim();
  const currentDraft = state.saasListingComposerDraft && typeof state.saasListingComposerDraft === "object"
    ? state.saasListingComposerDraft
    : null;
  const structuredDraftIdentity = normalizeIdentity(currentDraft?.listing_project_identity);
  const legacyDraftProjectId = String(currentDraft?.listing_project_key || "").trim();
  const currentDraftIdentity = structuredDraftIdentity || (
    /^[A-Za-z0-9._:-]{1,160}$/.test(legacyDraftProjectId)
      ? {
          key: legacyDraftProjectId,
          source_report_id: String(currentDraft?.source_report_id || "").trim().slice(0, 160),
          candidate_id: String(currentDraft?.selected_product_candidate?.candidate_id || "").trim().slice(0, 120),
        }
      : null
  );
  let draft = currentDraft && (!routeProjectId || currentDraftIdentity?.key === routeProjectId)
    ? currentDraft
    : null;
  let identity = draft ? currentDraftIdentity : null;
  const matchingReports = (Array.isArray(state.saasReports) ? state.saasReports : [])
    .filter((record) => {
      const reportStoreId = String(record?.store_id || record?.report?.store_id || "").trim();
      if (activeStoreId && reportStoreId !== activeStoreId) return false;
      const reportIdentity = identityFromReport(record);
      const targetProjectId = routeProjectId || identity?.key || "";
      return Boolean(reportIdentity?.key && (!targetProjectId || reportIdentity.key === targetProjectId));
    })
    .sort((a, b) => saasTimestampMillis(b.updated_at || b.created_at) - saasTimestampMillis(a.updated_at || a.created_at));
  const matchingReport = matchingReports[0] || null;
  const reportIdentity = identityFromReport(matchingReport);
  if (!identity?.key && reportIdentity?.key) identity = reportIdentity;
  if (!draft && matchingReport) {
    const reportBody = matchingReport.report && typeof matchingReport.report === "object" ? matchingReport.report : {};
    draft = saasListingDraftFromReport(matchingReport, "active_listing_context") || {
      listing_project_identity: reportIdentity,
      product: reportBody.product || reportBody.product_name || "",
      title: reportBody.title || "",
      merchant_product_fact_packet: reportBody.merchant_product_fact_packet || {},
    };
  }
  const projectSnapshot = state.saasMerchantProjectStatus?.project && typeof state.saasMerchantProjectStatus.project === "object"
    ? state.saasMerchantProjectStatus.project
    : {};
  const snapshotProjectId = String(projectSnapshot.project_id || "").trim();
  const snapshotIdentity = normalizeIdentity(projectSnapshot.listing_project_identity);
  if (
    !identity?.key &&
    snapshotIdentity?.key &&
    (!routeProjectId || (snapshotProjectId === routeProjectId && snapshotIdentity.key === routeProjectId))
  ) {
    identity = snapshotIdentity;
  }
  if (!identity?.key || (routeProjectId && identity.key !== routeProjectId)) return null;
  draft = draft || { listing_project_identity: identity };
  const packet = draft.merchant_product_fact_packet && typeof draft.merchant_product_fact_packet === "object"
    ? draft.merchant_product_fact_packet
    : {};
  const sourceFacts = packet.source_confirmed_facts && typeof packet.source_confirmed_facts === "object" ? packet.source_confirmed_facts : {};
  const merchantFacts = packet.merchant_confirmed_facts && typeof packet.merchant_confirmed_facts === "object" ? packet.merchant_confirmed_facts : {};
  const derivedFacts = packet.derived_listing_suggestions && typeof packet.derived_listing_suggestions === "object" ? packet.derived_listing_suggestions : {};
  const factAllowlist = [
    "product_name", "sku", "supplier_item_number", "material", "brand", "mpn", "condition",
    "net_weight_g", "package_weight_g", "package_length_cm", "package_width_cm", "package_height_cm",
    "length_cm", "width_cm", "height_cm", "unit_cost", "selling_price", "quantity",
    "handling_time_days", "country_of_origin", "item_location", "packaging",
  ];
  const knownFacts = {};
  factAllowlist.forEach((key) => {
    const value = merchantFacts[key] ?? sourceFacts[key] ?? derivedFacts[key];
    if (typeof value === "boolean") {
      knownFacts[key] = value;
      return;
    }
    const text = publicRuntimeText(value).trim().slice(0, 240);
    if (text) knownFacts[key] = text;
  });
  const missingFactKeys = [...new Set((Array.isArray(packet.unknown_facts) ? packet.unknown_facts : [])
    .map((key) => String(key || "").trim())
    .filter((key) => factAllowlist.includes(key)))]
    .slice(0, 24);
  missingFactKeys.forEach((key) => delete knownFacts[key]);
  const mediaJob = latestSaasMediaAssetJobWithManifest({ requireCurrentProject: true, draft });
  const manifestCards = saasMediaManifestAssetCards(mediaJob);
  const listingAssets = saasMediaManifestAssetsForListing(mediaJob).filter((asset) =>
    ["approved_for_listing_draft", "merchant_review_confirmed"].includes(String(asset?.listing_use_status || asset?.review_status || "")),
  );
  const mediaWriteback = saasListingMediaWritebackForDraft(draft);
  const writebackAssetCount = Math.max(
    0,
    Number(mediaWriteback?.asset_count || 0) || 0,
    Array.isArray(mediaWriteback?.assets) ? mediaWriteback.assets.length : 0,
    Array.isArray(mediaWriteback?.asset_urls) ? mediaWriteback.asset_urls.length : 0,
    Array.isArray(mediaWriteback?.image_urls) ? mediaWriteback.image_urls.length : 0,
  );
  const writebackListingReady = Boolean(mediaWriteback) && saasListingMediaWritebackRightsReady(draft);
  const writebackEligibleAssetCount = writebackListingReady ? writebackAssetCount : 0;
  const listingEligibleAssetCount = Math.max(listingAssets.length, writebackEligibleAssetCount);
  const rightsConfirmedForListingDraft = listingEligibleAssetCount > 0 && (
    writebackListingReady ||
    listingAssets.some((asset) =>
      ["approved_for_listing_draft", "merchant_review_confirmed"].includes(
        String(asset?.listing_use_status || asset?.review_status || ""),
      ),
    )
  );
  const mediaReviewStatuses = [
    ...manifestCards.map((card) => card?.reviewStatus || ""),
    mediaWriteback?.status || "",
    mediaWriteback?.review_status || "",
    mediaWriteback?.rights_status || "",
    mediaWriteback?.listing_use_status || "",
  ];
  const receipt = saasCurrentUnpublishedDraftReceipt(draft);
  const health = state.saasAccountHealth && typeof state.saasAccountHealth === "object" ? state.saasAccountHealth : {};
  return {
    contract_version: "active_listing_context_v1",
    source: "authenticated_current_project_snapshot",
    listing_project_identity: {
      key: String(identity.key || "").slice(0, 160),
      source_report_id: String(identity.source_report_id || identity.source_id || "").slice(0, 160),
      candidate_id: String(identity.candidate_id || "").slice(0, 120),
    },
    product_name: publicRuntimeText(identity.product || draft.product || draft.title || draft.fields?.title || "").slice(0, 120),
    listing: {
      sku: saasListingDraftAuthoritativeSku(draft).slice(0, 120),
      title: publicRuntimeText(draft.title || draft.fields?.title || "").slice(0, 180),
      known_facts: knownFacts,
      known_fact_keys: Object.keys(knownFacts),
      missing_fact_keys: missingFactKeys,
    },
    media: {
      media_job_id: String(mediaJob?.media_job_id || mediaWriteback?.media_job_id || "").slice(0, 120),
      asset_manifest_count: Math.max(manifestCards.length, writebackAssetCount),
      listing_eligible_asset_count: listingEligibleAssetCount,
      rights_confirmed_for_listing_draft: rightsConfirmedForListingDraft,
      product_fact_review_required_before_publish: missingFactKeys.length > 0 || listingEligibleAssetCount > 0,
      review_statuses: [...new Set(mediaReviewStatuses.map((status) => publicRuntimeText(status).slice(0, 80)).filter(Boolean))].slice(0, 8),
    },
    ebay_draft: receipt ? {
      offer_id: String(receipt.offerId || "").slice(0, 120),
      sku: String(receipt.sku || "").slice(0, 120),
      offer_status: String(receipt.offerStatus || receipt.status || "UNPUBLISHED").toUpperCase().slice(0, 40),
      execution_id: String(receipt.executionId || "").slice(0, 160),
      confirmation_id: String(receipt.confirmationId || "").slice(0, 160),
      public_listing_created: false,
    } : {},
    account_health: {
      status: publicRuntimeText(health.status || "unknown").toLowerCase().slice(0, 40),
      severity: publicRuntimeText(health.severity || "").toLowerCase().slice(0, 20),
      onboarding_stage: publicRuntimeText(health.onboarding_stage || "").toLowerCase().slice(0, 80),
    },
    secret_exposed: false,
  };
}

function buildSaasAiCeoChatRequestEnvelope(command = state.saasLastCeoCommand, sourceAssetIds = [], options = {}) {
  const current = normalizeSaasCeoCommand(command);
  const safeSourceAssetIds = (Array.isArray(sourceAssetIds) ? sourceAssetIds : [])
    .map((assetId) => String(assetId || "").trim())
    .filter(Boolean)
    .slice(0, 8);
  if (!current?.store_id) return null;
  if (options.frozenRequestPayload) {
    const frozen = sanitizeSaasFrozenNewProjectRequestPayload(options.frozenRequestPayload, { storeId: current.store_id });
    if (!frozen || frozen.command?.id !== current.id) return null;
    return { payload: frozen, activeListingContext: null, safeSourceAssetIds: frozen.source_asset_ids };
  }
  const supplierFactPayload = options.suppressSupplierFacts === true ? {} : supplierFactsForSaasAiCeoCommand(current);
  const activeListingContext = options.suppressActiveListingContext === true
    ? null
    : typeof saasAiCeoActiveListingContext === "function"
      ? saasAiCeoActiveListingContext()
      : null;
  const safeCommand = sanitizeSaasAiCeoRequestCommandSnapshot(current);
  if (!safeCommand) return null;
  const requestedKey = String(options.idempotencyKey || "").trim();
  const idempotencyKey = /^[A-Za-z0-9._:-]{8,160}$/.test(requestedKey)
    ? requestedKey
    : saasAiCeoIdempotencyKey(safeCommand.id, safeCommand.text);
  return {
    payload: {
      idempotency_key: idempotencyKey,
      chat_archive_contract: "server_finalized_chat_archive_v1",
      message: safeCommand.text,
      command: safeCommand,
      conversation_history: options.suppressConversationHistory === true ? [] : saasAiCeoConversationHistoryForRequest(),
      client_now: String(options.clientNow || new Date().toISOString()).slice(0, 40),
      client_timezone: publicRuntimeText(
        options.clientTimezone || Intl?.DateTimeFormat?.().resolvedOptions?.().timeZone || "",
      ).slice(0, 120),
      source_asset_ids: safeSourceAssetIds,
      active_listing_context: activeListingContext,
      real_platform_writes_enabled: isSaasRealPlatformWritesEnabled(),
      ...supplierFactPayload,
    },
    activeListingContext,
    safeSourceAssetIds,
  };
}

async function requestSaasAiCeoChat(command = state.saasLastCeoCommand, hooks = {}, sourceAssetIds = [], options = {}) {
  const current = normalizeSaasCeoCommand(command);
  const envelope = buildSaasAiCeoChatRequestEnvelope(current, sourceAssetIds, options);
  if (!current || !current.store_id) {
    return {
      ai_ceo_chat: {
        status: "blocked_before_model_chat",
        answer: "还没有可用店铺上下文，请先恢复登录和店铺状态。",
      },
    };
  }
  if (!envelope?.payload) {
    return {
      ai_ceo_chat: {
        status: "blocked_before_model_chat",
        answer: "本次请求上下文不完整，捷境已阻止提交；没有调用模型，也没有创建新项目。",
      },
      usage_consumed: false,
      listing_created: false,
      real_platform_writes_enabled: false,
      secret_exposed: false,
    };
  }
  if (!hasSaasProtectedSessionCandidate()) {
    return {
      ai_ceo_chat: {
        status: "blocked_before_model_chat",
        answer: "当前没有受保护登录会话，请登录后再向 AI CEO 发指令。",
      },
    };
  }
  try {
    const { payload: requestPayload, activeListingContext, safeSourceAssetIds } = envelope;
    if (requestPayload.chat_archive_contract === "server_finalized_chat_archive_v1") {
      hooks.onRequestIdentity?.(await saasAiCeoExpectedRequestArchiveIdentity(current, requestPayload));
    }
    const requiresWorkflowCompletionBudget = activeListingContext?.contract_version === "active_listing_context_v1";
    const defaultRequestTimeoutMs = safeSourceAssetIds.length || requiresWorkflowCompletionBudget ? 180000 : 60000;
    const requestedReconcileTimeoutMs = Number(options.reconcileTimeoutMs);
    const requestTimeoutMs = Number.isFinite(requestedReconcileTimeoutMs) && requestedReconcileTimeoutMs >= 1000
      ? Math.min(requestedReconcileTimeoutMs, defaultRequestTimeoutMs)
      : defaultRequestTimeoutMs;
    const requestedInlineAttempts = Number(options.maxInlineReconcileAttempts);
    const maxInlineReconcileAttempts = Number.isFinite(requestedInlineAttempts) && requestedInlineAttempts >= 0
      ? Math.min(3, Math.floor(requestedInlineAttempts))
      : 1;
    const reconcileDeadline = Date.now() + requestTimeoutMs;
    let inlineReconcileAttempts = 0;
    let payload = null;
    do {
      payload = await saasFetchNdjsonWithTimeout(
        `/stores/${encodeURIComponent(current.store_id)}/merchant-ceo/chat?stream=1&fresh=${Date.now()}`,
        {
          method: "POST",
          cache: "no-store",
          headers: {
            "cache-control": "no-store",
            pragma: "no-cache",
          },
          body: JSON.stringify(requestPayload),
        },
        requestTimeoutMs,
        hooks,
      );
      const requestStatus = String(payload?.ai_ceo_chat_request?.status || "");
      if (requestStatus !== "in_progress") break;
      hooks.onStage?.("idempotent_reconcile", payload.ai_ceo_chat_request);
      const retryAfterMs = Math.max(500, Math.min(5000, Number(payload.ai_ceo_chat_request.retry_after_ms || 1500)));
      if (inlineReconcileAttempts >= maxInlineReconcileAttempts || Date.now() + retryAfterMs >= reconcileDeadline) {
        payload = { ...payload, _http_status: 202 };
        break;
      }
      inlineReconcileAttempts += 1;
      await new Promise((resolve) => setTimeout(resolve, retryAfterMs));
    } while (Date.now() < reconcileDeadline);
    const responseHttpStatus = Number(payload?._http_status || payload?.http_status || 0) || 0;
    if (responseHttpStatus >= 400 && responseHttpStatus <= 599) {
      payload = {
        ...payload,
        _known_terminal: true,
        _transport_unknown: false,
      };
    }
    const enforceProjectIdentity = options.enforceProjectIdentity === true;
    const expectedIdentity = enforceProjectIdentity
      ? saasNormalizeListingProjectIdentity(activeListingContext?.listing_project_identity)
      : null;
    const responseIdentity = enforceProjectIdentity
      ? saasNormalizeListingProjectIdentity(payload?.ai_ceo_chat?.listing_project_identity)
      : null;
    const responseProjectMismatch = Boolean(enforceProjectIdentity && expectedIdentity?.key && (
      !responseIdentity ||
      responseIdentity.key !== expectedIdentity.key ||
      (expectedIdentity.source_report_id && responseIdentity.source_report_id !== expectedIdentity.source_report_id) ||
      (expectedIdentity.candidate_id && responseIdentity.candidate_id !== expectedIdentity.candidate_id)
    ));
    if (responseProjectMismatch) {
      return {
        _http_status: 409,
        ai_ceo_chat: {
          status: "project_context_mismatch",
          answer: "本次回复没有保持当前商品项目身份，捷境已阻止它覆盖当前商品。请重新进入该商品项目后重试；本次没有生成素材，也没有写入 eBay。",
          route: "ebay_workflow",
          route_label: "当前商品项目保护",
          listing_project_identity: expectedIdentity,
          source_records: [],
          work_records: [],
          confirmation_items: [],
          blocked_by: ["project_context_mismatch"],
        },
        ai_ceo_market_report: null,
        ai_ceo_market_report_delivery: null,
        product_vision_fact_packet: null,
        listing_created: false,
        usage_consumed: saasTriStateBoolean(payload?.usage_consumed),
        project_context_guard: {
          status: "blocked",
          reason: "response_identity_mismatch",
          expected_project_id: expectedIdentity.key,
          secret_exposed: false,
        },
        real_platform_writes_enabled: false,
        secret_exposed: false,
      };
    }
    return payload;
  } catch (error) {
    if (isSaasUnrecoverableSessionError(error)) {
      handleSaasUnrecoverableSession(error);
      throw error;
    }
    const httpStatus = Number(error?.status || 0) || 0;
    if (httpStatus >= 400 && httpStatus <= 599) {
      const errorPayload = error?.payload && typeof error.payload === "object" ? error.payload : {};
      const errorCode = sanitizeSaasNewListingProjectFailureReason(
        errorPayload.error_code || errorPayload.code || `http_${httpStatus}`,
      ) || `http_${httpStatus}`;
      const blockedBy = Array.from(new Set([
        ...(Array.isArray(errorPayload.blocked_by) ? errorPayload.blocked_by : []),
        errorCode,
      ].map(sanitizeSaasNewListingProjectFailureReason).filter(Boolean))).slice(0, 8);
      return {
        _http_status: httpStatus,
        _known_terminal: true,
        _transport_unknown: false,
        error_code: errorCode,
        ai_ceo_chat: {
          status: errorCode,
          answer: saasAiCeoMerchantSafeFailureText(error),
          route: "ebay_workflow",
          route_label: "请求校验",
          source_records: [],
          work_records: [],
          confirmation_items: [],
          blocked_by: blockedBy,
        },
        usage_consumed: saasTriStateBoolean(errorPayload.usage_consumed),
        listing_created: false,
        real_platform_writes_enabled: false,
        secret_exposed: false,
      };
    }
    return {
      _transport_unknown: true,
      ai_ceo_chat: {
        status: "model_call_failed",
        answer: saasAiCeoMerchantSafeFailureText(error),
      },
    };
  }
}

function saasTriStateBoolean(value) {
  return typeof value === "boolean" ? value : null;
}

function saasAiCeoMerchantSafeFailureText(error) {
  const raw = String(error?.message || error || "").toLowerCase();
  let title = "AI 连接暂时不可用";
  let reason = "这次没有拿到可展示回复。";
  let next = "你可以稍后重试，或到设置里的 AI 与素材查看连接状态。";
  if (/missing permission\s*:\s*create_task\b|\bcreate_task\b.{0,24}\bpermission\b|任务创建权限/.test(raw)) {
    title = "当前账号没有创建任务权限";
    reason = "当前店铺角色不能执行这项任务。";
    next = "请切换到有任务权限的账号，或联系团队负责人调整角色或权限。";
  } else if (raw.includes("402") || raw.includes("quota") || raw.includes("payment") || raw.includes("billing") || raw.includes("balance") || raw.includes("credit")) {
    title = "AI 额度或连接状态挡住了本次回复";
    reason = "这通常是当前套餐额度、用量上限或 AI 账号状态需要复核。";
    next = "先到设置里的 AI 与素材查看状态；不要重复填写连接信息，除非页面明确提示连接已失效。";
  } else if (raw.includes("401") || raw.includes("403") || raw.includes("unauthorized") || raw.includes("forbidden") || raw.includes("invalid")) {
    title = "AI 连接未通过本次校验";
    reason = "可能是连接权限、模型名称或账号状态需要复核。";
    next = "到设置里的 AI 与素材查看当前状态；敏感连接信息仍只在安全边界内处理。";
  } else if (raw.includes("timeout") || raw.includes("network") || raw.includes("fetch")) {
    title = "AI 连接超时";
    reason = "网络或 AI 连接临时不稳定。";
    next = "可以直接重试；如果是 Listing、发布、退款、广告等经营任务，我会继续保持确认边界。";
  }
  return `${title}。${reason} ${next} 本次不会产生捷境收费、不会写入 eBay，也不会把普通聊天写入长期经营记忆。`;
}

function saasAiCeoProductizedAnswerText(text = "", status = "") {
  const safeText = merchantConversationText(text || "AI CEO 暂时没有返回可展示内容。");
  const raw = `${status || ""} ${safeText}`.toLowerCase();
  if (
    raw.includes("402") ||
    raw.includes("quota") ||
    raw.includes("billing") ||
    raw.includes("payment") ||
    raw.includes("balance") ||
    raw.includes("credit") ||
    raw.includes("余额") ||
    raw.includes("额度") ||
    raw.includes("计费") ||
    raw.includes("账单")
  ) {
    return saasAiCeoMerchantSafeFailureText({ status: 402, message: safeText });
  }
  if (raw.includes("捷境后端接口") || raw.includes("traceback") || raw.includes("api key") || raw.includes("secret") || raw.includes("token")) {
    return saasAiCeoMerchantSafeFailureText({ message: safeText });
  }
  return safeText;
}

function classifySaasLocalClockRequest(text = "") {
  const normalized = String(text || "").trim().toLowerCase();
  if (!normalized) return "";
  if (/现在几点|几点了|当前时间|现在时间|北京时间|what time|current time|time is it/.test(normalized)) return "time";
  if (/今天几号|今天日期|今天是几号|今天星期几|今天周几|current date|today'?s date|date today/.test(normalized)) return "date";
  return "";
}

function buildSaasLocalClockAnswer(text = "") {
  const kind = classifySaasLocalClockRequest(text);
  if (!kind) return null;
  const now = new Date();
  const timezone = Intl?.DateTimeFormat?.().resolvedOptions?.().timeZone || "Asia/Shanghai";
  const label = timezone === "Asia/Shanghai" ? "北京时间" : "当前设备时间";
  const dateText = new Intl.DateTimeFormat("zh-CN", {
    timeZone: timezone,
    year: "numeric",
    month: "long",
    day: "numeric",
    weekday: "long",
  }).format(now);
  const timeText = new Intl.DateTimeFormat("zh-CN", {
    timeZone: timezone,
    hour: "2-digit",
    minute: "2-digit",
    hour12: false,
  }).format(now);
  return {
    status: "local_clock_answered",
    answer: kind === "time" ? `现在${label}是 ${dateText} ${timeText} 左右。` : `今天是 ${dateText}（${label}）。`,
    route: "general_chat",
    route_label: "直接回答",
    memory_policy: "transient_no_long_term_memory",
    long_term_memory: false,
    writes_merchant_rule: false,
    decision_center_required: false,
  };
}

async function hydrateSaasCeoCommandFromBackend(storeId = activeSaasStore()?.store_id || "") {
  const targetStoreId = String(storeId || "").trim();
  if (!targetStoreId || !hasSaasProtectedSessionCandidate()) return null;
  try {
    const payload = await saasFetch(`/stores/${encodeURIComponent(targetStoreId)}/merchant-ceo/commands/latest`);
    const command = applyBackendSaasCeoCommand(payload);
    if (command && state.view === "cockpit") {
      const latestCtx = saasMerchantWorkbenchContext();
      const consoleNode = document.querySelector("#view-cockpit .saas-ceo-command-console, #view-cockpit .ceo-home-boundary");
      replaceJiejingTrustedHtml(consoleNode, trustedJiejingHtml(renderSaasCeoCommandConsole(latestCtx, command), "ai_ceo.command_console.hydrate"));
      refreshSaasCeoRoutingTaskCard(command);
    }
    return command;
  } catch (error) {
    console.warn(`[JIEJING optional API skipped] merchant-ceo command hydrate: ${error.message}`);
    return null;
  }
}

function handleSaasCeoCommandSubmit(text, options = {}) {
  const newProjectRequest = prepareSaasNewListingProjectRequest(text, options.sourceAssetIds);
  if (newProjectRequest.blocked) {
    showActionToast("新的商品项目正在建立，请等待本次结果后再补充资料；不会重复提交。");
    return null;
  }
  const ctx = saasMerchantWorkbenchContext();
  const reusedRequestPayload = newProjectRequest.reuseUncertainRequest
    ? sanitizeSaasFrozenNewProjectRequestPayload(newProjectRequest.requestPayload, {
        storeId: String(activeSaasStore()?.store_id || storedSaasStoreId() || "").trim(),
      })
    : null;
  let command = reusedRequestPayload?.command || buildSaasCeoCommand(newProjectRequest.commandText, ctx);
  let frozenNewProjectRequestPayload = reusedRequestPayload;
  if (newProjectRequest.active && !frozenNewProjectRequestPayload) {
    const attemptIdentity = saasNewListingProjectAttemptIdentity(
      state.saasPendingNewListingProjectRequest?.originalText || newProjectRequest.commandText,
      newProjectRequest.sourceAssetIds,
      newProjectRequest.attemptSeed,
    );
    command = normalizeSaasCeoCommand({
      ...command,
      id: attemptIdentity.commandId,
      created_at: attemptIdentity.clientNow,
    });
    frozenNewProjectRequestPayload = buildSaasAiCeoChatRequestEnvelope(
      command,
      attemptIdentity.sourceAssetIds,
      {
        idempotencyKey: attemptIdentity.idempotencyKey,
        clientNow: attemptIdentity.clientNow,
        suppressActiveListingContext: true,
        suppressConversationHistory: true,
        suppressSupplierFacts: true,
      },
    )?.payload || null;
  }
  if (
    newProjectRequest.active &&
    !bindSaasNewListingProjectRequestToCommand(command?.id || "", frozenNewProjectRequestPayload)
  ) {
    const abandonedPending = state.saasPendingNewListingProjectRequest;
    stopSaasPendingNewListingProjectReconciliation();
    state.saasPendingNewListingProjectRequest = null;
    if (!saasMerchantProjectRouteId() && abandonedPending?.previousProjectId) {
      syncSaasProjectRoute(state.view || "cockpit", { projectId: abandonedPending.previousProjectId });
    }
    saveSaasProtectedStateSnapshot();
    showActionToast("新商品项目请求没有形成可安全重放的上下文，本次未调用模型。请重新提交商品目标。");
    return null;
  }
  const submittedRouteProjectId = saasMerchantProjectRouteId();
  const submittedProjectId = newProjectRequest.active ? "" : saasCurrentMerchantProjectId();
  state.saasLastCeoCommand = command;
  if (saasAiCeoCommandUsesProductTaskContext(command)) {
    const serverClockReliable = saasHasFreshServerClock();
    setSaasAiCeoTaskContextState("active_product_task", true, {
      commandId: command.id,
      projectId: "",
      startedAt: serverClockReliable ? new Date(saasServerNowMs()).toISOString() : "",
      startedAtReliable: serverClockReliable,
    });
  } else {
    setSaasAiCeoTaskContextState("plain_consultation", false);
  }
  refreshSaasAiCeoTaskContext();
  state.saasCeoCommandChatVisible = true;
  persistSaasLastCeoCommand(command);
  recordSaasCeoCommandSourceRecord(command);
  const submittedAtMs = Date.now();
  const submittedAt = new Date(submittedAtMs).toISOString();
  const submittedAccountContext = saasAiCeoHistoryRequestContext();
  const serverArchiveRequested = newProjectRequest.active
    ? frozenNewProjectRequestPayload?.chat_archive_contract === "server_finalized_chat_archive_v1" : true;
  let pendingMessageId = String(newProjectRequest.active && state.saasPendingNewListingProjectRequest?.assistantId || "") ||
    `ceo-ai-reply-${submittedAtMs.toString(16)}-${Math.abs(hashString(text)).toString(16)}`;
  if (newProjectRequest.active && state.saasPendingNewListingProjectRequest) {
    state.saasPendingNewListingProjectRequest.assistantId = pendingMessageId;
    saveSaasProtectedStateSnapshot();
  }
  const localInstantAnswer = buildSaasLocalClockAnswer(text);
  if (localInstantAnswer && !newProjectRequest.active) {
    const instantCommand = normalizeSaasCeoCommand({
      ...command,
      intent: "general_chat",
      ai_reply: localInstantAnswer.answer,
      ai_reply_status: localInstantAnswer.status,
      route: localInstantAnswer.route,
      route_label: localInstantAnswer.route_label,
      memory_policy: localInstantAnswer.memory_policy,
      long_term_memory: false,
      writes_merchant_rule: false,
      decision_center_required: false,
      high_risk: false,
      routes: [],
    });
    addCeoMessage(text, localInstantAnswer.answer, {
      assistantId: pendingMessageId,
      pending: false,
      status: localInstantAnswer.status,
      route: localInstantAnswer.route,
      route_label: localInstantAnswer.route_label,
      memory_policy: localInstantAnswer.memory_policy,
      long_term_memory: false,
      writes_merchant_rule: false,
      decision_center_required: false,
      createdAt: submittedAt,
    });
    if (instantCommand) {
      state.saasLastCeoCommand = instantCommand;
      persistSaasLastCeoCommand(state.saasLastCeoCommand);
      recordSaasCeoCommandSourceRecord(state.saasLastCeoCommand);
      state.saasLastCeoCommandPersistPromise = persistSaasCeoCommandToBackend(instantCommand);
    }
    const consoleNode = document.querySelector("#view-cockpit .saas-ceo-command-console, #view-cockpit .ceo-home-boundary");
    replaceJiejingTrustedHtml(consoleNode, trustedJiejingHtml(renderSaasCeoCommandConsole(ctx, instantCommand || command), "ai_ceo.command_console.instant"));
    refreshSaasCeoRoutingTaskCard(instantCommand || command);
    return instantCommand || command;
  }
  addCeoMessage(text, "正在思考", {
    assistantId: pendingMessageId,
    pending: true,
    pendingStage: "received",
    route: command.route || "",
    route_label: command.route_label || "",
    memory_policy: command.memory_policy || "transient_no_long_term_memory",
    long_term_memory: Boolean(command.long_term_memory),
    writes_merchant_rule: Boolean(command.writes_merchant_rule),
    decision_center_required: Boolean(command.decision_center_required),
    createdAt: submittedAt,
  });
  if (serverArchiveRequested) applySaasAiCeoArchivedResponseIdentity(pendingMessageId,
    { assistant_id: pendingMessageId, created_at: submittedAt, archived: false });
  scheduleSaasAiCeoPendingWatchdog(pendingMessageId, command);
  let streamRenderTimer = null;
  let streamRenderText = "";
  const flushStreamRender = () => {
    streamRenderTimer = null;
    if (streamRenderText) updateCeoAssistantStreamingMessage(pendingMessageId, streamRenderText);
  };
  const submittedSourceAssetIds = newProjectRequest.active
    ? frozenNewProjectRequestPayload?.source_asset_ids || newProjectRequest.sourceAssetIds
    : Array.isArray(options.sourceAssetIds)
      ? options.sourceAssetIds.slice(0, 8)
      : [];
  state.saasLastCeoCommandPersistPromise = requestSaasAiCeoChat(command, {
    onRequestIdentity: (expectedArchive) => {
      if (!isCurrentSaasAiCeoHistoryRequest(submittedAccountContext)) return;
      applySaasAiCeoArchivedResponseIdentity(pendingMessageId, { ...expectedArchive, created_at: submittedAt, archived: false });
      pendingMessageId = expectedArchive.assistant_id;
      if (newProjectRequest.active && state.saasPendingNewListingProjectRequest?.commandId === command.id) {
        state.saasPendingNewListingProjectRequest.assistantId = pendingMessageId;
        saveSaasProtectedStateSnapshot();
      }
      persistSaasAiCeoThread();
    },
    onStage: (stage) => {
      if (!isCurrentSaasAiCeoHistoryRequest(submittedAccountContext)) return;
      const latest = normalizeSaasAiCeoLatestTurn(state.saasAiCeoLatestTurn);
      if (!latest || latest.assistant_id !== pendingMessageId) return;
      updateCeoAssistantPendingMessage(pendingMessageId, {
        ...latest,
        status: "model_streaming",
        pending_stage: stage || "model",
        pending: true,
      });
    },
    onDelta: (_delta, fullText) => {
      if (!isCurrentSaasAiCeoHistoryRequest(submittedAccountContext)) return;
      streamRenderText = fullText;
      if (!streamRenderTimer) streamRenderTimer = setTimeout(flushStreamRender, 48);
    },
  }, submittedSourceAssetIds, {
    enforceProjectIdentity: options.enforceProjectIdentity === true,
    suppressActiveListingContext: newProjectRequest.active,
    suppressConversationHistory: newProjectRequest.active,
    suppressSupplierFacts: newProjectRequest.active,
    frozenRequestPayload: newProjectRequest.active ? frozenNewProjectRequestPayload : null,
  })
    .then((payload) => {
      if (streamRenderTimer) clearTimeout(streamRenderTimer);
      streamRenderTimer = null;
      if (!isCurrentSaasAiCeoHistoryRequest(submittedAccountContext)) return null;
      const latestTurnAtResponse = normalizeSaasAiCeoLatestTurn(state.saasAiCeoLatestTurn);
      const isCurrentChatTurn = !latestTurnAtResponse?.assistant_id || latestTurnAtResponse.assistant_id === pendingMessageId;
      const archived = saasAiCeoArchivedResponseIdentity(payload);
      const replyCreatedAt = archived?.created_at || submittedAt;
      if (archived) {
        applySaasAiCeoArchivedResponseIdentity(pendingMessageId, archived);
        pendingMessageId = archived.assistant_id;
      }
      const chat = payload?.ai_ceo_chat && typeof payload.ai_ceo_chat === "object" ? payload.ai_ceo_chat : null;
      const productVisionFactPacket =
        payload?.product_vision_fact_packet && typeof payload.product_vision_fact_packet === "object"
          ? payload.product_vision_fact_packet
          : null;
      let aiCeoMarketReport =
        payload?.ai_ceo_market_report && typeof payload.ai_ceo_market_report === "object" ? payload.ai_ceo_market_report : null;
      let aiCeoMarketReportDelivery = normalizeSaasAiCeoMarketReportDelivery(payload?.ai_ceo_market_report_delivery || null);
      const logicalHttpStatus = Number(payload?._http_status || payload?.http_status || 0) || 0;
      const requestStillInProgress = String(payload?.ai_ceo_chat_request?.status || "") === "in_progress";
      const requestOutcomeUnknown = saasPendingNewListingProjectOutcomeUnknown(payload);
      if (requestStillInProgress || requestOutcomeUnknown) {
        if (newProjectRequest.active) {
          markSaasNewListingProjectRequestFailed(command?.id || "", "uncertain");
          scheduleSaasPendingNewListingProjectReconciliation();
        }
        updateCeoAssistantPendingMessage(pendingMessageId, {
          ...(state.saasAiCeoLatestTurn || {}),
          assistant_id: pendingMessageId,
          created_at: replyCreatedAt,
          assistant_text: requestStillInProgress
            ? "这次新商品项目仍在后端处理中。捷境已保留同一请求标识，刷新或稍后重试不会再次调用模型。"
            : "这次请求的最终执行结果暂时无法确认。捷境会先按原请求对账，不会另起一次模型调用；请不要重复新建同一商品项目。",
          status: requestStillInProgress ? "request_reconciling" : "request_outcome_unknown",
          pending_stage: requestStillInProgress ? "idempotent_reconcile" : "",
          pending: requestStillInProgress,
        });
        return command;
      }
      const dependencyBlockedWithoutUsage =
        logicalHttpStatus >= 500 && payload?.usage_consumed === false && payload?.listing_created === false;
      const rawAnswer = saasAiCeoProductizedAnswerText(chat?.answer || "", chat?.status || "");
      const answer = dependencyBlockedWithoutUsage
        ? `${rawAnswer ? `${rawAnswer}\n\n` : ""}本次未调用模型、未消耗次数、未生成草稿。`
        : rawAnswer;
      const sourceRecords = normalizeSaasAiCeoSourceRecords(chat?.source_records || chat?.realtime_search?.source_records || []);
      const workRecords = normalizeSaasAiCeoWorkRecords(chat?.work_records || chat?.workflow_handoff?.work_records || []);
      const confirmationItems = normalizeSaasAiCeoConfirmationItems(chat?.confirmation_items || chat?.workflow_handoff?.confirmation_items || []);
      const sourcePolicy = chat?.source_policy && typeof chat.source_policy === "object" ? chat.source_policy : chat?.workflow_handoff?.source_policy || null;
      const modelResolution = payload?.model_secret_resolution && typeof payload.model_secret_resolution === "object" ? payload.model_secret_resolution : chat?.model_secret_resolution || null;
      const modelConnection = chat?.model_connection && typeof chat.model_connection === "object" ? chat.model_connection : null;
      const answerQuality = chat?.answer_quality && typeof chat.answer_quality === "object" ? chat.answer_quality : null;
      const performance = chat?.performance && typeof chat.performance === "object" ? chat.performance : null;
      const blockedBy = [
        ...(Array.isArray(chat?.blocked_by) ? chat.blocked_by : []),
        ...(Array.isArray(modelResolution?.blocked_by) ? modelResolution.blocked_by : []),
      ];
      const marketReportCandidateTurn = normalizeSaasAiCeoLatestTurn({
        ...(isCurrentChatTurn ? state.saasAiCeoLatestTurn || {} : {}),
        archive_pending: serverArchiveRequested && !archived,
        user_text: text,
        assistant_id: pendingMessageId,
        assistant_text: answer,
        status: chat?.status || "",
        store_id: command.store_id,
        model: chat?.model_client || state.saasAiCeoLatestTurn?.model || null,
        route: chat?.route || command.route || "general_chat",
        route_label: chat?.route_label || command.route_label || "",
        memory_policy: chat?.memory_policy || command.memory_policy || "transient_no_long_term_memory",
        long_term_memory: Boolean(chat?.long_term_memory || command.long_term_memory),
        writes_merchant_rule: Boolean(chat?.writes_merchant_rule || command.writes_merchant_rule),
        decision_center_required: Boolean(chat?.decision_center_required || command.decision_center_required),
        source_records: sourceRecords,
        work_records: workRecords,
        confirmation_items: confirmationItems,
        source_policy: sourcePolicy,
        blocked_by: blockedBy,
        model_secret_resolution: modelResolution,
        model_connection: modelConnection,
        answer_quality: answerQuality,
        market_report_id: aiCeoMarketReport?.report_id || aiCeoMarketReportDelivery?.report_id || "",
        market_report_delivery: aiCeoMarketReportDelivery,
        listing_project_identity: chat?.listing_project_identity || null,
        performance,
        pending_stage: "",
        pending: false,
        created_at: replyCreatedAt,
      });
      const marketReportTurn = ensureSaasAiCeoMarketReportRecordFromTurn(marketReportCandidateTurn, aiCeoMarketReport);
      if (marketReportTurn?.market_report_id) {
        const structuredReport = (state.saasReports || []).find(
          (record) => record?.report_id === marketReportTurn.market_report_id && record.report_type === "ai_ceo.market_research",
        );
        if (!aiCeoMarketReport?.report_id && structuredReport) aiCeoMarketReport = structuredReport;
        aiCeoMarketReportDelivery =
          aiCeoMarketReportDelivery ||
          marketReportTurn.market_report_delivery ||
          (structuredReport ? saasAiCeoMarketReportDeliveryFromRecord(structuredReport) : null);
      }
      const backendCommand = backendSaasCeoCommandFromPayload(payload || {});
      const mergedCommand = normalizeSaasCeoCommand({
        ...(backendCommand || command),
        ai_reply: answer,
        ai_reply_status: chat?.status || "unknown",
        ai_reply_model: chat?.model_client || null,
        route: chat?.route || backendCommand?.route || command.route || "general_chat",
        route_label: chat?.route_label || backendCommand?.route_label || command.route_label || "",
        memory_policy: chat?.memory_policy || backendCommand?.memory_policy || command.memory_policy || "transient_no_long_term_memory",
        long_term_memory: Boolean(chat?.long_term_memory || backendCommand?.long_term_memory || command.long_term_memory),
        writes_merchant_rule: Boolean(chat?.writes_merchant_rule || backendCommand?.writes_merchant_rule || command.writes_merchant_rule),
        decision_center_required: Boolean(chat?.decision_center_required || backendCommand?.decision_center_required || command.decision_center_required),
      });
      if (mergedCommand && isCurrentChatTurn) {
        state.saasLastCeoCommand = newestSaasCeoCommand(mergedCommand, state.saasLastCeoCommand);
        persistSaasLastCeoCommand(state.saasLastCeoCommand);
        recordSaasCeoCommandSourceRecord(state.saasLastCeoCommand);
      }
      updateCeoAssistantMessage(pendingMessageId, answer, chat?.status || "", chat?.model_client || null, sourceRecords, {
        work_records: workRecords,
        confirmation_items: confirmationItems,
        source_policy: sourcePolicy,
        blocked_by: blockedBy,
        model_secret_resolution: modelResolution,
        model_connection: modelConnection,
        answer_quality: answerQuality,
        market_report_delivery: aiCeoMarketReportDelivery,
        performance,
      });
      const completedTurn = {
        ...(isCurrentChatTurn ? state.saasAiCeoLatestTurn || {} : {}),
        archive_pending: serverArchiveRequested && !archived,
        user_text: text,
        assistant_id: pendingMessageId,
        assistant_text: answer,
        status: chat?.status || "",
        store_id: command.store_id,
        model: chat?.model_client || state.saasAiCeoLatestTurn?.model || null,
        route: chat?.route || mergedCommand?.route || "general_chat",
        route_label: chat?.route_label || mergedCommand?.route_label || "",
        memory_policy: chat?.memory_policy || mergedCommand?.memory_policy || "transient_no_long_term_memory",
        long_term_memory: Boolean(chat?.long_term_memory || mergedCommand?.long_term_memory),
        writes_merchant_rule: Boolean(chat?.writes_merchant_rule || mergedCommand?.writes_merchant_rule),
        decision_center_required: Boolean(chat?.decision_center_required || mergedCommand?.decision_center_required),
        source_records: sourceRecords,
        work_records: workRecords,
        confirmation_items: confirmationItems,
        source_policy: sourcePolicy,
        blocked_by: blockedBy,
        model_secret_resolution: modelResolution,
        model_connection: modelConnection,
        answer_quality: answerQuality,
        market_report_id: aiCeoMarketReport?.report_id || aiCeoMarketReportDelivery?.report_id || "",
        market_report_delivery: aiCeoMarketReportDelivery,
        listing_project_identity: chat?.listing_project_identity || null,
        performance,
        pending_stage: "",
        pending: false,
        created_at: replyCreatedAt,
      };
      const completedTurnWithReport = ensureSaasAiCeoMarketReportRecordFromTurn(completedTurn, aiCeoMarketReport) || completedTurn;
      const responseIdentity = saasNormalizeListingProjectIdentity(completedTurnWithReport?.listing_project_identity);
      const routeProjectIdAtResponse = saasMerchantProjectRouteId();
      const pendingNewProjectAtResponse = state.saasPendingNewListingProjectRequest;
      const ownsPendingNewProject = Boolean(
        newProjectRequest.active &&
          pendingNewProjectAtResponse &&
          String(pendingNewProjectAtResponse.commandId || "") === String(command?.id || ""),
      );
      const pendingRouteCompatible = Boolean(
        !routeProjectIdAtResponse ||
          routeProjectIdAtResponse === responseIdentity?.key,
      );
      let newProjectCommitted = false;
      if (ownsPendingNewProject) {
        if (responseIdentity?.key && pendingRouteCompatible) {
          newProjectCommitted = commitSaasNewListingProjectRequest(completedTurnWithReport, command?.id || "");
        }
        if (!newProjectCommitted && responseIdentity?.key) {
          completeSaasNewListingProjectRequest(command?.id || "");
        } else if (!newProjectCommitted) {
          const transportUnknown = payload?._transport_unknown === true;
          markSaasNewListingProjectRequestFailed(
            command?.id || "",
            transportUnknown ? "uncertain" : "failed",
            transportUnknown ? {} : { failureReason: saasPendingNewListingProjectFailureReason(payload) },
          );
          if (transportUnknown) scheduleSaasPendingNewListingProjectReconciliation();
        }
      }
      const routeStayedOnSubmittedProject = newProjectRequest.active
        ? !routeProjectIdAtResponse ||
          routeProjectIdAtResponse === responseIdentity?.key
        : routeProjectIdAtResponse === submittedRouteProjectId;
      const responseMatchesSubmittedProject = newProjectRequest.active
        ? Boolean(newProjectCommitted && responseIdentity?.key)
        : Boolean(submittedProjectId && responseIdentity?.key && responseIdentity.key === submittedProjectId);
      const responseProjectCompatible = routeStayedOnSubmittedProject && responseMatchesSubmittedProject;
      if (
        productVisionFactPacket &&
        responseProjectCompatible &&
        ((!newProjectRequest.active && isCurrentChatTurn) || newProjectCommitted)
      ) {
        applySaasAiCeoProductFactPacket(productVisionFactPacket, text, payload?.product_vision_report || null, {
          listingProjectIdentity: responseIdentity,
        });
      }
      if (isCurrentChatTurn) {
        updateSaasAiCeoLatestReply(completedTurnWithReport);
      } else {
        upsertSaasAiCeoThreadTurn(completedTurnWithReport);
      }
      if (!mergedCommand || state.view !== "cockpit" || !isCurrentChatTurn) return mergedCommand;
      const latestCtx = saasMerchantWorkbenchContext();
      const consoleNode = document.querySelector("#view-cockpit .saas-ceo-command-console, #view-cockpit .ceo-home-boundary");
      replaceJiejingTrustedHtml(consoleNode, trustedJiejingHtml(renderSaasCeoCommandConsole(latestCtx, mergedCommand), "ai_ceo.command_console.backend"));
      refreshSaasCeoRoutingTaskCard(mergedCommand);
      return mergedCommand;
    })
    .catch((error) => {
      if (streamRenderTimer) clearTimeout(streamRenderTimer);
      streamRenderTimer = null;
      if (!isCurrentSaasAiCeoHistoryRequest(submittedAccountContext)) return null;
      const sessionExpired = isSaasUnrecoverableSessionError(error);
      if (newProjectRequest.active) markSaasNewListingProjectRequestFailed(
        command?.id || "",
        sessionExpired ? "failed" : "uncertain",
        sessionExpired ? { failureReason: "session_expired" } : {},
      );
      if (newProjectRequest.active && !sessionExpired) scheduleSaasPendingNewListingProjectReconciliation();
      const failureStatus = sessionExpired ? "session_expired" : "model_call_failed";
      const safeText = sessionExpired
        ? "捷境登录已失效，请重新登录。本次没有调用 AI、没有消耗素材点，也没有写入 eBay；这次目标已保留在本机。"
        : "AI CEO 连接暂时没有完成。我已经保留这次目标，可以稍后重试或补充资料；真实发布、付款、退款、广告、授权和敏感客服承诺不会自动执行。";
      const latest = normalizeSaasAiCeoLatestTurn({
        ...(state.saasAiCeoLatestTurn || {}),
        archive_pending: serverArchiveRequested,
        assistant_id: pendingMessageId,
        assistant_text: safeText,
        status: failureStatus,
        route: command.route || state.saasAiCeoLatestTurn?.route || "general_chat",
        route_label: command.route_label || state.saasAiCeoLatestTurn?.route_label || "",
        memory_policy: command.memory_policy || state.saasAiCeoLatestTurn?.memory_policy || "transient_no_long_term_memory",
        pending_stage: "",
        pending: false,
        created_at: submittedAt,
      });
      updateCeoAssistantMessage(pendingMessageId, safeText, failureStatus, latest?.model || null, []);
      const latestTurnAtFailure = normalizeSaasAiCeoLatestTurn(state.saasAiCeoLatestTurn);
      if (latest && (!latestTurnAtFailure?.assistant_id || latestTurnAtFailure.assistant_id === pendingMessageId)) updateSaasAiCeoLatestReply(latest);
      return null;
    });
  const consoleNode = document.querySelector("#view-cockpit .saas-ceo-command-console, #view-cockpit .ceo-home-boundary");
  if (consoleNode) {
    replaceJiejingTrustedHtml(consoleNode, trustedJiejingHtml(renderSaasCeoCommandConsole(ctx, command), "ai_ceo.command_console.pending"));
  }
  refreshSaasCeoRoutingTaskCard(command);
  // The message stream and route card already confirm receipt; avoid covering the mobile handoff card.
  return command;
}

function latestSaasMerchantReport() {
  return (
    (state.saasReports || []).find((record) => ["ai_ceo.market_research", "market.report", "listing.package"].includes(record.report_type || "")) ||
    (state.saasReports || [])[0] ||
    null
  );
}

function addSaasMerchantFeedback(kind = "useful") {
  if (!requireSaasProtectedSessionForAction()) return false;
  const latest = latestSaasMerchantReport();
  const ruleInput = document.getElementById("saas-merchant-rule-memory");
  const ruleText = ruleInput?.value?.trim() || "";
  if (kind === "remember_rule" && !ruleText) {
    showActionToast("先写下要记住的规则，例如利润底线、供应商禁区或客服承诺边界。");
    return false;
  }
  const record = normalizeSaasMerchantFeedback({
    id: `feedback-${Date.now()}`,
    feedback_type: kind,
    report_id: latest?.report_id || latest?.task_id || "no_report_yet",
    report_type: latest?.report_type || "",
    report_title: latest?.title || saasReportTypeLabel(latest?.report_type || ""),
    rule_text: kind === "remember_rule" ? ruleText : "",
    created_at: new Date().toISOString(),
  });
  state.saasMerchantFeedback = [record, ...(state.saasMerchantFeedback || [])].slice(0, 80);
  if (kind === "remember_rule") {
    state.saasMerchantMemory = [
      {
        memory_type: "merchant_rule_feedback",
        title: "商家要求记住的规则",
        summary: ruleText,
        created_at: record.created_at,
        source: "merchant_feedback",
      },
      ...(state.saasMerchantMemory || []),
    ].slice(0, 20);
  }
  persistSaasMerchantFeedback();
  if (ruleInput) ruleInput.value = "";
  const label = kind === "useful" ? "有用反馈" : kind === "not_useful" ? "没用反馈" : "商家规则";
  showActionToast(`${label}已记录到当前账号空间；不会触发平台写入。`);
  setView(state.view || "connect", { preserveFlowKey: true });
  return true;
}

function normalizeSaasSourceRecord(item = {}, origin = "manual", index = 0) {
  const url = String(item.url || item.href || "").trim();
  const title = publicRuntimeText(item.title || item.name || item.label || item.source_type || "");
  const note = publicRuntimeText(item.note || item.summary || item.snippet || item.detail || item.reason || "");
  const sourceType = item.source_type || item.type || item.source || origin;
  const capturedAt = item.captured_at || item.created_at || item.updated_at || new Date().toISOString();
  if (!url && !title && !note) return null;
  return {
    id: item.id || item.record_id || `source-${origin}-${index}-${Math.abs(hashString(`${url}|${title}|${capturedAt}`))}`,
    source_type: String(sourceType || origin),
    title: title || (url ? "URL source" : "Source record"),
    url,
    note,
    captured_at: capturedAt,
    origin,
    status: item.status || "read_only_source_record",
    safety: "source_record_only_no_browser_control_no_platform_write",
  };
}

function hashString(value = "") {
  let hash = 0;
  String(value).split("").forEach((char) => {
    hash = (hash << 5) - hash + char.charCodeAt(0);
    hash |= 0;
  });
  return hash;
}

function extractSaasSourceRecordsFromReport(record = {}, reportIndex = 0) {
  const report = record.report || {};
  const direct = Array.isArray(report.source_records) ? report.source_records : [];
  const nested = Array.isArray(report.report?.source_records) ? report.report.source_records : [];
  return [...direct, ...nested]
    .map((item, index) => normalizeSaasSourceRecord(item, `report:${record.report_type || reportIndex}`, index))
    .filter(Boolean);
}

function saasCollectedSourceRecords(ctx = saasMerchantWorkbenchContext()) {
  const packetRecords = Array.isArray(ctx.packetBody?.source_records) ? ctx.packetBody.source_records : [];
  const publicSearchRecords = Array.isArray(state.saasLastPublicSearchHandoff?.source_records)
    ? state.saasLastPublicSearchHandoff.source_records
    : [];
  const reportRecords = (state.saasReports || []).flatMap(extractSaasSourceRecordsFromReport);
  const manualRecords = (state.saasSourceRecords || []).map((item, index) => normalizeSaasSourceRecord(item, "merchant_manual", index)).filter(Boolean);
  const all = [
    ...manualRecords,
    ...packetRecords.map((item, index) => normalizeSaasSourceRecord(item, "official_packet", index)).filter(Boolean),
    ...publicSearchRecords.map((item, index) => normalizeSaasSourceRecord(item, "public_search", index)).filter(Boolean),
    ...reportRecords,
  ];
  const seen = new Set();
  return all.filter((record) => {
    const key = `${record.url || ""}|${record.title || ""}|${record.source_type || ""}`.toLowerCase();
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function sourceRecordTypeLabel(type = "") {
  const normalized = String(type || "").toLowerCase();
  if (normalized.includes("official") || normalized.includes("packet")) return "官方资料";
  if (normalized.includes("public") || normalized.includes("web") || normalized.includes("search")) return "公开网页";
  if (normalized.includes("merchant") || normalized.includes("manual")) return "商家补充";
  if (normalized.includes("report")) return "AI 报告引用";
  return productizeJiejingProductCopy(type || "来源记录");
}

function addManualSaasSourceRecordFromSettings() {
  if (!requireSaasProtectedSessionForAction()) return false;
  const urlInput = document.getElementById("saas-source-record-url");
  const titleInput = document.getElementById("saas-source-record-title");
  const noteInput = document.getElementById("saas-source-record-note");
  const typeInput = document.getElementById("saas-source-record-type");
  const url = urlInput?.value?.trim() || "";
  const title = titleInput?.value?.trim() || "";
  const note = noteInput?.value?.trim() || "";
  const sourceType = typeInput?.value || "public_web";
  if (!url && !title && !note) {
    showActionToast("先填写 URL、标题或备注，才会保存来源记录。");
    return false;
  }
  if (url) {
    try {
      const parsed = new URL(url);
      if (!["http:", "https:"].includes(parsed.protocol)) throw new Error("unsupported protocol");
    } catch (error) {
      showActionToast("来源 URL 只接受 http/https，不能保存本机路径或敏感凭证。");
      return false;
    }
  }
  const record = normalizeSaasSourceRecord(
    {
      id: `manual-${Date.now()}`,
      url,
      title: title || url,
      note,
      source_type: sourceType,
      captured_at: new Date().toISOString(),
      status: "merchant_saved",
    },
    "merchant_manual",
    0,
  );
  state.saasSourceRecords = [record, ...(state.saasSourceRecords || [])].filter(Boolean).slice(0, 60);
  persistSaasSourceRecords();
  [urlInput, titleInput, noteInput].forEach((input) => {
    if (input) input.value = "";
  });
  showActionToast("来源记录已保存：只作为报告证据，不触发浏览器控制或平台写入。");
  setView(state.view || "connect", { preserveFlowKey: true });
  return true;
}

function clearManualSaasSourceRecords() {
  state.saasSourceRecords = [];
  try {
    const payload = JSON.parse(localStorage.getItem(saasStorageKeys.sourceRecords) || "{}");
    saasSourceRecordStorageScopes(true).forEach((scope) => {
      delete payload[scope];
    });
    localStorage.setItem(saasStorageKeys.sourceRecords, JSON.stringify(payload));
  } catch (error) {
    persistSaasSourceRecords();
  }
  showActionToast("已清空本账号本店铺的手动来源记录。");
  setView(state.view || "connect", { preserveFlowKey: true });
}

async function copySaasSourceRecordsSnapshot() {
  const records = saasCollectedSourceRecords();
  const payload = {
    generated_at: new Date().toISOString(),
    account: saasAccountDisplayName(),
    store_id: activeSaasStore()?.store_id || "",
    source_record_count: records.length,
    records: records.slice(0, 40),
    boundary: {
      source_record_only: true,
      browser_control_enabled: false,
      real_platform_writes_enabled: false,
      secrets_included: false,
    },
  };
  const text = JSON.stringify(payload, null, 2);
  try {
    await navigator.clipboard?.writeText(text);
    showActionToast("已复制来源记录快照；不包含敏感凭证、买家敏感信息或平台账号资料。");
  } catch (error) {
    showActionToast("复制失败，请从页面查看来源记录。");
  }
}

function saasMerchantNextAction(ctx = saasMerchantWorkbenchContext()) {
  if (hasSaasAccountReadInProgress()) {
    return {
      tone: "green",
      label: "读取中",
      title: "正在读取真实账号状态",
      body: "正在读取 eBay 授权、AI 连接、报告和确认中心；读取完成前不会用模拟商品或旧样例填充。",
      primaryAction: "refresh",
      primaryLabel: "刷新真实状态",
    };
  }
  if (!state.saasConnected) {
    return {
      tone: "amber",
      label: "先登录",
      title: "先登录捷境账号",
      body: "登录后工作台会按账号读取 eBay 只读同步、AI CEO 报告和确认中心；未登录时不创建匿名经营数据。",
      primaryAction: "refresh",
      primaryLabel: "刷新登录状态",
    };
  }
  if (!ctx.connection || !isSaasAuthorizedConnectionStatus(ctx.connection.status)) {
    return {
      tone: "amber",
      label: "先连接 eBay",
      title: "先完成 eBay 官方只读授权",
      body: "捷境只读取经营分析需要的数据；发布、改价、付款、退款和买家承诺不会自动执行。",
      primaryAction: "plan-ebay-oauth",
      primaryLabel: "检查只读授权",
    };
  }
  if (!ctx.hasPacket) {
    return {
      tone: "amber",
      label: "同步数据",
      title: "把店铺、Listing、订单、费用和政策同步成经营资料",
      body: "AI CEO 先基于官方只读数据工作，缺资料会清楚标出来，不拿占位内容冒充真实结果。",
      primaryAction: "sync-ebay-readonly",
      primaryLabel: "同步 eBay 数据",
    };
  }
  if (!ctx.reports.length) {
    return {
      tone: "green",
      label: "生成报告",
      title: "数据已就绪，下一步让 AI CEO 产出经营报告",
      body: "报告会覆盖市场判断、刊登建议、素材任务、客服学习、财务复核和需要确认的动作。",
      primaryAction: "run-workflow",
      primaryLabel: "生成 AI CEO 报告",
    };
  }
  if (ctx.pendingConfirmations.length) {
    return {
      tone: "amber",
      label: "待你确认",
      title: `${ctx.pendingConfirmations.length} 个动作需要你确认`,
      body: "AI CEO 已把高风险动作停在确认中心。你不点头，系统不会发布、付款、退款、改价或承诺买家。",
      primaryAction: "open-confirm",
      primaryLabel: "查看确认中心",
    };
  }
  return {
    tone: "green",
    label: "继续经营",
    title: "这轮数据和 AI CEO 输出已形成闭环",
    body: "可以继续同步最新 eBay 数据，或把下一件商品交给 AI CEO 做调研、刊登草稿和确认项。",
    primaryAction: "sync-ebay-readonly",
    primaryLabel: "更新 eBay 数据",
  };
}

function saasCockpitDraftAvailabilitySummary() {
  const store = activeSaasStore();
  const connection = latestSaasConnection();
  const connected = Boolean(connection && isSaasAuthorizedConnectionStatus(connection.status));
  const draftAuthorized = Boolean(store && isSaasEbayUnpublishedDraftAuthorized(store));
  if (!connected) {
    return {
      tone: "amber",
      label: "eBay 草稿",
      title: "先连接店铺",
      detail: "连接后才能核对未发布草稿权限；不会因此自动公开发布。",
    };
  }
  if (!draftAuthorized) {
    return {
      tone: "amber",
      label: "eBay 草稿",
      title: "未发布草稿权限待开通",
      detail: "只开通保存未发布草稿所需权限；公开发布仍需单独预检和确认。",
    };
  }
  return {
    tone: "green",
    label: "eBay 草稿",
    title: "未发布草稿可保存",
    detail: "Listing 资料通过检查后可保存为未发布 Offer；公开发布仍需单独确认。",
  };
}

function saasCockpitPublishSummary() {
  const readiness = state.saasLastPublishReadiness && typeof state.saasLastPublishReadiness === "object" ? state.saasLastPublishReadiness : null;
  if (readiness) {
    const report = saasPublishTrafficLightReport(readiness);
    const tone = saasPublishTrafficLightTone(report);
    return {
      tone,
      label: "发布体检",
      title:
        tone === "red"
          ? `${Number(report.red_count || 0)} 个红项阻断`
          : tone === "amber"
            ? `${Number(report.yellow_count || 0)} 个黄项复核`
            : "可进入确认中心",
      detail: `red=${Number(report.red_count || 0)} / yellow=${Number(report.yellow_count || 0)} / green=${Number(report.green_count || 0)}，真实发布仍需确认中心放行。`,
    };
  }
  const hasPublishConfirmation = (state.saasConfirmations || []).some((item) => item.action_type === "publish_listing");
  return {
    tone: hasPublishConfirmation ? "amber" : "neutral",
    label: "发布体检",
    title: hasPublishConfirmation ? "等待后端体检刷新" : "尚未创建发布确认单",
    detail: "先补齐新商品资料，再创建发布确认单；这里不会直接写入 eBay。",
  };
}

