function renderSaasCeoCockpitStatusStrip(statusPills, ctx) {
  const packetAge = ctx.latestPacket?.created_at || ctx.latestPacket?.createdAt || ctx.packetBody?.created_at || "";
  const cards = (statusPills || [])
    .map((pill) => {
      const tone = pill.tone === "green" ? "green" : pill.tone === "red" ? "red" : "amber";
      return `
        <article class="saas-ai-ceo-status-card is-${tone}">
          <span>${escapeHtml(pill.label || "")}</span>
          <strong>${escapeHtml(pill.value || "")}</strong>
          <small>${escapeHtml(pill.note || "")}</small>
        </article>
      `;
    })
    .join("");
  return `
    <section class="saas-ai-ceo-cockpit-status" aria-label="AI CEO 当前运营状态">
      <div class="saas-ai-ceo-status-strip">
        ${cards}
      </div>
      <div class="saas-ai-ceo-evidence-ticker" aria-label="当前证据链">
        <span>证据链</span>
        <strong>${escapeHtml(ctx.hasPacket ? "店铺资料已读取" : "等待店铺资料")}</strong>
        <small>${escapeHtml(packetAge || "发布、改价、退款、广告和敏感客服承诺仍进决策中心")}</small>
      </div>
    </section>
  `;
}

