function renderTasks() {
  const list = document.querySelector("#confirmTasks");
  if (!list) return;
  const visibleTasks = tasks.filter(shouldSurfaceImmediately);
  const tuckedAwayCount = Math.max(tasks.length - visibleTasks.length, 0);
  list.innerHTML = visibleTasks
    .map(
      (task) => `
        <article class="task-row">
          <div>
            <strong>${task.title}</strong>
            <p>${task.detail}</p>
          </div>
          <span class="pill ${pillClass(task.risk)}">${task.status}</span>
        </article>
      `,
    )
    .join("") + (tuckedAwayCount
    ? `
      <article class="task-row auto-row">
        <div>
          <strong>${tuckedAwayCount} 项中低风险工作已改为自动推进或集中确认</strong>
          <p>例如素材草稿、文案版本、普通过程留档，不再单独打断你。</p>
        </div>
        <span class="pill green">已收起</span>
      </article>
    `
    : "");
}

function renderAgents() {
  const grid = document.querySelector("#agentGrid");
  if (!grid) return;
  grid.innerHTML = agents
    .map(
      ([name, detail, progress]) => `
        <article class="agent-card">
          <div class="agent-top">
            <strong>${name}</strong>
            <span class="pill neutral">${progress}%</span>
          </div>
          <p>${detail}</p>
          <div class="mini-bar" aria-hidden="true"><span style="width:${progress}%"></span></div>
        </article>
      `,
    )
    .join("");
}

function renderOperatingModules() {
  const grid = document.querySelector("#operatingModuleGrid");
  if (!grid) return;
  grid.innerHTML = operatingModules
    .map(
      (module) => `
        <article class="operating-module-card">
          <div class="module-card-top">
            <span>${module.source}</span>
            <em class="pill ${module.tone}">${module.status}</em>
          </div>
          <strong>${module.name}</strong>
          <p>${module.detail}</p>
        </article>
      `,
    )
    .join("");
}

function renderRuleOutput() {
  const mode = state.activeRule;
  const { profitFloor, riskLevel, tone, permissionLevel, fulfillmentMode } = state.dna;
  const permissionDetail = permissionModeDetail(permissionLevel);
  const content = {
    profit: `
      <strong>利润规则</strong>
      <ul>
        <li>低于 ${profitFloor}%：选品、广告和 Listing 发布都会先停在确认中心。</li>
        <li>利润测算会纳入平台成交费、订阅费、广告费、物流成本和退货预留。</li>
        <li>高于安全线也不会自动发布，仍需要你确认价格、承诺和风险。</li>
      </ul>
    `,
    risk: `
      <strong>风险规则</strong>
      <ul>
        <li>当前偏好：${riskText(riskLevel)}。</li>
        <li>VeRO、禁售会先拦截并留痕；只有涉及资金相关、真实发布、退款、广告、客服发送或明确承诺时才打断你。</li>
        <li>${fulfillmentText(fulfillmentMode)} 会影响 handling time 建议。</li>
      </ul>
    `,
    service: `
      <strong>客服规则</strong>
      <ul>
        <li>默认口吻：${toneText(tone)}。</li>
        <li>普通尺寸、库存、使用方式和 tracking 同步可生成草稿，低风险可自动推进。</li>
        <li>退款、补偿、差评、纠纷、明确到货承诺和金钱承诺才进入人工确认。</li>
      </ul>
    `,
    permission: `
      <strong>AI 权限矩阵</strong>
      <ul>
        <li>当前权限：${permissionText(permissionLevel)}。</li>
        <li>资料整理、素材生成、草稿、风险标记和过程留档默认可自动推进。</li>
        <li>发布 Listing、改价、退款/补偿、广告预算、平台授权、店铺业务政策 和扣费动作默认禁止自动执行。</li>
        <li>${permissionDetail.hint}</li>
      </ul>
    `,
  };
  document.querySelector("#ruleOutput").innerHTML = content[mode];
}

