    ebayApiMode: "数据接入",
    feeInsightMode: "费用利润",
    fulfillmentMode: "履约方式",
    sourceApiMode: "货源连接",
    profitFloor: "利润底线",
    riskLevel: "风险偏好",
    tone: "客服售后",
