function onboardingChoiceContextMarkup(current, taskMeta) {
  const manualCount = manualKeysForField(current.field).length;
  const currentValue = onboardingValueText(current.field);
  return `
    <div class="onboarding-choice-context">
      <div>
        <span>本步影响</span>
        <strong>${escapeHtml(taskMeta.task)}</strong>
        <p>${escapeHtml(taskMeta.ai)} ${escapeHtml(taskMeta.human)}</p>
      </div>
      <div>
        <span>当前保存</span>
        <strong>${escapeHtml(currentValue)}</strong>
        <p>${manualCount ? `本步有 ${manualCount} 个外部入口或人工确认项。` : "本步不需要外部账号动作，可以直接继续。"}</p>
      </div>
    </div>
  `;
}

function onboardingSummaryMetricsMarkup(activeWizard, completed) {
  const progress = `${completed.length}/${activeWizard.length}`;
  const nextStep = getWizardStep(state.wizardStep + 1);
  const metrics = [
    ["已确认", progress, "形成第一版经营边界"],
    ["当前路线", stageText(state.dna.merchantStage), "决定首单先跑哪条主线"],
    ["下一步", nextStep ? onboardingPhaseLabel(nextStep.field) : "进入工作舱", "继续补齐首单闭环"],
    ["高风险动作", "确认中心", "真实执行前必须人工确认"],
  ];
  return metrics
    .map(
      ([label, value, detail]) => `
        <article>
          <span>${escapeHtml(label)}</span>
          <strong>${escapeHtml(value)}</strong>
          <small>${escapeHtml(detail)}</small>
        </article>
      `,
    )
    .join("");
}

