function renderWizard() {
  clampWizardStep();
  const current = getWizardStep();
  const total = getWizardLength();
  document.querySelector("#wizardStepLabel").textContent = `第 ${state.wizardStep + 1}/${total} 步`;
  document.querySelector("#wizardProgressBar").style.width = `${((state.wizardStep + 1) / total) * 100}%`;
  const selected = state.dna[current.field];
  document.querySelector("#wizardCard").innerHTML = `
    <h3>${current.title}</h3>
    <p>${current.reason}</p>
    <div class="wizard-options">
      ${current.options
        .map(
          ([value, label, detail]) => `
            <button class="choice ${selected === value ? "is-selected" : ""}" type="button" data-wizard-value="${value}">
              <span>
                <strong>${label}</strong>
                <small>${detail}</small>
              </span>
            </button>
          `,
        )
        .join("")}
    </div>
  `;
  renderWizardManualActions(current.field);
}

function renderOnboarding() {
  clampWizardStep();
  const current = getWizardStep();
  if (!current) return;
  const profile = getLandingProfile();
  const selected = state.dna[current.field];
  const taskMeta = getOnboardingTaskMeta(current.field);
  const total = getWizardLength();
  document.querySelector("#onboardingEyebrow").textContent = `${profile.title} · 自动化向导`;
  document.querySelector("#onboardingTitle").textContent = profile.entry;
  document.querySelector("#onboardingSubtitle").textContent = onboardingRouteDescription();
  document.querySelector("#onboardingStepLabel").textContent = `第 ${state.wizardStep + 1}/${total} 步`;
  document.querySelector("#onboardingProgressBar").style.width = `${((state.wizardStep + 1) / total) * 100}%`;
  const exitButton = document.querySelector("#onboardingExit");
  if (exitButton) {
    const isLastStep = state.wizardStep >= total - 1;
    exitButton.textContent = isLastStep ? "进入 AI CEO 工作舱" : "继续完成首日边界";
    exitButton.disabled = !isLastStep;
  }
  document.querySelector("#onboardingCard").innerHTML = `
    <div class="onboarding-path-rail onboarding-lite-path" aria-label="当前向导路线">
      ${onboardingPathRailMarkup()}
    </div>
    <div class="task-step-banner onboarding-lite-banner">
      <span>${onboardingPhaseLabel(current.field)}</span>
      <strong>${taskMeta.task}</strong>
    </div>
    ${onboardingChoiceContextMarkup(current, taskMeta)}
    <div class="onboarding-lite-safety" aria-label="首日安全边界">
      ${onboardingLightSafetyMarkup()}
    </div>
    <div class="onboarding-decision-head">
      <div>
        <span class="eyebrow">当前决策</span>
        <h3>${current.title}</h3>
      </div>
      <small>不确定就先用推荐项，后面可在设置里改。</small>
    </div>
    <p class="onboarding-reason">${current.reason}</p>
    <div class="wizard-options">
      ${current.options
        .map(
          ([value, label, detail], index) => `
            <button class="choice ${selected === value ? "is-selected" : ""}" type="button" data-onboarding-value="${value}">
              <span>
                <strong>${label}</strong>
                <small>${detail}</small>
              </span>
              <em>${selected === value ? "已选" : index === 0 ? "推荐" : ""}</em>
            </button>
          `,
        )
        .join("")}
    </div>
  `;
  document.querySelector("#onboardingNext").textContent =
    current.field === "finish"
      ? selected === "review"
        ? "进入规则中心再检查"
        : "进入 AI CEO 工作台"
      : "下一步";
  renderManualActionsForField(current.field, "#onboardingManualActions");
  renderOnboardingSummary();
}

function manualKeysForField(field) {
  if (field === "ebaySetup") {
    return {
      newbie: ["ebay_account", "seller_policies"],
      store_opened: ["ebay_oauth", "seller_policies"],
      has_orders: ["ebay_oauth"],
      multi_store: ["ebay_oauth", "team_permissions"],
    }[state.dna.merchantStage] || ["seller_policies"];
  }
  const actionsByField = {
    ebayApiMode: ["ebay_oauth"],
    feeInsightMode: ["fee_authorization"],
    fulfillmentMode: ["fulfillment_setup"],
    sourceApiMode: ["source_api_binding", "source_order_rules"],
    returnPolicy: ["seller_policies"],
    mediaMode: ["media_review"],
    tone: ["service_tone"],
    permissionLevel: state.dna.merchantStage === "multi_store" ? ["service_tone", "team_permissions"] : ["service_tone"],
  };
  return actionsByField[field] || [];
}

function renderManualActionsForField(field, targetSelector) {
  const keys = manualKeysForField(field);
  const box = document.querySelector(targetSelector);
  if (!box) return;
  if (!keys.length) {
    box.classList.remove("is-active");
    box.innerHTML = "";
    return;
  }
  box.classList.add("is-active");
  box.innerHTML = `
    <strong>本步外部入口与确认项</strong>
    <span>需要你本人完成的平台动作或业务判断会给入口；捷境不会替你注册、真实授权、发布或承诺，只负责引导、预填和风险提醒。跳过后可以在「连接账号」继续补接。</span>
    <div class="manual-action-list">
      ${keys
        .map((key) => `<button class="manual-link-button" data-manual="${key}" type="button">${manualActionDetails[key]?.title || key}</button>`)
        .join("")}
    </div>
  `;
}

function renderWizardManualActions(field) {
  renderManualActionsForField(field, "#wizardManualActions");
}

