function renderSaasActivityCenter(view) {
  if (!view) return;
  const ctx = saasMerchantWorkbenchContext();
  const projectId = saasCurrentMerchantProjectId();
  const projectLabel =
    state.saasMerchantProjectStatus?.project?.product_name ||
    state.saasMerchantProjectStatus?.project?.sku ||
    "当前商品项目";
  const allReports = saasReportsForDisplay(state.saasReports || []);
  const reports = allReports.filter((record) => saasActivityReportMatchesCurrentProject(record, projectId));
  const historicalReports = allReports.filter((record) => !saasActivityReportMatchesCurrentProject(record, projectId));
  const allExecutions = Array.isArray(state.saasExecutionResults) ? state.saasExecutionResults : [];
  const executions = allExecutions.filter((record) => saasActivityExecutionMatchesCurrentProject(record, projectId));
  const historicalExecutions = allExecutions.filter((record) => !saasActivityExecutionMatchesCurrentProject(record, projectId));
  const confirmations = saasConfirmationsForDisplay(state.saasConfirmations || []);
  const pendingConfirmations = confirmations.filter((item) => item.status === "pending");
  const marketReport = reports.find((record) =>
    ["ai_ceo.market_research", "market.report", "market.data_packet"].includes(record.report_type || ""),
  ) || null;
  const listingReport = reports.find((record) =>
    ["listing.package", "product.listing"].includes(record.report_type || ""),
  ) || null;
  const canGenerateReport = state.saasConnected && ctx.hasPacket && isSaasModelConfigured();
  view.innerHTML = jiejingTrustedTemplate("activity.report_center")`
    <section class="panel full product-manager-module saas-real-activity-center" aria-label="真实 AI CEO 汇报">
      <header class="product-manager-header saas-real-listing-header">
        <div>
          <p class="eyebrow">工作记录</p>
          <h2>${projectId ? `${escapeHtml(projectLabel)}的工作记录` : "先打开一个商品项目"}</h2>
          <p class="section-note">默认只显示当前项目的报告、确认和平台结果。其他商品放在历史项目归档，不参与当前项目判断。</p>
        </div>
        <span class="pill ${reports.length ? "green" : "amber"}">${reports.length ? `${reports.length} 条报告` : "等待报告"}</span>
      </header>

      <section class="saas-readable-page-head saas-activity-readable-head" aria-label="AI CEO 汇报说明">
        <div>
          <span>当前项目</span>
          <strong>${reports.length ? "报告已经进入当前项目" : projectId ? "当前项目还没有报告" : "还没有选择商品项目"}</strong>
          <p>${reports.length ? "继续看报告结论、确认项和下一步动作。" : projectId ? "回到 AI CEO 或 Listing 继续当前项目。" : "先从 AI CEO 或 Listing 打开一个商品项目。"}</p>
        </div>
        <div class="saas-page-next-action">
          <b>${pendingConfirmations.length ? `${pendingConfirmations.length} 个确认项` : canGenerateReport ? "可以生成报告" : "去设置补连接"}</b>
          <small>连接和来源在设置</small>
        </div>
      </section>

      <div class="saas-activity-simple-actions">
        <button class="primary-action" type="button" data-saas-action="run-model-value-rehearsal" ${state.saasLoading || !canGenerateReport ? "disabled" : ""}>生成报告</button>
        <button class="secondary-action" type="button" data-global-flow-view="product">去 Listing</button>
        <button class="secondary-action" type="button" data-global-flow-view="connect">去设置</button>
        <button class="secondary-action" type="button" data-global-flow-view="confirm" ${pendingConfirmations.length ? "" : "disabled"}>看确认项</button>
      </div>

      <section class="saas-listing-report-grid" aria-label="核心报告">
        ${renderSaasListingFactoryReportCard(marketReport, "市场报告", { snapshot: true })}
        ${renderSaasListingFactoryReportCard(listingReport, "Listing 草稿", { snapshot: true })}
      </section>

      ${renderSaasActivityExecutionRecords(executions)}

      ${renderSaasMerchantWorkRecordIndex()}
      ${renderSaasHistoricalProjectArchive(historicalReports, historicalExecutions)}
    </section>
  `;
}

function renderActivities() {
  if (isSaasPublicMvpMode()) {
    renderSaasActivityCenter(document.querySelector("#view-activity"));
    return;
  }
  const project = getActiveProject();
  const allActivities = visibleActivitiesForProject(project);
  const visibleActivities = filteredActivitiesForProject(project);
  const pill = document.querySelector("#activityProjectPill");
  if (pill) pill.textContent = `当前项目：${project.title}`;
  renderProjectPickers();
  renderActivityFilters(project);
  renderActivityCommandCenter(project, allActivities, visibleActivities);
  renderTaskSplitStatusBoard(project);
  renderReadinessScoreBoard();
  renderRuntimeBridgePanel();
  renderSaasBackendPanel();
  renderProjectArchiveCard();
  if (!visibleActivities.includes(activities[activeEvidenceIndex]) && visibleActivities[0]) {
    activeEvidenceIndex = activities.indexOf(visibleActivities[0]);
  }
  document.querySelector("#activityList").innerHTML = visibleActivities
    .map(
      (item, index) => {
        const report = getActivityReport(item);
        const sectionCount = report.sections?.length || 0;
        const boardCount = report.boards?.length || 0;
        const activityIndex = activities.indexOf(item);
        return `
        <article class="activity-row activity-report-row ${activityIndex === activeEvidenceIndex ? "is-previewing" : ""}" data-activity-index="${activityIndex}" role="button" tabindex="0" aria-label="预览${activityWorkType(item.role)}工作记录">
          <div class="activity-row-head">
            <span class="activity-role">${activityWorkType(item.role)}</span>
            <span class="pill ${activityStatusClass(item)}">${item.status}</span>
          </div>
          <strong class="activity-row-title">${item.title}</strong>
          <p class="activity-row-copy">${item.action}</p>
          <small class="activity-row-meta">${activitySourceLabel(item.role)} · 置信度 ${item.confidence} · ${item.sources.length} 个数据来源 · ${boardCount + sectionCount} 个汇报板块</small>
        </article>
      `;
      },
    )
      .join("") || `<article class="activity-row activity-report-row is-empty"><strong class="activity-row-title">当前筛选下没有汇报</strong><p class="activity-row-copy">换一个流程筛选，或者先从首页、产品刊登、素材工坊、批量铺货继续推进，新的输出会自动写入 AI 汇报中心。</p></article>`;
  renderEvidencePreview(activeEvidenceIndex);
}

function ensureSaasConfirmScaffold() {
  if (!isSaasPublicMvpMode()) return;
  const view = document.querySelector("#view-confirm");
  if (!view) return;
  const realWritesEnabled = state.saasEbayWriteAdapter?.real_platform_writes_enabled === true;
  view.innerHTML = jiejingTrustedTemplate("confirmation.center")`
    <section class="panel full saas-real-confirm-center" aria-label="真实确认中心">
      <div class="section-heading">
        <div>
          <p class="eyebrow">确认中心 · 真实状态</p>
          <h2>只承接高风险动作，不展示历史商品流程</h2>
          <p class="section-note">发布、付款、退款、改价、广告、政策和敏感客服承诺必须先停住；当前真实 eBay 写入${realWritesEnabled ? "已开启，但发布仍必须先预检并由商家确认" : "保持关闭"}。</p>
        </div>
        <span class="pill ${realWritesEnabled ? "amber" : "green"}">${realWritesEnabled ? "real writes on" : "real writes off"}</span>
      </div>
      <div id="confirmGrid" class="confirm-grid"></div>
    </section>
  `;
}

function renderConfirmations() {
  ensureSaasConfirmScaffold();
  if (isSaasPublicMvpMode()) {
    renderSaasConfirmPanel();
    const grid = document.querySelector("#confirmGrid");
    if (grid) grid.innerHTML = "";
    return;
  }
  const filtered = confirmations.filter(
    (card) =>
      state.confirmFilter === "all" ||
      (state.confirmFilter === "immediate" && shouldSurfaceImmediately(card)) ||
      card.risk === state.confirmFilter,
  );
  const displayCards =
    state.confirmFilter === "immediate"
      ? filtered.filter((card) => confirmCoreDisplayIds.includes(card.id))
      : filtered;
  const mergedCoreCount =
    state.confirmFilter === "immediate"
      ? Math.max(filtered.length - displayCards.length, 0)
      : 0;
  const hiddenNonCoreCount =
    state.confirmFilter === "immediate"
      ? confirmations.filter((card) => !shouldSurfaceImmediately(card)).length
      : 0;
  renderCurrentDecisionGuide(displayCards, mergedCoreCount, hiddenNonCoreCount);
  renderConfirmBoundaryMap(displayCards, mergedCoreCount, hiddenNonCoreCount);
  renderConfirmBridge(displayCards, mergedCoreCount, hiddenNonCoreCount);
  syncConfirmIntro();
  renderRuntimeConfirmPanel();
  renderSaasConfirmPanel();
  if (
    state.confirmFilter === "immediate" &&
    ["blocked", "pending", "published"].includes(state.publishFlow.status) &&
    shouldShowLegacyDemoControls()
  ) {
    document.querySelector("#confirmGrid").innerHTML = renderPublishConfirmationCard(getPublishDraft());
    return;
  }
  if (state.confirmFilter === "immediate") {
    document.querySelector("#confirmGrid").innerHTML = renderCoreConfirmSummary(
      visibleCoreConfirmations(true),
      mergedCoreCount,
      hiddenNonCoreCount,
    );
    return;
  }
  document.querySelector("#confirmGrid").innerHTML = displayCards
    .map((card) => {
      const savedRule = state.savedDecisionDefaults[card.id];
      const defaultRule = getConfirmationDefaultRule(card);
      const flowMeta = confirmationFlowMeta(card);
      const primaryLabel = savedRule ? "按默认继续" : "按推荐保存";
      const resultText = savedRule
        ? `已保存为默认配置：${savedRule.config}`
        : card.suggestion || "先按保守方案继续，缺资料就让 AI CEO 拆成更简单的问题。";
      return `
        <article class="confirm-card simple-confirm-card ${savedRule ? "is-saved-default" : ""}" data-confirm-id="${card.id}">
          <div class="confirm-card-top">
            <span class="pill ${savedRule ? "green" : pillClass(card.risk)}">${savedRule ? "已保存默认" : simpleRiskLabel(card)}</span>
            <small>${savedRule ? "同类按规则走" : shouldSurfaceImmediately(card) ? "核心经营动作" : "可自动推进或留痕"}</small>
          </div>
          <strong>${card.title}</strong>
          <div class="confirm-card-flow">
            <span>来自：${escapeHtml(flowMeta.source)}</span>
            <span>影响：${escapeHtml(flowMeta.impact)}</span>
          </div>
          <div class="decision-default">
            <span>推荐你选</span>
            <strong>${cleanDefaultAction(card.defaultAction)}</strong>
          </div>
          <div class="saved-rule-strip ${savedRule ? "is-active" : ""}">
            <span>${savedRule ? "已保存默认配置" : "确认一次后默认配置"}</span>
            <p>${
              savedRule
                ? `${escapeHtml(savedRule.ruleTitle)} · ${escapeHtml(savedRule.savedAt)}。${escapeHtml(savedRule.config)}`
                : `${escapeHtml(defaultRule.scope)}同类事项以后按这条规则走；金额、账号、真实发布、退款、广告、授权或平台政策变化时再提醒。`
            }</p>
          </div>
          <p class="confirm-card-result">${resultText}</p>
          <div class="confirm-card-after">
            <span>确认后</span>
            <p>${escapeHtml(flowMeta.after)}</p>
          </div>
          <details class="confirm-detail">
            <summary>为什么要我确认？</summary>
            <p>${card.reason}</p>
            <small>依据：${card.evidence}</small>
          </details>
          <div class="button-row">
            <button class="secondary-action" data-action="unsure">我看不懂</button>
            <button class="primary-action" data-action="approve">${primaryLabel}</button>
          </div>
        </article>
      `;
    })
    .join("") + (mergedCoreCount
      ? `
        <article class="confirm-card simple-confirm-card confirm-merged-card">
          <span class="pill green">已归并</span>
          <strong>${mergedCoreCount} 个核心细节并入默认规则</strong>
          <p class="confirm-card-result">素材方向、客服草稿、物流提醒和广告建议不会消失；它们按默认规则归并处理。资金相关、真实发布、退款、广告花费、客服发送或明确承诺仍会重新提醒。</p>
        </article>
      `
      : "") + (hiddenNonCoreCount
      ? `
        <article class="confirm-card simple-confirm-card auto-confirm-card">
          <span class="pill green">自动推进</span>
          <strong>${hiddenNonCoreCount} 项非核心事项不再打扰你</strong>
        <p class="confirm-card-result">素材方向、补资料提醒、普通草稿和过程留档会由 AI CEO 继续推进并写入工作记录；只有资金相关、真实发布、退款、广告预算、客服发送或明确承诺才需要你点头。</p>
        </article>
      `
      : "") || `<article class="confirm-card simple-confirm-card"><span class="pill green">已清空</span><strong>现在没有需要你决定的核心事项</strong><p class="confirm-card-result">${permissionModeDetail().hint}</p></article>`;
}

function renderPermissionPolicy() {
  const detail = permissionModeDetail();
  document
    .querySelectorAll("[data-permission-mode]")
    .forEach((button) => button.classList.toggle("is-active", button.dataset.permissionMode === state.dna.permissionLevel));
  const pill = document.querySelector("#confirmModePill");
  if (pill) pill.textContent = detail.pill;
}

function logisticsStage(item) {
  const status = String(item?.status || "");
  if (status.includes("派送失败")) {
    return {
      lane: "派送异常",
      due: "买家已催促",
      action: "先核对地址和承运商异常；退款、重发或补偿必须送确认中心。",
    };
  }
  if (status.includes("退货")) {
    return {
      lane: "退货中",
      due: "今日处理",
      action: "整理退货原因、订单利润和责任边界，不自动退款。",
    };
  }
  if (status.includes("待上传") || status.includes("待发货")) {
    return {
      lane: "待发货",
      due: "剩余 18 小时",
      action: "核对供应商或仓库是否已发货、是否已生成运单；不清楚时先保守回复。",
    };
  }
  if (status.includes("催单") || status.includes("未更新")) {
    return {
      lane: "物流异常",
      due: "优先跟进",
      action: "先查承运商节点，再给买家保守说明，不承诺具体到达日。",
    };
  }
  if (status.includes("已发货") || status.includes("妥投")) {
    return {
      lane: "正常",
      due: "可自动",
      action: "可自动发送 tracking 或妥投说明，并写入 AI 汇报。",
    };
  }
  return {
    lane: "处理中",
    due: "等待更新",
    action: "保持保守承诺，必要时送确认中心。",
  };
}

function conversationMatchesServiceFilter(item, filter = state.serviceFilter) {
  const text = `${item.title} ${item.intent} ${item.buyer} ${item.draft}`;
  if (filter === "pending") return item.risk !== "可自动";
  if (filter === "logistics") return /物流|发货|tracking|催发货|到货/i.test(text);
  if (filter === "refund") return /退款|退货|refund|return|case|纠纷|补偿/i.test(text);
  return true;
}

function renderServiceFilters() {
  document
    .querySelectorAll(".service-filter-row [data-service-filter]")
    .forEach((button) => {
      button.classList.toggle("is-active", button.dataset.serviceFilter === state.serviceFilter);
    });
}

function renderServiceKnowledgeSync() {
  const grid = document.querySelector("#serviceAgentGrid");
  if (!grid) return;
  const draft = getPublishDraft();
  const published = state.publishFlow.status === "published";
  const learnedLabel = published ? `${draft.titleCn} 商品档案` : "等待 Listing 商品档案";
  const learnedStatus = published ? "已学习" : "待同步";
  const publishNote = published
    ? `已接收 ${draft.titleCn} 的标题、规格、FAQ、退货边界和物流承诺。`
    : "产品刊登完成并通过确认后，商品档案会自动同步到客服。";
  grid.innerHTML = `
    <article class="${published ? "is-synced" : ""}">
      <span>${learnedStatus}</span>
      <strong>${escapeHtml(learnedLabel)}</strong>
      <p>${escapeHtml(publishNote)}</p>
    </article>
    <article>
      <span>可自动处理</span>
      <strong>规格、材质、是否含配件、tracking 查询</strong>
      <p>只要问题能从商品档案和物流状态回答，就不再反复打扰商家。</p>
    </article>
    <article>
      <span>必须停住</span>
      <strong>退款、补偿、差评、明确到货承诺</strong>
      <p>这些会影响钱、账号表现和买家预期，继续进入确认中心或人工接管。</p>
    </article>
    <article>
      <span>发布后接力</span>
      <strong>${published ? state.publishFlow.simulatedItemId : "等待发布结果"}</strong>
      <p>${published ? "后续有真实订单时，客服会按这个 Listing 档案接待买家。" : "正式版发布成功后会绑定真实 itemId 和 Listing URL。"}</p>
    </article>
  `;
}

function saasServiceTraceStateLabel(stateKey = "") {
  return {
    buyer_message: "买家原消息",
    ai_suggested: "AI 建议",
    merchant_edited: "商家已修改",
    sent: "已发送",
    simulated: "演练记录",
  }[String(stateKey || "")] || "客服记录";
}

function saasServiceTraceRecords() {
  const buyerActions = new Set(["buyer_message_send", "sensitive_buyer_commitment", "send_customer_reply", "sensitive_customer_reply"]);
  const confirmations = (Array.isArray(state.saasConfirmations) ? state.saasConfirmations : [])
    .filter((card) => buyerActions.has(String(card?.action_type || card?.item?.action_type || "")))
    .map((card) => {
      const item = card?.item && typeof card.item === "object" ? card.item : {};
      const explicitState = String(item.reply_state || item.customer_service_state || "");
      const stateKey = explicitState === "merchant_edited" ? "merchant_edited" : "ai_suggested";
      return {
        recordId: String(card.confirmation_id || "").replace(/[^A-Za-z0-9._:-]/g, "").slice(0, 160),
        stateKey,
        title: publicRuntimeText(card.title || item.title || "买家回复草稿").slice(0, 160),
        summary: publicRuntimeText(item.message_draft || item.reply_text || item.message || card.summary || "发送前等待商家核对事实和承诺。").slice(0, 320),
        occurredAt: publicRuntimeText(card.updated_at || card.created_at || "").slice(0, 80),
        targetView: "confirm",
      };
    });
  const executions = (Array.isArray(state.saasExecutionResults) ? state.saasExecutionResults : [])
    .filter((record) => buyerActions.has(String(record?.action_type || "")))
    .map((record) => {
      const result = record?.result && typeof record.result === "object" ? record.result : {};
      const platform = result.platform_result && typeof result.platform_result === "object" ? result.platform_result : {};
      const status = String(record.status || result.status || "").toLowerCase();
      const simulated = status === "simulated_no_platform_write" || result.simulated === true;
      const sent = !simulated && platform.message_sent === true && ["sent", "completed", "success"].includes(status);
      if (!simulated && !sent) return null;
      return {
        recordId: String(record.execution_id || "").replace(/[^A-Za-z0-9._:-]/g, "").slice(0, 160),
        stateKey: simulated ? "simulated" : "sent",
        title: simulated ? "客服演练" : "买家回复",
        summary: simulated ? "仅记录演练结果，没有向买家发送消息。" : "平台已确认消息发送成功。",
        occurredAt: publicRuntimeText(record.updated_at || record.created_at || "").slice(0, 80),
        targetView: "activity",
      };
    })
    .filter(Boolean);
  return [...confirmations, ...executions]
    .filter((item) => item.recordId)
    .sort((left, right) => String(right.occurredAt).localeCompare(String(left.occurredAt)))
    .slice(0, 30);
}

function renderSaasServiceTrace(records = saasServiceTraceRecords()) {
  const items = Array.isArray(records) ? records : [];
  const states = ["buyer_message", "ai_suggested", "merchant_edited", "sent", "simulated"];
  return `
    <section class="saas-activity-simple-list saas-service-trace" data-service-trace-contract="customer_service_trace_v1" aria-label="客服消息状态记录">
      <div class="saas-activity-simple-head">
        <div>
          <strong role="heading" aria-level="3">回复记录</strong>
          <p>草稿与发送结果分别保留。只有平台确认发送成功，才会显示“已发送”。</p>
        </div>
      </div>
      ${
        items.length
          ? `<details class="saas-confirm-safety-detail"><summary>回复状态说明</summary><div class="saas-service-lane-grid" aria-label="客服消息五种状态">
              ${states
                .map(
                  (stateKey) => `
                    <article>
                      <strong>${escapeHtml(saasServiceTraceStateLabel(stateKey))}</strong>
                      <p>${escapeHtml({
                        buyer_message: "从官方消息来源读取的买家原文。",
                        ai_suggested: "AI 已起草，等待商家核对。",
                        merchant_edited: "商家已修改，尚未发送。",
                        sent: "平台已返回发送成功证据。",
                        simulated: "演练记录，没有真实发送。",
                      }[stateKey])}</p>
                    </article>
                  `,
                )
                .join("")}
            </div></details>`
          : ""
      }
      <div class="saas-activity-simple-grid">
        ${
          items.length
            ? items
                .map(
                  (item) => `
                    <article data-service-trace-id="${escapeHtml(item.recordId)}" data-service-trace-state="${escapeHtml(item.stateKey)}">
                      <span>${escapeHtml(saasServiceTraceStateLabel(item.stateKey))}</span>
                      <strong>${escapeHtml(item.title)}</strong>
                      <p>${escapeHtml(item.summary)}</p>
                      <div class="button-row"><button class="secondary-action compact-action" type="button" data-global-flow-view="${escapeHtml(item.targetView)}">查看原记录</button></div>
                    </article>
                  `,
                )
                .join("")
            : `<article class="is-empty"><strong>还没有回复记录</strong><p>买家消息暂未接入。可先在 AI CEO 中整理回复草稿，核对后再处理；草稿不会自动发送。</p></article>`
        }
      </div>
    </section>
  `;
}

function saasPendingServiceConfirmations(cards = state.saasConfirmations || []) {
  const actions = new Set([
    "refund", "partial_refund", "refund_order", "replacement", "compensation",
    "buyer_message_send", "sensitive_buyer_commitment", "send_customer_reply", "sensitive_customer_reply",
  ]);
  return saasConfirmationsForDisplay(cards).filter((card) =>
    card.status === "pending" && actions.has(String(card.action_type || card.item?.action_type || "")),
  );
}

function renderSaasServiceCenter(view = document.querySelector("#view-service")) {
  if (!view) return;
  const ctx = saasMerchantWorkbenchContext();
  const pendingServiceConfirmations = saasPendingServiceConfirmations();
  const opsSnapshot = saasEbayOperationsSnapshot(ctx.packetBody || {});
  const hasOfficialOrders = ctx.presentKeys.includes("orders_and_fulfillment") && opsSnapshot.orderCount > 0;
  const hasListings = ctx.presentKeys.includes("inventory_and_offers") && opsSnapshot.listingCount > 0;
  const serviceTraceRecords = saasServiceTraceRecords();
  const hasOfficialBuyerMessages = serviceTraceRecords.some((item) => item.stateKey === "buyer_message");
  const serviceNextAction = !ctx.connection
    ? "连接店铺后可查看官方订单；买家消息暂未接入，当前可整理回复草稿并由你审核。"
    : hasOfficialOrders
      ? "已有订单快照，可核对履约资料"
      : ctx.presentKeys.includes("orders_and_fulfillment") ? "最近同步未包含订单" : "订单数据尚未读取";
  const serviceActionButtons = (() => {
    if (!ctx.connection) {
      return '<button class="primary-action" type="button" data-global-flow-view="connect">连接 eBay 店铺</button>';
    }
    if (pendingServiceConfirmations.length) {
      return `<button class="primary-action" type="button" data-global-flow-view="confirm">查看 ${pendingServiceConfirmations.length} 项待确认</button>`;
    }
    return '<button class="secondary-action" type="button" data-global-flow-view="cockpit">前往 AI CEO 起草回复</button>';
  })();
  view.innerHTML = jiejingTrustedTemplate("service.order_center")`
      <section class="panel full saas-real-service-center" data-saas-service-daily-workbench="service_order_plain_workbench_v2" aria-label="客服与订单工作台">
      <header class="product-manager-header saas-real-listing-header">
        <div>
          <p class="eyebrow">客服与订单</p>
          <h2>今日客服与订单</h2>
          <p class="section-note">买家消息、订单状态和回复草稿集中处理；退款、补偿、重发、地址修改和明确到货日会进入确认中心。</p>
        </div>
        <span class="pill ${hasOfficialBuyerMessages ? "green" : "amber"}">${hasOfficialBuyerMessages ? "有买家消息" : "没有官方消息"}</span>
      </header>

      <section class="saas-readable-page-head saas-service-readable-head" aria-label="客服与订单说明">
        <div>
          <strong role="heading" aria-level="2">客服与订单</strong>
          <p>依据商品资料和订单状态准备回复。退款、补偿、重发、地址修改、明确到货日和敏感承诺需单独确认。</p>
        </div>
        <div class="saas-page-next-action">
          <b>${escapeHtml(serviceNextAction)}</b>
          <small>${ctx.lastSync ? `最近同步：${escapeHtml(saasTimestampLabel(ctx.lastSync))}` : "尚无同步时间"} · 买家消息暂未接入</small>
        </div>
      </section>
      ${renderSaasModuleAiGoalStrip("service")}

      <section class="saas-service-simple-workspace" aria-label="客服与订单工作区">
        <article class="${hasOfficialOrders ? "is-green" : "is-empty"}">
          <span>订单快照</span>
          <strong>${hasOfficialOrders ? "可查看已同步订单资料" : ctx.presentKeys.includes("orders_and_fulfillment") ? "最近同步没有订单" : "尚无订单数据"}</strong>
          <p>${hasOfficialOrders ? `${escapeHtml(saasCompactValue(opsSnapshot.orderLabel))} · ${escapeHtml(saasCompactValue(opsSnapshot.fulfillment, "按订单状态核对"))}` : "订单以最近一次同步为准，不代表当前待回复数量。"}</p>
        </article>
        <article class="${hasListings ? "is-green" : "is-amber"}">
          <span>回复草稿</span>
          <strong>${hasListings ? "商品档案可供参考" : "先准备商品与订单信息"}</strong>
          <p>在 AI CEO 中提供买家问题并整理草稿。发送前请核对商品事实、订单情况与承诺。</p>
        </article>
        <article class="${pendingServiceConfirmations.length ? "is-amber" : "is-green"}">
          <span>确认事项</span>
          <strong>${pendingServiceConfirmations.length}</strong>
          <p>退款、补偿、重发、地址修改、明确到货日和敏感承诺会进入确认中心。</p>
        </article>
      </section>

      ${renderSaasServiceTrace(serviceTraceRecords)}

      <div class="saas-service-action-strip">
        <strong>下一步</strong>
        <div>
          ${serviceActionButtons}
        </div>
      </div>
    </section>
  `;
}

function renderConversations() {
  if (isSaasPublicMvpMode() && state.view === "service") {
    renderSaasServiceCenter();
    return;
  }
  const list = document.querySelector("#conversationList");
  if (!list) return;
  renderServiceKnowledgeSync();
  renderServiceKnowledgePanel();
  const filteredConversations = conversations
    .map((item, index) => ({ item, index }))
    .filter(({ item }) => conversationMatchesServiceFilter(item));
  if (!filteredConversations.some(({ index }) => index === state.activeConversation)) {
    state.activeConversation = filteredConversations[0]?.index ?? 0;
  }
  renderServiceFilters();
  list.innerHTML = filteredConversations.length
    ? filteredConversations
    .map(
      ({ item, index }) => `
        <button class="conversation-item ${index === state.activeConversation ? "is-active" : ""}" data-conversation="${index}">
          <span class="queue-meta">${escapeHtml(item.channel)} · ${escapeHtml(item.order)}</span>
          <strong>${escapeHtml(item.title)}</strong>
          <p>${escapeHtml(item.buyer)}</p>
          <div class="queue-footer">
            <small>${escapeHtml(item.buyerName)} · ${escapeHtml(item.intent)}</small>
            <span class="pill ${pillClass(item.risk)}">${escapeHtml(item.risk)}</span>
          </div>
        </button>
      `,
    )
    .join("")
    : `<article class="conversation-empty"><strong>这个筛选下没有消息</strong><p>AI CEO 会继续监控新消息；有退款、物流异常或需要人工判断时再送到这里。</p></article>`;
  const active = conversations[state.activeConversation];
  if (!active) return;
  const relatedOrderIndex = logisticsItems.findIndex((item) => item.order === active.order);
  if (relatedOrderIndex >= 0) state.activeLogistics = relatedOrderIndex;
  document.querySelector("#conversationTitle").textContent = active.title;
  document.querySelector("#conversationRisk").textContent = active.risk;
  document.querySelector("#conversationRisk").className = `pill ${pillClass(active.risk)}`;
  document.querySelector("#handoffMode").textContent =
    active.risk === "可自动" ? "AI 自动接待中" : "等待人工接管";
  document.querySelector("#handoffMode").className =
    `pill ${active.risk === "可自动" ? "green" : "amber"}`;
  document.querySelector("#buyerThread").innerHTML = `
    <div class="thread-bubble buyer">
      <span>买家 · ${escapeHtml(active.buyerName)}</span>
      <p>${escapeHtml(active.buyer)}</p>
      <small>${escapeHtml(active.order)} · ${escapeHtml(active.intent)}</small>
    </div>
    <div class="thread-bubble ai">
      <span>AI CEO 草稿</span>
      <p>${escapeHtml(active.draft)}</p>
      <small>${escapeHtml(active.boundary)}</small>
    </div>
  `;
  document.querySelector("#replyDraft").value = active.draft;
}

function renderLogistics() {
  if (isSaasPublicMvpMode() && state.view === "service") return;
  const list = document.querySelector("#logisticsList");
  if (!list) return;
  const query = state.logisticsQuery.trim().toLowerCase();
  const filteredItems = logisticsItems
    .map((item, index) => ({ ...item, index }))
    .filter((item) => {
    if (!query) return true;
    return [item.order, item.buyer, item.status, item.tracking, item.promise, item.risk, logisticsStage(item).lane]
      .join(" ")
      .toLowerCase()
      .includes(query);
  });
  const meta = document.querySelector("#logisticsSearchMeta");
  if (meta) {
    meta.textContent = query
      ? `找到 ${filteredItems.length} 条订单，关键词：${state.logisticsQuery}`
      : `显示全部 ${logisticsItems.length} 条订单`;
  }
  const activeOrder = logisticsItems[state.activeLogistics] || logisticsItems[0];
  const activeStage = logisticsStage(activeOrder);
  const activeSummary = document.querySelector("#activeOrderSummary");
  if (activeSummary && activeOrder) {
    activeSummary.innerHTML = `
      <span class="pill ${pillClass(activeOrder.risk)}">${escapeHtml(activeOrder.risk)}</span>
      <strong>订单 ${escapeHtml(activeOrder.order)} · ${escapeHtml(activeOrder.buyer)}</strong>
      <p>${escapeHtml(activeOrder.status)} · Tracking：${escapeHtml(activeOrder.tracking)}</p>
      <div class="order-timeline">
        <i class="is-done"></i><i class="${activeStage.lane !== "待发货" ? "is-done" : ""}"></i><i class="${activeStage.lane === "正常" ? "is-done" : ""}"></i>
      </div>
      <small>${escapeHtml(activeStage.lane)} · ${escapeHtml(activeStage.due)} · ${escapeHtml(activeStage.action)}</small>
    `;
  }
  if (!filteredItems.length) {
    list.innerHTML = `
      <article class="logistics-empty">
        <strong>没有找到匹配订单</strong>
        <p>可以按订单号、买家姓名、tracking、物流状态或风险等级搜索。</p>
      </article>
    `;
    return;
  }
  list.innerHTML = filteredItems
    .map(
      (item) => `
        <button class="logistics-row ${item.index === state.activeLogistics ? "is-active" : ""}" data-logistics="${item.index}" type="button">
          <div>
            <span class="queue-meta">${escapeHtml(logisticsStage(item).lane)} · ${escapeHtml(logisticsStage(item).due)}</span>
            <strong>订单 ${escapeHtml(item.order)} · ${escapeHtml(item.buyer)}</strong>
            <p>${escapeHtml(item.status)}</p>
            <small>Tracking：${escapeHtml(item.tracking)} · ${escapeHtml(item.promise)}</small>
          </div>
          <span class="pill ${pillClass(item.risk)}">${escapeHtml(item.risk)}</span>
        </button>
      `,
    )
    .join("");
}

