async function copySaasEbayCallbackUrl() {
  const callbackUrl = currentSaasEbayCallbackUrl();
  try {
    if (navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(callbackUrl);
    } else {
      const textarea = document.createElement("textarea");
      textarea.value = callbackUrl;
      textarea.setAttribute("readonly", "readonly");
      textarea.style.position = "fixed";
      textarea.style.opacity = "0";
      document.body.appendChild(textarea);
      textarea.select();
      document.execCommand("copy");
      textarea.remove();
    }
    showActionToast("已复制 eBay 官方连接返回地址。");
  } catch (error) {
    console.warn("copySaasEbayCallbackUrl failed", error);
    showActionToast("复制失败，请手动复制设置页里的官方连接返回地址。");
  }
}
