function saasAccountHealthSnapshot() {
  return state.saasAccountHealth && typeof state.saasAccountHealth === "object" ? state.saasAccountHealth : {};
}

function saasMerchantSafeSettingsText(value = "", fallback = "状态待更新") {
  const text = publicRuntimeText(value)
    .replace(/\bpacket\b/gi, "店铺资料")
    .replace(/\bprovider\b/gi, "服务商")
    .replace(/\bpreflight\b/gi, "发布体检")
    .trim();
  if (!text) return fallback;
  return /\b(token|secret_ref|webhook|quota)\b|BYOK|API key|后台排查|后台证据/i.test(text)
    ? fallback
    : text;
}

function saasAccountHealthTone(health = saasAccountHealthSnapshot()) {
  const severity = String(health.severity || "").toLowerCase();
  const status = String(health.status || "").toLowerCase();
  if (severity === "green" || status === "normal") return "green";
  if (severity === "red" || ["unknown", "restricted", "suspended", "payout_hold", "quota_limited"].includes(status)) return "red";
  return "amber";
}

function saasAccountHealthMerchantText(value = "", fallback = "状态待更新") {
  // Translate known diagnostic messages for this view only; keep source evidence intact.
  const text = saasMerchantSafeSettingsText(value, fallback);
  const messages = new Map([
    ["eBay 拒绝了最近一次正式发布并暂时限制账号；KYC 已清除也不代表该限制已解除，Offer 仍未公开，捷境已暂停后续真实写入。",
      "eBay 最近拒绝了商品发布，账号的发布限制尚未解除。完成身份核验不代表可以恢复发布；商品仍未公开，相关店铺操作已暂停。"],
    ["收到 eBay 明确的限制解除通知后，将该通知作为解除证据交给捷境；仅 KYC=clear 或普通只读同步不会解除门禁。",
      "请提供 eBay 明确解除本次账号限制的通知。仅完成身份核验或更新店铺数据，不能解除发布限制。"],
    ["捷境核验证据晚于最近一次 25019 拒绝后，才重新生成精确发布确认单；旧 Offer、Listing 草稿和素材无需重建。",
      "解除限制的通知必须晚于最近一次发布被拒绝的时间。捷境核对后再生成新的发布确认单；原有商品草稿和素材无需重建，正式发布仍需你确认。"],
  ]);
  return messages.get(text) || text;
}

function saasSellerOnboardingGuidance(health = saasAccountHealthSnapshot()) {
  const evidence = health.evidence_package && typeof health.evidence_package === "object" ? health.evidence_package : {};
  const stage = String(health.onboarding_stage || "").toLowerCase();
  const sellerStatus = String(evidence.seller_account_status || health.status || "")
    .toLowerCase()
    .replace(/[\s-]+/g, "_");
  if (stage === "seller_registration_required" || sellerStatus === "registration_incomplete") {
    return {
      key: "seller_registration_required",
      tone: "red",
      title: "先完成 eBay 卖家注册",
      detail: "当前 eBay 授权与 Token 续期正常，无需重新授权。请在 eBay 官方页面完成身份、注册地址和收款验证，完成后回到 Seller Hub。",
      next: "回来后只刷新官方只读数据；若仍缺政策，再按下一条提示补齐 Business Policies。",
    };
  }
  const missingResources = Array.isArray(evidence.missing_resource_keys) ? evidence.missing_resource_keys : [];
  if (
    stage === "business_policies_required" ||
    (evidence.business_policies_present === false && missingResources.includes("account_business_policies"))
  ) {
    return {
      key: "business_policies_required",
      tone: "amber",
      title: "在 Seller Hub 启用 Business Policies",
      detail: "建立付款、配送和退货三类政策，让 Listing 草稿可以引用真实店铺规则。无需重新授权，也不要在捷境里填写 eBay 密码。",
      next: "完成后刷新官方只读数据，捷境会继续发布体检；真实发布仍需决策中心确认。",
    };
  }
  return null;
}

function renderSaasAccountHealthTrafficPanel({ compact = false } = {}) {
  const health = saasAccountHealthSnapshot();
  const evidence = health.evidence_package && typeof health.evidence_package === "object" ? health.evidence_package : {};
  const guardrails = health.guardrails && typeof health.guardrails === "object" ? health.guardrails : {};
  const allowed = Array.isArray(guardrails.allowed_incident_actions) ? guardrails.allowed_incident_actions : [];
  const blocked = Array.isArray(guardrails.blocked_real_actions) ? guardrails.blocked_real_actions : [];
  const tone = saasAccountHealthTone(health);
  const realWriteTone = health.can_execute_real_writes && !health.incident_mode ? "green" : "red";
  const rows = [
    {
      label: "账号状态",
      value: health.label || "状态未知",
      detail: health.summary || "缺账号健康快照时默认事故模式。",
      tone,
    },
    {
      label: "店铺资料",
      value: evidence.official_packet_present ? "已更新" : "等待更新",
      detail: evidence.official_packet_present ? "来自 eBay 官方只读资料" : "缺少店铺资料或官方同步结果",
      tone: evidence.official_packet_present ? "green" : "amber",
    },
    {
      label: "资金/限制",
      value: evidence.payout_status || evidence.seller_account_status || health.status || "unknown",
      detail: `${Number(evidence.restriction_count || 0)} 条限制 / ${Number((evidence.recent_platform_errors || []).length || 0)} 条近期平台错误`,
      tone: health.incident_mode ? "red" : evidence.restriction_count ? "amber" : "green",
    },
    {
      label: "真实动作",
      value: health.can_execute_real_writes && !health.incident_mode ? "可继续体检" : "暂停写入",
      detail: health.incident_mode
        ? `允许 ${allowed.join(" / ") || "诊断 / 证据包 / 只读同步"}；停止 ${blocked.slice(0, 4).join(" / ") || "真实发布 / 改价 / 库存 / 退款"}。`
        : "发布、改价、库存、退款、广告和政策仍必须进入决策中心。",
      tone: realWriteTone,
    },
  ];
  return `
    <section class="saas-account-health-traffic ${compact ? "is-compact" : ""}" aria-label="账号健康红黄绿报告">
      <div class="saas-account-health-traffic-head">
        <div>
          <span>账号健康 / 事故模式</span>
          <strong>${escapeHtml(health.incident_mode ? "真实写入已暂停" : health.label || "等待账号健康快照")}</strong>
          <p>${escapeHtml(health.summary || "首次执行真实动作前，先更新 eBay 官方只读资料并检查账号状态。资料不足时不会进入真实发布。")}</p>
        </div>
        <span class="pill ${escapeHtml(tone)}">${health.incident_mode ? "事故模式" : "红黄绿报告"}</span>
      </div>
      <div class="saas-account-health-traffic-grid">
        ${rows
          .map(
            (row) => `
              <article class="is-${escapeHtml(row.tone || "amber")}">
                <span>${escapeHtml(row.label)}</span>
                <strong>${escapeHtml(row.value)}</strong>
                <small>${escapeHtml(row.detail)}</small>
              </article>
            `,
          )
          .join("")}
      </div>
    </section>
  `;
}

